let dgCountryIso3Map = null;
function dgCountryIso3(name) {
  if (!dgCountryIso3Map) {
    dgCountryIso3Map = {};
    DG_COUNTRY_ISO3.forEach(function(e) { dgCountryIso3Map[e[0]] = e[1]; });
  }
  return dgCountryIso3Map[name] || null;
}

function dgResolveCountry(raw) {
  const name = String(raw || "").trim();
  if (!name) return null;
  const key = name.toLowerCase();
  if (DG_WORLD_MAP_INDEX.has(key)) return DG_WORLD_MAP_INDEX.get(key);
  if (DG_COUNTRY_ALIASES[key]) return DG_COUNTRY_ALIASES[key];
  return null;
}

const DG_WORLD_MAP_INDEX = new Map(DG_WORLD_COUNTRIES.map(c => [c[0].toLowerCase(), c[0]]));

// ── Colour helpers: small hex/rgb utilities shared by the theme-aware map
// scale below. Kept local to this module — no new global surface. ──
function dgHexToRgb(hex) {
  hex = String(hex || '').replace('#', '').trim();
  if (hex.length === 3) hex = hex.split('').map(c => c + c).join('');
  const n = parseInt(hex, 16);
  if (isNaN(n)) return [37, 99, 235]; // safe fallback: brand blue
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}
function dgMixRgb(a, b, t) {
  return [
    Math.round(a[0] + (b[0] - a[0]) * t),
    Math.round(a[1] + (b[1] - a[1]) * t),
    Math.round(a[2] + (b[2] - a[2]) * t)
  ];
}
function dgRgbToCss(rgb) { return `rgb(${rgb[0]},${rgb[1]},${rgb[2]})`; }

// Theme-aware sequential scale: the map now RESPECTS whatever colour the
// person has actually chosen elsewhere in the app — the active palette
// scheme's lead swatch, or their Custom/Same Colour pick when "same colour"
// mode is on — instead of being hard-locked to one fixed blue regardless of
// what's selected. Three anchor tones (light tint → the chosen colour itself
// → a deepened shade of it) give a proper enterprise choropleth ramp that
// still reads as "this person's chart", every time, in every palette.
function dgWorldMapBaseHex() {
  if (dgState.sameColorMode && dgState.sameColor) return dgState.sameColor;
  const scheme = dgCurrentScheme();
  return (scheme && scheme[0]) || '#2563EB';
}
function dgWorldMapScaleStops() {
  const base = dgHexToRgb(dgWorldMapBaseHex());
  const white = [255, 255, 255];
  const black = [0, 0, 0];
  return {
    light: dgMixRgb(white, base, 0.16),
    mid: base,
    deep: dgMixRgb(base, black, 0.42)
  };
}
function dgWorldMapColor(t) {
  t = Math.max(0, Math.min(1, t));
  const { light, mid, deep } = dgWorldMapScaleStops();
  let a, b, f;
  if (t < 0.5) { a = light; b = mid; f = t / 0.5; }
  else { a = mid; b = deep; f = (t - 0.5) / 0.5; }
  return dgRgbToCss(dgMixRgb(a, b, f));
}

// Resolves each data row against the map, computes the min/max for the colour
// scale, and returns { rows, matched, unmatched, min, max } — `rows` is a
// COPY (never mutates dgState.rows) with .color set to its choropleth colour
// and .canonical set to the matched country name, sorted highest value first
// so the shared legend renderer (dgLayoutLegend/dgDrawLegend) shows the
// biggest countries before truncating to "+N more".
function dgAssignWorldMapColors(rows) {
  const resolved = rows.map(r => ({ ...r, canonical: dgResolveCountry(r.label) }));
  const matched = resolved.filter(r => r.canonical);
  const unmatched = resolved.filter(r => !r.canonical);
  const vals = matched.map(r => r.value);
  const min = vals.length ? Math.min(...vals) : 0;
  const max = vals.length ? Math.max(...vals) : 0;
  matched.sort((a, b) => b.value - a.value);
  matched.forEach(r => {
    const t = max > min ? (r.value - min) / (max - min) : (vals.length ? 1 : 0);
    r.color = dgWorldMapColor(t);
  });
  // Unmatched rows still need a .color for the shared legend renderer (dgDrawLegend reads
  // it.r.color directly) — a visible slate grey (not the old near-white tone) so an
  // unmatched row still reads clearly in the legend list, not just on the map itself.
  unmatched.forEach(r => { r.color = '#94a3b8'; });
  return { rows: matched.concat(unmatched), matched, unmatched, min, max };
}

