// Flattened lookup: normalised state/province name → list of countries it could belong to (almost
// always just one; a few names like "Punjab" legitimately exist in more than one, so
// dgDetectStatesCountry below resolves those by which country the REST of the sheet points to).
const DG_STATE_COUNTRY_INDEX = {};
DG_STATE_COUNTRY_GROUPS.forEach(function(group) {
  const country = group[0];
  group[1].forEach(function(state) {
    const key = state.trim().toLowerCase();
    if (!DG_STATE_COUNTRY_INDEX[key]) DG_STATE_COUNTRY_INDEX[key] = [];
    DG_STATE_COUNTRY_INDEX[key].push(country);
  });
});

// Given the same {label, value} rows Map mode already works with, guesses which single country
// the data's state/province names belong to. Returns null when too few rows are recognisable
// state names, or when no one country clearly dominates the matches (e.g. a genuinely mixed or
// ambiguous sheet) — callers should silently fall back to ordinary "no match" handling in that case.
function dgDetectStatesCountry(rows) {
  if (!Array.isArray(rows) || !rows.length) return null;
  const tally = {};
  let consideredRows = 0;
  rows.forEach(function(r) {
    const key = String((r && r.label) || '').trim().toLowerCase();
    const countries = DG_STATE_COUNTRY_INDEX[key];
    if (!countries || !countries.length) return;
    consideredRows++;
    countries.forEach(function(c) { tally[c] = (tally[c] || 0) + 1; });
  });
  if (!consideredRows) return null;
  let best = null, bestCount = 0;
  Object.keys(tally).forEach(function(c) { if (tally[c] > bestCount) { bestCount = tally[c]; best = c; } });
  if (!best) return null;
  // Require a clear majority of the recognised rows to point at this one country — guards
  // against a handful of ambiguous names (shared across countries) tipping the guess the wrong
  // way. A single recognised row is accepted on its own since there's nothing to disagree with it.
  const threshold = consideredRows <= 1 ? 1 : Math.ceil(consideredRows * 0.5);
  if (bestCount < threshold) return null;
  return { country: best, matched: bestCount, consideredRows: consideredRows, totalRows: rows.length };
}

// ── Map Explorer: real, zoomable OpenStreetMap view of the current Map-mode data ──────────
// The choropleth above is a static offline SVG shape (deliberately — no map tile server, no
// network call). This is the opposite: a genuine Leaflet map on real OpenStreetMap tiles (free,
// no API key) so someone can pan and zoom in for country/city-level detail — "dive deeper" —
// with a marker per matched country, sized/coloured the same way the choropleth legend is.
const dgMapx = { map: null, markerLayer: null, basemapLayer: null, basemap: 'dark', statesOn: false, statesLayer: null, statesCache: {} };

const DG_MAPX_BASEMAPS = {
  // CARTO's free "dark matter" tiles — no API key, matches the app's dark theme.
  dark: { url: 'https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', attribution: '© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors © <a href="https://carto.com/attributions" target="_blank" rel="noopener">CARTO</a>', subdomains: 'abcd', maxZoom: 19 },
  // Standard OpenStreetMap tiles — no API key.
  streets: { url: 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', attribution: '© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors', subdomains: 'abc', maxZoom: 19 }
};

function dgMapExplorerEnsureMap() {
  if (dgMapx.map || typeof L === 'undefined') return;
  const el = document.getElementById('dgLeafletMap');
  if (!el) return;
  dgMapx.map = L.map(el, { worldCopyJump: true, minZoom: 2 }).setView([20, 0], 2);
  dgMapExplorerSetBasemap(dgMapx.basemap || 'dark');
  dgMapx.markerLayer = L.layerGroup().addTo(dgMapx.map);
}

function dgMapExplorerSetBasemap(which) {
  dgMapx.basemap = (which === 'streets') ? 'streets' : 'dark';
  const cfg = DG_MAPX_BASEMAPS[dgMapx.basemap];
  const darkBtn = document.getElementById('dgMapxBasemapDark');
  const streetsBtn = document.getElementById('dgMapxBasemapStreets');
  if (darkBtn) darkBtn.classList.toggle('active', dgMapx.basemap === 'dark');
  if (streetsBtn) streetsBtn.classList.toggle('active', dgMapx.basemap === 'streets');
  if (!dgMapx.map || typeof L === 'undefined') return;
  if (dgMapx.basemapLayer) dgMapx.map.removeLayer(dgMapx.basemapLayer);
  dgMapx.basemapLayer = L.tileLayer(cfg.url, { attribution: cfg.attribution, subdomains: cfg.subdomains, maxZoom: cfg.maxZoom, crossOrigin: 'anonymous' }).addTo(dgMapx.map);
}

// Pulls the same matched/coloured rows the choropleth legend uses (dgAssignWorldMapColors),
// looks each canonical country up in DG_COUNTRY_LATLNG, and plots one circle marker per match —
// radius scaled by value (bigger number = bigger circle), colour taken straight from the
// choropleth's own colour ramp so the two views always agree visually.
function dgRefreshMapExplorerMarkers() {
  if (!dgMapx.map || !dgMapx.markerLayer) return;
  dgMapx.markerLayer.clearLayers();
  const emptyState = document.getElementById('dgMapxEmptyState');
  const rows = (dgState && Array.isArray(dgState.rows)) ? dgState.rows : [];
  if (!rows.length) {
    if (emptyState) { emptyState.style.display = 'flex'; emptyState.textContent = 'Add data with a country column to see it plotted here.'; }
    return;
  }
  const result = dgAssignWorldMapColors(rows);
  const plottable = result.matched.filter(r => dgCountryLatLng(r.canonical));
  if (!plottable.length) {
    if (emptyState) { emptyState.style.display = 'flex'; emptyState.textContent = "None of the labels in this data matched a recognised country, so there's nothing to plot yet."; }
    return;
  }
  if (emptyState) emptyState.style.display = 'none';
  const numberFormat = (typeof dgGetOpts === 'function') ? (dgGetOpts().numberFormat || 'plain') : 'plain';
  const vals = plottable.map(r => r.value);
  const minV = Math.min.apply(null, vals), maxV = Math.max.apply(null, vals);
  const bounds = [];
  plottable.forEach(r => {
    const ll = dgCountryLatLng(r.canonical);
    const t = maxV > minV ? (r.value - minV) / (maxV - minV) : 1;
    const radius = 8 + t * 26; // px, visually mirrors the legend's light→deep ramp
    const marker = L.circleMarker(ll, {
      radius: radius,
      color: '#0A0F1E',
      weight: 1.5,
      fillColor: r.color,
      fillOpacity: 0.85
    });
    const valueStr = (typeof dgFormatNumber === 'function') ? dgFormatNumber(r.value, numberFormat) : String(r.value);
    marker.bindPopup('<div class="dg-mapx-popup-title">' + r.canonical + '</div><div class="dg-mapx-popup-value">' + valueStr + '</div>');
    marker.addTo(dgMapx.markerLayer);
    bounds.push(ll);
  });
  if (bounds.length) dgMapx._lastBounds = bounds;
}

function dgMapExplorerFitAll() {
  if (!dgMapx.map) return;
  if (dgMapx._lastBounds && dgMapx._lastBounds.length) {
    dgMapx.map.fitBounds(dgMapx._lastBounds, { padding: [40, 40], maxZoom: 6 });
  } else {
    dgMapx.map.setView([20, 0], 2);
  }
}

function dgOpenMapExplorer() {
  if (dgActiveMode !== 'map') { toast('Switch to the Map tab first', 'error'); return; }
  const modal = document.getElementById('dgMapExplorerModal');
  if (!modal) return;
  // Root cause of "push to Workspace does nothing": this modal is `position:fixed`,
  // but it lives in the DOM inside #dgCanvasZoomWrap, and dgApplyZoom() sets that
  // wrap's `transform: scale(...)` the moment the Diagrams page loads (even at
  // 100% zoom). Per the CSS spec, ANY transform on an ancestor turns it into the
  // containing block for `position:fixed` descendants — so instead of covering the
  // real viewport, this modal (and its Push-to-Workspace button) was being sized
  // and positioned relative to the small, scaled chart canvas, not the screen.
  // That's what made the button unreachable/inert. Re-parenting to <body> (which
  // has no transform) the first time this opens permanently fixes it — appendChild
  // moves the existing node (Leaflet instance, listeners, and all), it doesn't
  // recreate it, so nothing else about the panel changes.
  if (modal.parentElement !== document.body) document.body.appendChild(modal);
  modal.classList.add('open');
  dgMapExplorerEnsureMap();
  dgRefreshMapExplorerMarkers();
  // Leaflet sizes itself from the container's dimensions at init time, and the modal was
  // display:none until just now, so give the layout a tick to settle before invalidating.
  setTimeout(() => {
    if (dgMapx.map) {
      dgMapx.map.invalidateSize();
      dgMapExplorerFitAll();
    }
  }, 60);
}

function dgCloseMapExplorer() {
  const modal = document.getElementById('dgMapExplorerModal');
  if (modal) modal.classList.remove('open');
}

// ── State/Province choropleth: colours in ADM1 boundaries for one country at a time,
// fetched on demand from the free geoBoundaries API (https://www.geoboundaries.org — CC-BY 4.0,
// no key required) and matched against dgState.rows by name, the same way the country-level
// choropleth matches DG_WORLD_COUNTRIES. Kept as its own on/off layer (rather than baking every
// country's states into the file) because world admin-1 data runs into the tens of megabytes —
// fetching just the one country someone is actually looking at keeps this fast and lightweight.
let dgMapxSelectPopulated = false;
function dgMapxPopulateCountrySelect() {
  const select = document.getElementById('dgMapxCountrySelect');
  if (!select) return;
  if (!dgMapxSelectPopulated) {
    select.innerHTML = DG_COUNTRY_ISO3.map(function(e) {
      return '<option value="' + e[0].replace(/"/g, '&quot;') + '">' + e[0] + '</option>';
    }).join('');
    dgMapxSelectPopulated = true;
  }
  // Preselect whichever country the current data already matches best. A few state/province
  // names double as the name of a sovereign country (e.g. "Georgia" is both a US state and a
  // country), so a naive "any country-level match wins" check can misfire on a full 50-row
  // US-states sheet that happens to include that one row. Compare both signals and trust
  // whichever one actually explains a bigger share of the sheet.
  const rows = (dgState && Array.isArray(dgState.rows)) ? dgState.rows : [];
  let preferred = null;
  let countryMatchedCount = 0;
  if (rows.length) {
    const result = dgAssignWorldMapColors(rows);
    countryMatchedCount = result.matched.length;
    if (countryMatchedCount) preferred = result.matched[0].canonical;
  }
  if (rows.length) {
    const guess = dgDetectStatesCountry(rows);
    if (guess && guess.matched > countryMatchedCount) preferred = guess.country;
  }
  select.value = preferred || 'United States of America';
  if (!select.value) select.selectedIndex = 0;
}

function dgMapxToggleStates() {
  const btn = document.getElementById('dgMapxStatesToggle');
  const select = document.getElementById('dgMapxCountrySelect');
  const statusEl = document.getElementById('dgMapxStatesStatus');
  const emptyState = document.getElementById('dgMapxEmptyState');
  dgMapx.statesOn = !dgMapx.statesOn;
  if (btn) btn.classList.toggle('active', dgMapx.statesOn);
  if (select) select.disabled = !dgMapx.statesOn;
  // The per-country dot markers and the per-state fill cover the same ground, so only show one
  // at a time — otherwise a big circle marker sits on top of the very states it's obscuring.
  if (dgMapx.map && dgMapx.markerLayer) {
    if (dgMapx.statesOn) dgMapx.map.removeLayer(dgMapx.markerLayer);
    else if (!dgMapx.map.hasLayer(dgMapx.markerLayer)) dgMapx.map.addLayer(dgMapx.markerLayer);
  }
  if (dgMapx.statesOn) {
    // The "no country matched" message belongs to the dot-marker view — states/provinces data
    // is expected not to match country names, so that message is stale noise here. Hide it;
    // dgMapxRenderStatesLayer/dgMapxLoadStates own the status line for this mode instead.
    if (emptyState) emptyState.style.display = 'none';
    dgMapxPopulateCountrySelect();
    if (select && select.value) dgMapxLoadStates(select.value);
  } else {
    if (dgMapx.statesLayer && dgMapx.map) { dgMapx.map.removeLayer(dgMapx.statesLayer); dgMapx.statesLayer = null; }
    if (statusEl) statusEl.textContent = '';
    const pushBtn = document.getElementById('dgMapxPushBtn');
    if (pushBtn) pushBtn.style.display = 'none';
    // Back to dot-marker mode — let it recompute whether the empty-state message applies.
    dgRefreshMapExplorerMarkers();
    dgMapExplorerFitAll();
  }
}

function dgMapxOnCountryChange() {
  const select = document.getElementById('dgMapxCountrySelect');
  if (dgMapx.statesOn && select && select.value) dgMapxLoadStates(select.value);
}

// geoBoundaries' metadata sometimes points at a "github.com/.../raw/..." URL rather than
// the raw.githubusercontent.com host. github.com's own /raw/ redirect endpoint answers with
// an empty Access-Control-Allow-Origin header, which browsers treat as an invalid CORS
// response and block outright — even though the file itself is public. Rewriting to the
// actual raw-content host (which sends a proper "*" CORS header) fixes the fetch without
// changing what file is loaded.
function dgGithubRawUrl(url) {
  if (!url) return url;
  const m = /^https?:\/\/github\.com\/([^\/]+)\/([^\/]+)\/raw\/(.+)$/.exec(url);
  if (m) return 'https://raw.githubusercontent.com/' + m[1] + '/' + m[2] + '/' + m[3];
  return url;
}

// raw.githubusercontent.com serves the correct CORS headers, but for files GitHub stores via
// Git LFS (some of geoBoundaries' larger ADM1 files) it can hand back the LFS *pointer* stub —
// a few lines of plain text starting with "version https://git-lfs.github.com/spec/v1" — instead
// of the actual GeoJSON. media.githubusercontent.com is GitHub's LFS-smudge host and serves the
// real file content for the same repo path, so on that specific failure we retry there once.
function dgIsLfsPointerText(text) {
  return typeof text === 'string' && text.slice(0, 40).indexOf('version https://git-lfs') === 0;
}
function dgGithubMediaUrl(rawUrl) {
  const m = /^https?:\/\/raw\.githubusercontent\.com\/([^\/]+)\/([^\/]+)\/(.+)$/.exec(rawUrl);
  if (!m) return null;
  return 'https://media.githubusercontent.com/media/' + m[1] + '/' + m[2] + '/' + m[3];
}

function dgFetchBoundaryJson(url) {
  return fetch(url)
    .then(function(r) { if (!r.ok) throw new Error('download failed (' + r.status + ')'); return r.text(); })
    .then(function(text) {
      if (dgIsLfsPointerText(text)) {
        const mediaUrl = dgGithubMediaUrl(url);
        if (!mediaUrl) throw new Error('file is stored via Git LFS and could not be resolved');
        return fetch(mediaUrl).then(function(r) {
          if (!r.ok) throw new Error('download failed (' + r.status + ')');
          return r.text();
        }).then(function(mediaText) {
          if (dgIsLfsPointerText(mediaText)) throw new Error('file is stored via Git LFS and could not be resolved');
          return JSON.parse(mediaText);
        });
      }
      return JSON.parse(text);
    });
}

function dgMapxLoadStates(countryName) {
  const iso3 = dgCountryIso3(countryName);
  const statusEl = document.getElementById('dgMapxStatesStatus');
  const pushBtn = document.getElementById('dgMapxPushBtn');
  if (pushBtn) pushBtn.style.display = 'none';
  if (!iso3) { if (statusEl) statusEl.textContent = "No boundary code for " + countryName + "."; return; }
  if (dgMapx.statesCache[iso3]) { dgMapxRenderStatesLayer(dgMapx.statesCache[iso3], countryName); return; }
  if (statusEl) statusEl.textContent = 'Loading ' + countryName + ' states/provinces…';
  fetch('https://www.geoboundaries.org/api/current/gbOpen/' + iso3 + '/ADM1/')
    .then(function(r) { if (!r.ok) throw new Error('lookup failed (' + r.status + ')'); return r.json(); })
    .then(function(meta) {
      let url = (meta && (meta.simplifiedGeometryGeoJSON || meta.gjDownloadURL)) || null;
      if (!url) throw new Error('no boundary file for this country');
      url = dgGithubRawUrl(url);
      return dgFetchBoundaryJson(url);
    })
    .then(function(geojson) {
      dgMapx.statesCache[iso3] = geojson;
      dgMapxRenderStatesLayer(geojson, countryName);
    })
    .catch(function(err) {
      if (statusEl) statusEl.textContent = "Couldn't load " + countryName + " boundaries (" + (err && err.message ? err.message : 'network error') + ').';
    });
}

// Boundary datasets and user spreadsheets rarely agree on the exact label for a state — official
// GIS sources often carry formal prefixes ("NCT of Delhi") or older names (Orissa, Pondicherry,
// Uttaranchal, Mysore) that a plain lowercase-equality match will never line up with what
// someone actually typed. Strip common prefixes/punctuation and run through a small alias table
// before comparing, so both sides land on the same canonical spelling.
const DG_STATE_NAME_ALIASES = {
  'orissa': 'odisha',
  'pondicherry': 'puducherry',
  'uttaranchal': 'uttarakhand',
  'mysore': 'karnataka',
  'madras': 'tamil nadu',
  'travancore-cochin': 'kerala',
  'united provinces': 'uttar pradesh',
  'jammu and kashmir and ladakh': 'jammu and kashmir'
};
function dgNormalizeStateName(name) {
  let s = String(name || '')
    .toLowerCase()
    .replace(/&/g, 'and')
    .replace(/[.,]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
  s = s.replace(/^(nct of|state of|union territory of|ut of)\s+/, '').trim();
  if (DG_STATE_NAME_ALIASES[s]) s = DG_STATE_NAME_ALIASES[s];
  return s;
}
// Matches a boundary feature's shapeName against the uploaded rows: exact match on the
// normalized/aliased name first, then (since prefix-stripping alone won't catch every formatting
// difference) a same-key containment check — e.g. a row normalized to "delhi" still matches a
// feature normalized to "delhi ncr" or vice versa — so near-miss labels aren't silently dropped.
function dgMatchStateRow(rowMap, normalizedKeys, shapeName) {
  const norm = dgNormalizeStateName(shapeName);
  if (rowMap[norm]) return rowMap[norm];
  if (!norm) return null;
  const normPadded = ' ' + norm + ' ';
  for (let i = 0; i < normalizedKeys.length; i++) {
    const key = normalizedKeys[i];
    if (!key) continue;
    const keyPadded = ' ' + key + ' ';
    if (normPadded.indexOf(keyPadded) !== -1 || keyPadded.indexOf(normPadded) !== -1) return rowMap[key];
  }
  return null;
}

function dgMapxRenderStatesLayer(geojson, countryName) {
  if (!dgMapx.map || typeof L === 'undefined') return;
  const emptyState = document.getElementById('dgMapxEmptyState');
  if (emptyState) emptyState.style.display = 'none';
  const pushBtn = document.getElementById('dgMapxPushBtn');
  if (pushBtn) pushBtn.style.display = '';
  if (dgMapx.statesLayer) { dgMapx.map.removeLayer(dgMapx.statesLayer); dgMapx.statesLayer = null; }
  const rows = (dgState && Array.isArray(dgState.rows)) ? dgState.rows : [];
  const rowMap = {};
  rows.forEach(function(r) { rowMap[dgNormalizeStateName(r.label)] = r; });
  const normalizedKeys = Object.keys(rowMap);
  const features = (geojson && geojson.features) || [];
  const matchedVals = [];
  const matchedKeys = {};
  features.forEach(function(f) {
    const row = dgMatchStateRow(rowMap, normalizedKeys, (f.properties && f.properties.shapeName) || '');
    if (row) { matchedVals.push(row.value); matchedKeys[dgNormalizeStateName(row.label)] = true; }
  });
  const minV = matchedVals.length ? Math.min.apply(null, matchedVals) : 0;
  const maxV = matchedVals.length ? Math.max.apply(null, matchedVals) : 0;
  const numberFormat = (typeof dgGetOpts === 'function') ? (dgGetOpts().numberFormat || 'plain') : 'plain';
  dgMapx.statesLayer = L.geoJSON(geojson, {
    style: function(feature) {
      const row = dgMatchStateRow(rowMap, normalizedKeys, (feature.properties && feature.properties.shapeName) || '');
      if (row) {
        const t = maxV > minV ? (row.value - minV) / (maxV - minV) : 1;
        return { color: '#0A0F1E', weight: 1, fillColor: dgWorldMapColor(t), fillOpacity: 0.82 };
      }
      return { color: 'rgba(255,255,255,0.35)', weight: 1, fillColor: '#1e293b', fillOpacity: 0.15 };
    },
    onEachFeature: function(feature, layer) {
      const shapeName = (feature.properties && feature.properties.shapeName) || 'Unknown';
      const row = dgMatchStateRow(rowMap, normalizedKeys, shapeName);
      const valueStr = row ? ((typeof dgFormatNumber === 'function') ? dgFormatNumber(row.value, numberFormat) : String(row.value)) : 'No matching data';
      layer.bindPopup('<div class="dg-mapx-popup-title">' + shapeName + '</div><div class="dg-mapx-popup-value">' + valueStr + '</div>');
    }
  }).addTo(dgMapx.map);
  dgMapx.map.fitBounds(dgMapx.statesLayer.getBounds(), { padding: [30, 30] });
  const statusEl = document.getElementById('dgMapxStatesStatus');
  if (statusEl) {
    statusEl.textContent = matchedVals.length + ' of ' + features.length + ' ' + countryName + ' states matched · boundaries via geoBoundaries (CC-BY 4.0) · name matching still improving';
    const unmatchedLabels = rows
      .filter(function(r) { return !matchedKeys[dgNormalizeStateName(r.label)]; })
      .map(function(r) { return r.label; });
    statusEl.title = unmatchedLabels.length ? ('Not matched: ' + unmatchedLabels.join(', ')) : '';
  }
}

// Auto-opens Map Explorer with the States/Provinces layer switched straight on for the given
// country, skipping the manual "open Explore Map → click States → pick the country" steps —
// used right after a state/province-only upload gets auto-detected (see dgDetectStatesCountry)
// so the person lands directly on their big, zoomed-in country map with every state coloured in
// at its precise real-world location, instead of the flat "nothing matched" world choropleth.
function dgAutoShowStateMap(countryName) {
  if (dgActiveMode !== 'map' || !countryName) return;
  dgOpenMapExplorer();
  dgMapxPopulateCountrySelect();
  const btn = document.getElementById('dgMapxStatesToggle');
  const select = document.getElementById('dgMapxCountrySelect');
  dgMapx.statesOn = true;
  if (btn) btn.classList.add('active');
  if (select) { select.disabled = false; select.value = countryName; }
  if (dgMapx.map && dgMapx.markerLayer && dgMapx.map.hasLayer(dgMapx.markerLayer)) {
    dgMapx.map.removeLayer(dgMapx.markerLayer);
  }
  dgMapxLoadStates(countryName);
}

// ── Map mode: per-country maps ──────────────────────────────────────────────
// Multi-country tabular data (e.g. a table listing USA, Australia, India, China,
// Russia) already produces one combined choropleth with every country shaded
// together. On top of that, this builds a separate single-country map for EACH
// matched country and drops them into the multi-chart gallery strip below the
// main canvas — the same gallery "one chart per column" already uses — so every
// country in the upload gets its own dedicated map, one click away, without
// disturbing the combined world map still showing in the main editor.
function dgBuildPerCountryMaps(rows) {
  if (!Array.isArray(rows) || !rows.length) {
    if (dgMultiCharts.length) { dgMultiCharts = []; dgRenderMultiChartGallery(); }
    return;
  }
  const matchedRows = rows.filter(r => dgResolveCountry(r.label));
  // Only worth a per-country gallery once there's genuinely more than one country —
  // a single-country upload already IS its own map in the main canvas.
  if (matchedRows.length < 2) {
    if (dgMultiCharts.length) { dgMultiCharts = []; dgRenderMultiChartGallery(); }
    return;
  }
  // Each card is its own big, zoomed-in country chart (dgDrawCountryZoom) — NOT a
  // small highlight inside the whole globe — so it reads as a dedicated chart for
  // that one country, distinct from the combined world map on the main canvas.
  dgMultiCharts = matchedRows.map(r => ({
    title: dgResolveCountry(r.label) || r.label,
    type: 'countryzoom',
    rows: [{ label: r.label, value: r.value }]
  }));
  dgRenderMultiChartGallery();
}

// Keeps the per-country gallery in sync with whatever's currently on the canvas —
// rebuilds it after every re-generate while Map mode is active, and clears any
// leftover per-country cards if the person switches back to a normal chart type.
function dgSyncPerCountryGallery(rows) {
  if (dgState.type === 'worldmap') {
    dgBuildPerCountryMaps(rows);
  } else if (dgMultiCharts.length && dgMultiCharts.every(c => c.type === 'countryzoom')) {
    dgMultiCharts = [];
    dgRenderMultiChartGallery();
  }
}

// Draws the choropleth itself straight onto the shared chart canvas (Path2D
// from each country's SVG path data) — same canvas the rest of the chart
// engine draws to, so PNG/JPEG/PDF/DOCX export and "Push to Workspace" keep
// working unmodified, with zero extra export-pipeline code.
function dgDrawWorldMap(ctx, matchResult, area, opts) {
  const { matched, unmatched, min, max } = matchResult;
  const valueByCountry = new Map(matched.map(r => [r.canonical, r]));

  const legendH = 46;
  const mapArea = { x: area.x, y: area.y, w: area.w, h: Math.max(80, area.h - legendH) };
  const scale = Math.min(mapArea.w / DG_WORLD_MAP_VB.w, mapArea.h / DG_WORLD_MAP_VB.h);
  const drawW = DG_WORLD_MAP_VB.w * scale, drawH = DG_WORLD_MAP_VB.h * scale;
  const offX = mapArea.x + (mapArea.w - drawW) / 2;
  const offY = mapArea.y + (mapArea.h - drawH) / 2;

  // "Ocean" backdrop: a genuinely flat, premium card behind the landmasses — pure
  // solid fill, a crisp 1px hairline border, and NO shadow/elevation, so nothing
  // on the panel reads as curved or dimensional. It still keeps the map reading
  // as a distinct, deliberate chart region — even on a plain white PDF page after
  // Push to Workspace, and even when NO row has matched a country yet. This bakes
  // into every export path (PNG/JPEG/PDF/DOCX/Push) since it's drawn straight
  // onto the shared canvas.
  const panelPad = 12;
  dgRoundRectPath(ctx, mapArea.x - panelPad, mapArea.y - panelPad, mapArea.w + panelPad * 2, mapArea.h + panelPad * 2, 8);
  ctx.fillStyle = '#ffffff';
  ctx.fill();
  ctx.strokeStyle = '#dde3ea';
  ctx.lineWidth = 1;
  ctx.stroke();

  ctx.save();
  ctx.translate(offX, offY);
  ctx.scale(scale, scale);
  // Flat cartography: fills carry all the information, so borders are kept to a
  // thin hairline matching the panel background — countries read as clean,
  // separate cut-out shapes (the premium "vector map" look) rather than a
  // hand-inked atlas with heavy dark outlines.
  ctx.lineWidth = 0.5 / scale;
  DG_WORLD_COUNTRIES.forEach(([name, d]) => {
    const row = valueByCountry.get(name);
    const p = new Path2D(d);
    // Unmatched countries get a clearly visible, neutral slate fill (not near-white)
    // so the whole landmass is always legible on its own, independent of whether
    // any row happened to match — this is what keeps a freshly-built map from
    // looking "blank" the moment it's dropped onto a white Workspace page.
    ctx.fillStyle = row ? row.color : '#cbd5e1';
    ctx.fill(p);
    ctx.strokeStyle = '#ffffff';
    ctx.stroke(p);
  });
  ctx.restore();

  // Gradient legend bar (min → max), only drawn once there is real matched data —
  // an unresolved-data state shows guidance text instead of an empty 0→0 scale.
  // Styled as a flat pill (rounded ends, thin border, no glow) for a clean,
  // dashboard-grade legend rather than a raw canvas gradient strip.
  const barY = mapArea.y + mapArea.h + 14;
  const barW = Math.min(260, area.w * 0.45), barH = 8;
  const barX = area.x + area.w / 2 - barW / 2;
  if (matched.length) {
    const grad = ctx.createLinearGradient(barX, 0, barX + barW, 0);
    grad.addColorStop(0, dgWorldMapColor(0));
    grad.addColorStop(1, dgWorldMapColor(1));
    ctx.fillStyle = grad;
    dgRoundRectPath(ctx, barX, barY, barW, barH, barH / 2);
    ctx.fill();
    ctx.strokeStyle = 'rgba(15,23,42,0.08)';
    ctx.lineWidth = 1;
    dgRoundRectPath(ctx, barX, barY, barW, barH, barH / 2);
    ctx.stroke();
    ctx.fillStyle = "#475569";
    ctx.font = "600 11px Inter, sans-serif";
    ctx.textAlign = "right";
    ctx.fillText(dgFormatNumber(min, opts.numberFormat), barX - 8, barY + 8);
    ctx.textAlign = "left";
    ctx.fillText(dgFormatNumber(max, opts.numberFormat), barX + barW + 8, barY + 8);
    if (unmatched.length) {
      ctx.textAlign = "center";
      ctx.font = "500 10.5px Inter, sans-serif";
      ctx.fillStyle = "#94a3b8";
      ctx.fillText(unmatched.length + (unmatched.length === 1 ? " row didn't match a country name" : " rows didn't match a country name"), area.x + area.w / 2, barY + 26);
    }
  } else {
    ctx.fillStyle = "#94a3b8";
    ctx.font = "600 13px Inter, sans-serif";
    ctx.textAlign = "center";
    ctx.fillText("None of these labels matched a country", area.x + area.w / 2, barY + 4);
    ctx.font = "400 11.5px Inter, sans-serif";
    ctx.fillStyle = "#b0b9c6";
    ctx.fillText("Use country names as row labels — e.g. India, United States, Germany, Brazil", area.x + area.w / 2, barY + 22);
  }
}

// ── Per-country "big main" map view ──────────────────────────────────────────
// dgDrawWorldMap above shows the WHOLE globe with one country highlighted inside
// it — right for the combined multi-country map, but too small/zoomed-out for a
// per-country card whose whole point is to be a big, dedicated chart of just that
// one country. This looks up the same path data, crops the canvas to that
// country's own bounding box (ignoring the rest of the 960x500 world viewBox),
// and fills the canvas with it — the "big main country chart" view.
const DG_COUNTRY_PATH_BY_NAME = new Map(DG_WORLD_COUNTRIES.map(c => [c[0], c[1]]));

// Extracts every "x,y" coordinate pair out of an SVG path's `d` string and returns
// its bounding box. Works for this dataset because every path here uses absolute
// M/L/Z commands glued directly to their numbers with no spaces (e.g.
// "M187.8,93L194.5,93L...Z"), so a plain "number,number" scan picks up every
// vertex regardless of which command precedes it or how many disconnected
// subpaths (islands, exclaves) the country has.
function dgPathBBox(d) {
  const re = /(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)/g;
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity, found = false;
  let m;
  while ((m = re.exec(d))) {
    found = true;
    const x = parseFloat(m[1]), y = parseFloat(m[2]);
    if (x < minX) minX = x; if (x > maxX) maxX = x;
    if (y < minY) minY = y; if (y > maxY) maxY = y;
  }
  if (!found) return null;
  return { minX, minY, maxX, maxY, w: maxX - minX, h: maxY - minY };
}

// Draws ONE country zoomed to fill the available area, instead of the whole world
// with that country merely highlighted. `target` is { country, value } — country
// must be the canonical DG_WORLD_COUNTRIES name (already resolved via
// dgResolveCountry by the caller). Falls back to a plain message if the shape
// can't be found, so it's always safe to call even on bad data.
function dgDrawCountryZoom(ctx, target, area, opts) {
  const d = target && target.country ? DG_COUNTRY_PATH_BY_NAME.get(target.country) : null;
  if (!d) {
    ctx.fillStyle = '#b8c0cc';
    ctx.font = '600 13px Inter, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Country shape not found', area.x + area.w / 2, area.y + area.h / 2);
    return;
  }
  const bbox = dgPathBBox(d);
  if (!bbox) return;
  const PAD = 0.12; // breathing room on every side so the shape doesn't touch the frame
  const bw = bbox.w || 1, bh = bbox.h || 1;
  const padX = bw * PAD, padY = bh * PAD;
  const vbX = bbox.minX - padX, vbY = bbox.minY - padY;
  const vbW = bw + padX * 2, vbH = bh + padY * 2;

  // A small header strip for the country name keeps this reading as a proper,
  // titled chart card rather than a bare floating shape, and a value chip
  // (instead of plain baseline text) gives the number the same flat, pill-style
  // treatment as the legend on the combined world map — one consistent visual
  // language across both views.
  const titleH = target && target.country ? 26 : 0;
  const valueH = target && target.value != null ? 34 : 12;
  const mapArea = { x: area.x, y: area.y + titleH, w: area.w, h: Math.max(60, area.h - valueH - titleH) };
  const scale = Math.min(mapArea.w / vbW, mapArea.h / vbH);
  const drawW = vbW * scale, drawH = vbH * scale;
  const offX = mapArea.x + (mapArea.w - drawW) / 2 - vbX * scale;
  const offY = mapArea.y + (mapArea.h - drawH) / 2 - vbY * scale;

  // Same genuinely flat card the combined world map uses — solid white fill,
  // crisp hairline border, no shadow/elevation — so a single-country card reads
  // as part of the same premium, flat design system rather than a shape
  // floating on bare white once it's pushed onto a plain Workspace page.
  const panelPad = 12;
  dgRoundRectPath(ctx, mapArea.x - panelPad, mapArea.y - panelPad, mapArea.w + panelPad * 2, mapArea.h + panelPad * 2, 8);
  ctx.fillStyle = '#ffffff';
  ctx.fill();
  ctx.strokeStyle = '#dde3ea';
  ctx.lineWidth = 1;
  ctx.stroke();

  if (titleH) {
    ctx.fillStyle = '#334155';
    ctx.font = '700 13px Inter, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(target.country, area.x + area.w / 2, area.y + 15);
  }

  ctx.save();
  ctx.translate(offX, offY);
  ctx.scale(scale, scale);
  const p = new Path2D(d);
  // A single country has no min/max range to shade against, so it's filled with
  // the deepest tone of the current theme colour — same scale the combined
  // world map uses, so it reads as part of the same product/theme instead of
  // an arbitrary fixed colour. Border matches the flat white hairline used on
  // the combined map instead of a heavy dark outline.
  ctx.fillStyle = dgWorldMapColor(1);
  ctx.fill(p);
  ctx.lineWidth = Math.max(0.6, 0.5 / scale);
  ctx.strokeStyle = '#ffffff';
  ctx.stroke(p);
  ctx.restore();

  if (target && target.value != null) {
    const label = dgFormatNumber(target.value, opts.numberFormat);
    const chipY = mapArea.y + mapArea.h + panelPad + 16;
    ctx.font = '700 13px Inter, sans-serif';
    const chipW = ctx.measureText(label).width + 24, chipH = 24;
    const chipX = area.x + area.w / 2 - chipW / 2;
    dgRoundRectPath(ctx, chipX, chipY - chipH / 2, chipW, chipH, chipH / 2);
    ctx.fillStyle = dgWorldMapColor(1);
    ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(label, area.x + area.w / 2, chipY + 1);
    ctx.textBaseline = 'alphabetic';
  }
}

// ═══════════════════════════════════════════════════════════════════════
// FLOWCHART / DIAGRAM MODE (Mermaid) — additive sibling to the canvas-based
// chart engine above. Never reads or writes dgState/dg3D, so switching
// modes can't corrupt an in-progress data chart. The only shared surface
// is dgGetExportCanvas(), which is taught below to branch on dgActiveMode
// so Download/Export/Push-to-Workspace all keep working unmodified.
// ═══════════════════════════════════════════════════════════════════════
let dgActiveMode = 'chart'; // 'chart' | 'flow' | 'map'
let dgPrevChartType = 'bar'; // chart type to restore when leaving Map mode back to Data Charts
let dgFlowCanvasCache = null; // last successfully rendered diagram, rasterized to a <canvas>
let dgFlowDebounceTimer = null;

if (typeof mermaid !== 'undefined') {
  try {
    mermaid.initialize({
      startOnLoad: false, theme: 'default', securityLevel: 'loose', fontFamily: 'Inter, sans-serif',
      // htmlLabels:false forces plain SVG <text> instead of <foreignObject><div>...</div></foreignObject>.
      // foreignObject content taints the canvas the moment we drawImage() it in, so toDataURL() (used by
      // both Download PNG and Push to Workspace) throws a silent SecurityError. Plain SVG text avoids that.
      flowchart: { htmlLabels: false }
    });
  }
  catch (e) { console.error('Mermaid init failed', e); }
}

const DG_FLOW_TEMPLATES = {
  flowchart: 'flowchart TD\n    A[Start] --> B{Decision}\n    B -->|Yes| C[Continue]\n    B -->|No| D[Stop]\n    C --> E[End]\n    D --> E',
  sequence: 'sequenceDiagram\n    participant U as User\n    participant S as System\n    U->>S: Request\n    S-->>U: Response\n    S->>U: Confirmation',
  org: 'flowchart TD\n    CEO[CEO] --> VP1[VP Sales]\n    CEO --> VP2[VP Engineering]\n    VP1 --> M1[Sales Manager]\n    VP2 --> M2[Engineering Manager]',
  mindmap: 'mindmap\n  root((Topic))\n    Idea 1\n      Detail A\n      Detail B\n    Idea 2\n    Idea 3',
  gantt: 'gantt\n    title Project Timeline\n    dateFormat YYYY-MM-DD\n    section Phase 1\n    Task A :a1, 2026-01-01, 10d\n    Task B :after a1, 8d'
};

// ── Strips characters Mermaid's mindmap parser reads as node-shape syntax —
// ( ) [ ] { } — and collapses whitespace, so a real label like "Revenue (APAC)"
// renders as plain node text instead of breaking the diagram or being silently
// reinterpreted as a shape. Also caps length so long labels don't blow out the layout.
function dgMindSanitize(s, maxLen) {
  const clean = String(s == null ? '' : s).replace(/[()\[\]{}]/g, '').replace(/\s+/g, ' ').trim();
  const limit = maxLen || 40;
  return clean.length > limit ? clean.slice(0, Math.max(1, limit - 1)) + '\u2026' : clean;
}

// ── "Business Mind" template: unlike the other Flowchart/Diagram starters, this one
// isn't a static string — it reuses the same domain-detection + stat + business-read
// helpers that already power the Data Charts Insights panel (dgComputeStats,
// dgDetectDomain, dgBuildBusinessReadSentence) and lays their output out as a Mermaid
// mindmap instead of a strip of stat cards. So whatever data is currently loaded in
// Data Charts is what gets mapped here — nothing is invented. Falls back to a short
// "nothing loaded yet" placeholder mindmap when Data Charts is empty.
function dgBuildBusinessMindMapCode() {
  try {
    if (typeof dgState === 'undefined' || !dgState.rows || !dgState.rows.length) {
      return 'mindmap\n  root((Business Mind))\n    No data loaded yet\n      Upload a spreadsheet or table in Data Arrangement\n      Or build a chart here in Data Charts\n    Then reopen Business Mind\n      to auto-map its key insights';
    }
    const opts = (typeof dgGetOpts === 'function') ? dgGetOpts() : {};
    const stats = dgComputeStats(dgState.rows);
    const chartTitle = dgState.title || (document.getElementById('dgTitleInput') || {}).value || '';
    const domain = dgDetectDomain(dgState.rows, chartTitle, dgState.type);
    const fmt = v => (typeof dgFormatNumber === 'function') ? dgFormatNumber(v, opts.numberFormat) : String(Math.round(v));
    const rootLabel = dgMindSanitize(domain.confident ? domain.label : (chartTitle || 'Business Mind'), 40) || 'Business Mind';

    const lines = ['mindmap', `  root((${rootLabel}))`];

    lines.push('    Totals');
    lines.push(`      Total ${dgMindSanitize(fmt(stats.total), 24)}`);
    lines.push(`      Average ${dgMindSanitize(fmt(stats.avg), 24)}`);

    lines.push('    Performance');
    lines.push(`      Top - ${dgMindSanitize(stats.maxLabel, 26)} ${dgMindSanitize(fmt(stats.max), 16)}`);
    lines.push(`      Bottom - ${dgMindSanitize(stats.minLabel, 26)} ${dgMindSanitize(fmt(stats.min), 16)}`);
    if (stats.vitalFewCount !== null && stats.n > 2) {
      lines.push(`      Top ${stats.vitalFewCount} of ${stats.n} drive 80% of the total`);
    }

    lines.push('    Trend');
    const trendWord = stats.trend === 'up' ? 'Trending up' : stats.trend === 'down' ? 'Trending down' : 'Holding steady';
    const growthLine = stats.growthPct !== null
      ? `${trendWord}, ${stats.growthPct >= 0 ? '+' : ''}${Math.round(stats.growthPct)}% first to last`
      : trendWord;
    lines.push(`      ${dgMindSanitize(growthLine, 44)}`);

    if (stats.outliers && stats.outliers.length) {
      lines.push('    Watch');
      lines.push(`      ${dgMindSanitize(stats.outliers.length > 1 ? stats.outliers.length + ' values outside the normal range' : stats.outliers[0].label + ' sits well outside the normal range', 44)}`);
    }

    let businessRead = '';
    try { businessRead = dgBuildBusinessReadSentence(domain, stats, dgState.rows, opts) || ''; } catch (e) { businessRead = ''; }
    businessRead = businessRead.replace(/<[^>]+>/g, ''); // strip the <b> tags meant for the HTML insight sentence, not a mindmap leaf
    if (businessRead) {
      lines.push('    Recommendation');
      const chunks = businessRead.match(/.{1,44}(\s|$)/g) || [businessRead];
      chunks.slice(0, 3).forEach(c => lines.push(`      ${dgMindSanitize(c, 44)}`));
    }

    return lines.join('\n');
  } catch (e) {
    console.warn('[Diagrams] could not build Business Mind map', e);
    return 'mindmap\n  root((Business Mind))\n    Could not read the current data\n      Try reloading it in Data Charts first';
  }
}

function dgFlowInsertTemplate(name) {
  const ta = document.getElementById('dgFlowInput');
  if (!ta) return;
  if (name === 'businessmind') {
    ta.value = dgBuildBusinessMindMapCode();
    dgFlowRender();
    return;
  }
  if (!DG_FLOW_TEMPLATES[name]) return;
  ta.value = DG_FLOW_TEMPLATES[name];
  dgFlowRender();
}

// ─── Persistence: same mechanism as the chart builder's dgPersist/dgRestore —
// browser-only (localStorage), nothing uploaded anywhere. Registered under
// SM_MODULE_STORAGE.diagrams above, so it's automatically picked up by
// "Save Your Workflow", Saved Sessions, and cleared by "New Project" —
// no extra wiring needed in any of those three places. ───
const DG_FLOW_STORAGE_KEY = 'sarvarcDgFlowState_v1';
let dgFlowPersistTimer = null;
function dgFlowPersist() {
  clearTimeout(dgFlowPersistTimer);
  dgFlowPersistTimer = setTimeout(() => {
    try {
      const code = (document.getElementById('dgFlowInput') || {}).value || '';
      const title = (document.getElementById('dgFlowTitleInput') || {}).value || '';
      localStorage.setItem(DG_FLOW_STORAGE_KEY, JSON.stringify({ code, title }));
    } catch (e) { console.warn('[Diagrams] could not persist flowchart state', e); }
    dgFlowCollabPush();
  }, 300);
}
function dgFlowRestore() {
  try {
    const raw = localStorage.getItem(DG_FLOW_STORAGE_KEY);
    if (!raw) return;
    const saved = JSON.parse(raw);
    if (!saved || typeof saved !== 'object') return;
    const ta = document.getElementById('dgFlowInput');
    const ti = document.getElementById('dgFlowTitleInput');
    if (ta && typeof saved.code === 'string') ta.value = saved.code;
    if (ti && typeof saved.title === 'string' && saved.title) ti.value = saved.title;
  } catch (e) { console.warn('[Diagrams] could not restore flowchart state', e); }
}
dgFlowRestore();

// Reads width/height straight off the Mermaid SVG string (viewBox fallback) so the
// rasterized canvas matches the diagram's real proportions instead of a guessed size.
function dgFlowSvgSize(svgString) {
  const wm = svgString.match(/<svg[^>]*\swidth="([\d.]+)(px)?"/);
  const hm = svgString.match(/<svg[^>]*\sheight="([\d.]+)(px)?"/);
  if (wm && hm && parseFloat(wm[1]) > 0 && parseFloat(hm[1]) > 0) {
    return { w: parseFloat(wm[1]), h: parseFloat(hm[1]) };
  }
  const vb = svgString.match(/viewBox="[-\d.]+\s+[-\d.]+\s+([\d.]+)\s+([\d.]+)"/);
  if (vb) return { w: parseFloat(vb[1]), h: parseFloat(vb[2]) };
  return { w: 900, h: 600 };
}

// Rasterizes the given Mermaid SVG onto an offscreen canvas (white background, 2x
// supersampled for crisp PNG/PDF export) and caches it for dgGetExportCanvas().
function dgFlowRasterizeAndCache(svgString) {
  return new Promise((resolve) => {
    const size = dgFlowSvgSize(svgString);
    const svgBlob = new Blob([svgString], { type: 'image/svg+xml;charset=utf-8' });
    const url = URL.createObjectURL(svgBlob);
    const img = new Image();
    img.onload = function () {
      const scale = 2;
      const w = Math.max(1, Math.round((img.naturalWidth || size.w) * scale));
      const h = Math.max(1, Math.round((img.naturalHeight || size.h) * scale));
      const canvas = document.createElement('canvas');
      canvas.width = w; canvas.height = h;
      const ctx = canvas.getContext('2d');
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, w, h);
      try {
        ctx.drawImage(img, 0, 0, w, h);
        canvas.toDataURL('image/png'); // probe now, not later — surfaces a tainted-canvas error immediately instead of silently at export/push time
        dgFlowCanvasCache = canvas;
        resolve(canvas);
      } catch (e) {
        console.error('Diagram rasterization failed (likely a tainted canvas):', e);
        dgFlowCanvasCache = null;
        const errEl = document.getElementById('dgFlowError');
        if (errEl) { errEl.textContent = 'Could not prepare this diagram for export. Try simplifying it or removing custom styling.'; errEl.style.display = 'block'; }
        resolve(null);
      } finally {
        URL.revokeObjectURL(url);
      }
    };
    img.onerror = function () { URL.revokeObjectURL(url); resolve(null); };
    img.src = url;
  });
}

function dgFlowDebouncedRender() {
  clearTimeout(dgFlowDebounceTimer);
  dgFlowDebounceTimer = setTimeout(dgFlowRender, 500);
}

async function dgFlowRender() {
  dgFlowPersist();
  const code = ((document.getElementById('dgFlowInput') || {}).value || '').trim();
  const previewEl = document.getElementById('dgFlowPreview');
  const errEl = document.getElementById('dgFlowError');
  if (errEl) errEl.style.display = 'none';
  if (!code) { if (previewEl) previewEl.innerHTML = ''; dgFlowCanvasCache = null; return; }
  if (typeof mermaid === 'undefined') {
    if (errEl) { errEl.textContent = 'Flowchart engine failed to load — check your connection and reload.'; errEl.style.display = 'block'; }
    return;
  }
  try {
    const id = 'dgMermaidGraph' + Date.now();
    const { svg } = await mermaid.render(id, code);
    if (previewEl) previewEl.innerHTML = svg;
    await dgFlowRasterizeAndCache(svg);
  } catch (e) {
    console.error(e);
    if (errEl) { errEl.textContent = 'Syntax error: ' + (e && e.message ? e.message.split('\n')[0] : 'could not parse this diagram.'); errEl.style.display = 'block'; }
    // Clean up any partial error markup Mermaid injects into the DOM on failed parses
    const stray = document.getElementById('dMermaidGraph' + id); if (stray) stray.remove();
  }
}

// Switches between the existing canvas-based chart builder and the new Mermaid panel.
// Purely a visibility/state toggle — never touches dgState, dgDrawChart, or dg3D.
function dgSetDgMode(mode) {
  const wasMode = dgActiveMode;
  dgActiveMode = (mode === 'flow') ? 'flow' : (mode === 'map') ? 'map' : 'chart';
  const isFlow = dgActiveMode === 'flow';
  const isMap = dgActiveMode === 'map';
  const isChart = dgActiveMode === 'chart';

  // Leaving Data Charts for Map: remember whatever chart type was active so it can be
  // restored later, then force the shared canvas engine onto 'worldmap'.
  if (isMap && wasMode !== 'map') {
    if (typeof dgState !== 'undefined' && dgState.type && dgState.type !== 'worldmap') {
      dgPrevChartType = dgState.type;
    }
    dgSetType('worldmap');
  }
  // Leaving Map back to Data Charts: restore whatever chart type was active before.
  if (isChart && wasMode === 'map') {
    dgSetType(dgPrevChartType || 'bar');
  }
  // Entering or leaving Map on data that's already loaded: re-tag the Label Column
  // dropdown so the "Country column detected" flag shows/hides with the mode, and
  // jump the selection to the detected country column if it wasn't already on one.
  if ((isMap && wasMode !== 'map') || (isChart && wasMode === 'map')) {
    dgRefreshLabelColDetection();
  }

  const ribbon = document.getElementById('dgRibbonBar');
  const mainRow = document.getElementById('dgMainRow');
  const gallery = document.getElementById('dgMultiGallery');
  const flowPanel = document.getElementById('dgFlowPanel');
  const canvasModeActive = isChart || isMap; // both share the same canvas-based builder
  if (ribbon) ribbon.style.display = canvasModeActive ? '' : 'none';
  if (mainRow) mainRow.style.display = canvasModeActive ? '' : 'none';
  if (gallery) gallery.style.display = canvasModeActive ? '' : 'none';
  if (flowPanel) flowPanel.style.display = isFlow ? 'flex' : 'none';

  // Map mode only ever renders one chart type, so any ribbon controls that only make
  // sense for bar/line/pie/3D-style charts (chart type picker, axis titles, quick
  // templates, bar-corner radius, trendline/growth/hologram toggles) are hidden while
  // Map is active — only the settings that are actually relevant to a choropleth map
  // (columns, legend, values, number format, colours, upload/data, export, push) stay.
  const hideWhenMap = (el) => {
    if (!el) return;
    el.style.display = isMap ? 'none' : '';
    const sep = el.nextElementSibling;
    if (sep && sep.classList && sep.classList.contains('dg-rbn-sep')) {
      sep.style.display = isMap ? 'none' : '';
    }
  };
  hideWhenMap(document.getElementById('dgTypeGroup'));
  hideWhenMap(document.getElementById('dgAxesGroup'));
  hideWhenMap(document.getElementById('dgTemplatesGroup'));
  hideWhenMap(document.getElementById('dgRadiusGroup'));

  // Show-toggle chips that only apply to bar/line/area/3D charts: hide in Map mode.
  const trendChip = document.getElementById('dgTrendChip');
  const growthChip = document.getElementById('dgGrowthChip');
  const hologramChip = document.getElementById('dgHologramChip');
  if (trendChip) trendChip.style.display = isMap ? 'none' : '';
  if (growthChip) growthChip.style.display = isMap ? 'none' : '';
  if (hologramChip) hologramChip.style.display = isMap ? 'none' : '';

  // "Explore Map" only makes sense once Map mode is active and there's a choropleth on the canvas.
  const exploreChip = document.getElementById('dgExploreMapChip');
  if (exploreChip) exploreChip.style.display = isMap ? '' : 'none';
  if (!isMap) dgCloseMapExplorer();
  dgSyncRibbonForType();

  const chartTab = document.getElementById('dgModeChartTab');
  const flowTab = document.getElementById('dgModeFlowTab');
  const mapTab = document.getElementById('dgModeMapTab');
  const tabStyle = (el, active) => {
    if (!el) return;
    el.style.background = active ? 'var(--pdfed-accent-bg)' : 'var(--surface)';
    el.style.color = active ? 'var(--pdfed-accent)' : 'var(--text2)';
    el.style.borderColor = active ? 'var(--border2)' : 'var(--border)';
  };
  tabStyle(chartTab, isChart);
  tabStyle(flowTab, isFlow);
  tabStyle(mapTab, isMap);

  if (isFlow) dgFlowRender();
}

// ── Info popover: replaces the old always-visible title+description header. Opens on click of the small (i) icon,
// closes on outside click, so the ribbon/canvas keep the space by default. ──
function dgToggleInfoPopover(e) {
  if (e) e.stopPropagation();
  const pop = document.getElementById('dgInfoPopover');
  if (pop) pop.classList.toggle('open');
}
document.addEventListener('click', function(e) {
  const pop = document.getElementById('dgInfoPopover');
  const btn = document.getElementById('dgInfoBtn');
  if (pop && pop.classList.contains('open') && !pop.contains(e.target) && (!btn || !btn.contains(e.target))) {
    pop.classList.remove('open');
  }
});

// ═══════════════════════════════════════════════════════════════════════
// 3D STATISTICAL CHARTS ENGINE (Three.js) — Bar / Histogram / Scatter / Box
// Plot rendered with real depth + mouse-orbit, sharing dgState.rows (the
// same label/value/color data the flat 2D charts use) so switching a
// chart between a flat type and a 3D type keeps the same data intact.
// The WebGL canvas (#dgCanvas3D) lives in the same zoom-wrap slot as the
// 2D <canvas> — only one of the two is ever visible at a time.
// ═══════════════════════════════════════════════════════════════════════
function dgHologramOn() {
  const el = document.getElementById('dgHologramToggle');
  return !!(el && el.checked);
}

const DG_3D_TYPES = ['3d-bar', '3d-grouped-bar', '3d-histogram', '3d-scatter', '3d-boxplot'];
function dgIs3DType(type) { return DG_3D_TYPES.indexOf(type) !== -1; }

// Which chart types each ribbon control actually affects, mirrored from the drawing code:
// - DG_AXES_TYPES matches axisChartTypes in dgDrawChart (only these ever get an x/y axis title).
// - DG_RADIUS_TYPES matches every place opts.barRadius is read (dgDrawBars/GroupedBars/Waterfall/Pareto).
// - DG_TREND_TYPES matches every `if (opts.trendline...)` guard, 2D and 3D.
// - DG_GROWTH_TYPES matches growthEligible in dgDrawChart (single-series, non-grouped only).
// - Hologram applies to every 3D type (DG_3D_TYPES) and nothing else.
const DG_AXES_TYPES = ['bar', 'stacked', 'waterfall', 'pareto', 'line', 'area', 'grouped'];
const DG_RADIUS_TYPES = ['bar', 'stacked', 'grouped', 'waterfall', 'pareto'];
const DG_TREND_TYPES = ['bar', 'line', 'area', '3d-bar', '3d-histogram', '3d-scatter'];
const DG_GROWTH_TYPES = ['bar', 'line', 'area'];

// Grays out (and disables) ribbon controls that don't apply to the currently-selected chart
// type — e.g. Trend/Growth %/Hologram/Radius/Axes on a Pie or Funnel chart — instead of
// leaving them fully clickable while doing nothing when toggled. Map mode already hides this
// whole set of controls via dgSetDgMode's hideWhenMap/chip-hide logic, so this only needs to
// run for Chart mode; it's still safe to call unconditionally since a hidden element staying
// "disabled" underneath has no visible effect.
function dgSyncRibbonForType() {
  const type = (typeof dgState !== 'undefined' && dgState) ? dgState.type : null;
  const setDisabled = (id, enabled) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.classList.toggle('dg-chip-disabled', !enabled);
    el.title = el.title || '';
    if (!enabled && !el.dataset.dgFullTitle) {
      el.dataset.dgFullTitle = el.title;
      el.title = el.title ? el.title + ' — not used by this chart type' : 'Not used by this chart type';
    } else if (enabled && el.dataset.dgFullTitle) {
      el.title = el.dataset.dgFullTitle;
      delete el.dataset.dgFullTitle;
    }
  };
  const setGroupDisabled = (groupId, ddId, enabled) => {
    const el = document.getElementById(groupId);
    if (!el) return;
    el.classList.toggle('dg-chip-disabled', !enabled);
    if (!enabled) {
      const dd = ddId && document.getElementById(ddId);
      if (dd) dd.classList.remove('open');
    }
  };
  if (dgActiveMode === 'map' || !type) return; // map mode's own gating already hides these entirely
  setDisabled('dgTrendChip', DG_TREND_TYPES.includes(type));
  setDisabled('dgGrowthChip', DG_GROWTH_TYPES.includes(type));
  setDisabled('dgHologramChip', dgIs3DType(type));
  setGroupDisabled('dgRadiusGroup', 'dgRadiusDropdown', DG_RADIUS_TYPES.includes(type));
  setGroupDisabled('dgAxesGroup', 'dgAxesDropdown', DG_AXES_TYPES.includes(type));
}

const dg3D = {
  renderer: null, scene: null, camera: null, controls: null,
  group: null, raf: null, active: false, resizeObs: null,
  raycaster: null, pointer: null
};

function dgMakeLabelSprite(text, color) {
  const c = document.createElement('canvas');
  const scale = 4; // supersample so labels stay crisp when the camera gets close
  c.width = 256 * scale; c.height = 64 * scale;
  const ctx = c.getContext('2d');
  ctx.scale(scale, scale);
  ctx.font = '700 26px Inter, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  if (dgHologramOn()) {
    // Bright glowing cyan text on the dark hologram backdrop — keeps the same
    // two-tier brightness (muted grey callouts stay dimmer than primary value
    // labels) so it still reads as a lit projection, not just plain text.
    ctx.fillStyle = (color === '#7a8496') ? '#5FE0FF' : '#EAFBFF';
    ctx.shadowColor = '#00E5FF';
    ctx.shadowBlur = 14;
  } else {
    ctx.fillStyle = color || '#1a2230';
  }
  ctx.fillText(String(text), 128, 32);
  const tex = new THREE.CanvasTexture(c);
  tex.minFilter = THREE.LinearFilter;
  const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false });
  const sprite = new THREE.Sprite(mat);
  sprite.scale.set(3.2, 0.8, 1);
  return sprite;
}

// Larger banner sprite for the chart title, floated above everything.
function dgMakeTitleSprite(text) {
  const c = document.createElement('canvas');
  const scale = 3;
  c.width = 700 * scale; c.height = 80 * scale;
  const ctx = c.getContext('2d');
  ctx.scale(scale, scale);
  ctx.font = '800 34px Inter, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  if (dgHologramOn()) {
    ctx.fillStyle = '#EAFBFF';
    ctx.shadowColor = '#00E5FF';
    ctx.shadowBlur = 18;
  } else {
    ctx.fillStyle = '#101820';
  }
  ctx.fillText(dgFitLabel(ctx, String(text), 660), 350, 40);
  const tex = new THREE.CanvasTexture(c);
  tex.minFilter = THREE.LinearFilter;
  const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false });
  const sprite = new THREE.Sprite(mat);
  sprite.scale.set(7.2, 0.82, 1);
  return sprite;
}

// Small uppercase caption sprite used for axis titles ("VALUE", "FREQUENCY", etc).
function dgMakeAxisCaptionSprite(text) {
  const c = document.createElement('canvas');
  const scale = 4;
  c.width = 320 * scale; c.height = 56 * scale;
  const ctx = c.getContext('2d');
  ctx.scale(scale, scale);
  ctx.font = '800 21px Inter, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  if (dgHologramOn()) {
    ctx.fillStyle = '#00E5FF';
    ctx.shadowColor = '#00E5FF';
    ctx.shadowBlur = 12;
  } else {
    ctx.fillStyle = '#0073E6';
  }
  ctx.fillText(String(text).toUpperCase(), 160, 28);
  const tex = new THREE.CanvasTexture(c);
  tex.minFilter = THREE.LinearFilter;
  const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false });
  const sprite = new THREE.Sprite(mat);
  sprite.scale.set(3.0, 0.52, 1);
  return sprite;
}

function dgInit3DEngine() {
  if (dg3D.renderer) return;
  const canvas = document.getElementById('dgCanvas3D');
  if (!canvas || typeof THREE === 'undefined') return;
  const W = canvas.width, H = canvas.height;
  // Keep the original CSS-pixel size around: three.js's setSize() takes CSS
  // pixels and multiplies internally by the pixel ratio, so later resolution
  // updates (see dg3DUpdateResolutionForZoom) must keep reusing these base
  // values rather than reading canvas.width/height back (which, after the
  // first setSize call, already holds the multiplied drawing-buffer size).
  dg3D.baseW = W; dg3D.baseH = H;

  dg3D.renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: false, preserveDrawingBuffer: true, powerPreference: 'high-performance' });
  dg3D.baseDPR = Math.min(window.devicePixelRatio || 1, 3); // baseline device-pixel density, a bit higher than before for sharper text/edges
  dg3D.renderer.setPixelRatio(dg3D.baseDPR);
  dg3D.renderer.setSize(W, H, false);
  dg3D.renderer.setClearColor(0xffffff, 1);

  dg3D.scene = new THREE.Scene();
  dg3D.camera = new THREE.PerspectiveCamera(42, W / H, 0.1, 200);
  dg3D.camera.position.set(11, 9, 13);

  dg3D.ambientLight = new THREE.AmbientLight(0xffffff, 0.65);
  dg3D.scene.add(dg3D.ambientLight);
  const key = new THREE.DirectionalLight(0xffffff, 0.75);
  key.position.set(8, 14, 10);
  dg3D.scene.add(key);
  dg3D.keyLight = key;
  const fill = new THREE.DirectionalLight(0xaeeaff, 0.3);
  fill.position.set(-8, 4, -6);
  dg3D.scene.add(fill);
  dg3D.fillLight = fill;

  if (THREE.OrbitControls) {
    dg3D.controls = new THREE.OrbitControls(dg3D.camera, canvas);
    dg3D.controls.enableDamping = true;
    dg3D.controls.dampingFactor = 0.08;
    dg3D.controls.minDistance = 5;
    dg3D.controls.maxDistance = 40;
    dg3D.controls.maxPolarAngle = Math.PI * 0.49; // never dip below the floor grid
    dg3D.controls.target.set(0, 0.5, 0);
  }

  dg3D.group = new THREE.Group();
  dg3D.scene.add(dg3D.group);

  // Hover tooltip: raycast against whatever's tagged userData.dgHover, so
  // the exact label + value behind any bar/point/box is always one hover
  // away instead of relying only on the always-on floating value labels.
  dg3D.raycaster = new THREE.Raycaster();
  dg3D.pointer = new THREE.Vector2();
  canvas.addEventListener('pointermove', dg3DOnPointerMove);
  canvas.addEventListener('pointerleave', dg3DOnPointerLeave);
}

// The zoom control (dgApplyZoom) zooms the whole preview via a CSS transform:
// scale() on the wrapper. That's fine for the 2D <canvas>, which gets redrawn
// at native resolution on every dgRender(), but the 3D WebGL canvas is only
// ever rendered once per frame at its own fixed drawing-buffer resolution —
// so stretching it larger via CSS scale was blowing up its existing pixels
// (blur/pixelation) instead of rendering more of them. Fix: whenever the zoom
// level changes, bump the renderer's actual pixel ratio to match, so the
// drawing buffer always has enough real pixels for the zoomed-in display size.
function dg3DUpdateResolutionForZoom(zoom) {
  if (!dg3D.renderer) return;
  const base = dg3D.baseDPR || Math.min(window.devicePixelRatio || 1, 3);
  // Cap the combined ratio so we don't ask the GPU for an absurdly large
  // framebuffer at high zoom on an already-high-DPI screen.
  const effective = Math.min(base * Math.max(zoom || 1, 1), 6);
  dg3D.renderer.setPixelRatio(effective);
  const canvas = dg3D.renderer.domElement;
  // Reuse the ORIGINAL css-pixel dimensions (not canvas.width/height, which
  // already holds the previous pixelRatio-multiplied drawing-buffer size) —
  // three.js multiplies these by the new pixel ratio internally.
  dg3D.renderer.setSize(dg3D.baseW || canvas.width, dg3D.baseH || canvas.height, false);
  if (dg3D.active && dg3D.renderer && dg3D.scene && dg3D.camera) {
    dg3D.renderer.render(dg3D.scene, dg3D.camera);
  }
}
window.dg3DUpdateResolutionForZoom = dg3DUpdateResolutionForZoom;

function dg3DOnPointerMove(e) {
  if (!dg3D.active || !dg3D.renderer || !dg3D.group) return;
  const canvas = dg3D.renderer.domElement;
  const rect = canvas.getBoundingClientRect();
  dg3D.pointer.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  dg3D.pointer.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  dg3D.raycaster.setFromCamera(dg3D.pointer, dg3D.camera);
  const hoverable = dg3D.group.children.filter(o => o.userData && o.userData.dgHover);
  const hits = dg3D.raycaster.intersectObjects(hoverable, false);
  const tooltip = document.getElementById('dg3DTooltip');
  if (!tooltip) return;
  if (hits.length) {
    const d = hits[0].object.userData;
    tooltip.innerHTML = '<div class="dg-3d-tt-title">' + dgEsc(d.label || '') + '</div>' +
      (d.sub ? '<div class="dg-3d-tt-sub">' + dgEsc(d.sub) + '</div>' : '');
    tooltip.style.display = 'block';
    const holderRect = document.getElementById('dgCanvasHolder').getBoundingClientRect();
    tooltip.style.left = (e.clientX - holderRect.left + document.getElementById('dgCanvasHolder').scrollLeft) + 'px';
    tooltip.style.top = (e.clientY - holderRect.top + document.getElementById('dgCanvasHolder').scrollTop - 12) + 'px';
    canvas.style.cursor = 'pointer';
  } else {
    tooltip.style.display = 'none';
    canvas.style.cursor = 'grab';
  }
}
function dg3DOnPointerLeave() {
  const tooltip = document.getElementById('dg3DTooltip');
  if (tooltip) tooltip.style.display = 'none';
}

function dgClear3DGroup() {
  if (!dg3D.group) return;
  while (dg3D.group.children.length) {
    const obj = dg3D.group.children.pop();
    if (obj.geometry) obj.geometry.dispose();
    if (obj.material) {
      if (obj.material.map) obj.material.map.dispose();
      obj.material.dispose();
    }
    dg3D.group.remove(obj);
  }
}

function dg3DAddFloor(halfSize) {
  const holo = dgHologramOn();
  const grid = holo
    ? new THREE.GridHelper(halfSize * 2, 10, 0x00E5FF, 0x0C3A52)
    : new THREE.GridHelper(halfSize * 2, 10, 0xd6dde6, 0xe9edf2);
  grid.position.y = 0;
  if (holo) {
    grid.material.transparent = true;
    grid.material.opacity = 0.65;
  }
  dg3D.group.add(grid);

  if (holo) {
    // Projector-base glow: a soft radial-gradient disc sitting right on the
    // floor, like the light pool a hologram emitter would be projecting up
    // from — this, plus the dim scene lighting (see dg3DApplyHologramMood),
    // is what sells "hologram" instead of just "dark chart".
    const glowCanvas = document.createElement('canvas');
    glowCanvas.width = glowCanvas.height = 256;
    const gctx = glowCanvas.getContext('2d');
    const grad = gctx.createRadialGradient(128, 128, 0, 128, 128, 128);
    grad.addColorStop(0, 'rgba(0,229,255,0.55)');
    grad.addColorStop(0.5, 'rgba(0,194,255,0.18)');
    grad.addColorStop(1, 'rgba(0,194,255,0)');
    gctx.fillStyle = grad;
    gctx.fillRect(0, 0, 256, 256);
    const glowTex = new THREE.CanvasTexture(glowCanvas);
    const glowMat = new THREE.MeshBasicMaterial({ map: glowTex, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending });
    const glowDisc = new THREE.Mesh(new THREE.CircleGeometry(halfSize * 0.9, 48), glowMat);
    glowDisc.rotation.x = -Math.PI / 2;
    glowDisc.position.y = 0.01;
    glowDisc.userData.dgHoloGlow = true; // tagged so the flicker loop can pulse it
    dg3D.group.add(glowDisc);
  }
}

function dg3DPalette() {
  const scheme = dgCurrentScheme();
  return dgState.rows.map((r, i) => new THREE.Color(r.color || scheme[i % scheme.length]));
}

// Dashed regression line through a series of 3D points — the 3D counterpart
// to dgDrawTrendline on the 2D canvas, so the "Trend" toggle does the same
// job (and uses the same red dashed styling + "Trend" tag) in both views.
function dg3DAddTrendline(pts) {
  if (!pts || pts.length < 2) return;
  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  const mat = new THREE.LineDashedMaterial({ color: 0xef4444, dashSize: 0.3, gapSize: 0.18, linewidth: 2, transparent: true, opacity: 0.9 });
  const line = new THREE.Line(geo, mat);
  line.computeLineDistances();
  dg3D.group.add(line);
  const last = pts[pts.length - 1];
  const label = dgMakeLabelSprite('Trend', '#ef4444');
  label.position.set(last.x, last.y + 0.45, last.z);
  label.scale.set(1.3, 0.35, 1);
  dg3D.group.add(label);
}

// Vertical value axis with tick marks + numeric labels, so the height/size
// encoding on every 3D chart maps back to an actual number at a glance —
// not just a relative floating label on each shape.
function dg3DAddValueAxis({ x, z, worldMax, valueAtFrac, caption, tickCount }) {
  tickCount = tickCount || 4;
  const rodGeo = new THREE.CylinderGeometry(0.025, 0.025, worldMax, 8);
  const rod = new THREE.Mesh(rodGeo, new THREE.MeshBasicMaterial({ color: 0xb9c2cc }));
  rod.position.set(x, worldMax / 2, z);
  dg3D.group.add(rod);
  for (let t = 0; t <= tickCount; t++) {
    const frac = t / tickCount;
    const wy = frac * worldMax;
    const tick = new THREE.Mesh(new THREE.BoxGeometry(0.24, 0.02, 0.24), new THREE.MeshBasicMaterial({ color: 0xb9c2cc }));
    tick.position.set(x, wy, z);
    dg3D.group.add(tick);
    const lab = dgMakeLabelSprite(dgFormatValueForOpts(valueAtFrac(frac)), '#7a8496');
    lab.scale.set(1.5, 0.4, 1);
    lab.position.set(x - 0.95, wy, z);
    dg3D.group.add(lab);
  }
  if (caption) {
    const cap = dgMakeAxisCaptionSprite(caption);
    cap.position.set(x - 1.7, worldMax + 0.55, z);
    dg3D.group.add(cap);
  }
}

function dg3DAddTitleAndCaptions(opts) {
  const title = (opts.title || '').trim();
  if (title) {
    const t = dgMakeTitleSprite(title);
    t.position.set(0, 8.4, 0);
    dg3D.group.add(t);
  }
}

// ── 3D Bar: one extruded column per row, height = value ──
function dg3DBuildBar() {
  const rows = dgState.rows;
  const opts = dgGetOpts();
  dgClear3DGroup();
  if (!rows.length) return;
  const maxV = Math.max(1, ...rows.map(r => Math.abs(Number(r.value) || 0)));
  const n = rows.length;
  const spacing = 2.1;
  const totalW = (n - 1) * spacing;
  dg3DAddFloor(Math.max(6, totalW / 2 + 3));
  const colors = dg3DPalette();

  rows.forEach((r, i) => {
    const v = Number(r.value) || 0;
    const h = Math.max(0.05, (Math.abs(v) / maxV) * 6.5);
    const geo = new THREE.BoxGeometry(1.1, h, 1.1);
    const mat = new THREE.MeshStandardMaterial({ color: colors[i], metalness: 0.15, roughness: 0.45 });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.set(i * spacing - totalW / 2, h / 2, 0);
    mesh.userData = { dgHover: true, label: r.label || ('Item ' + (i + 1)), sub: dgFormatValueForOpts(v) };
    dg3D.group.add(mesh);

    if (opts.values) {
      const valLabel = dgMakeLabelSprite(dgFormatValueForOpts(v), '#1a2230');
      valLabel.position.set(mesh.position.x, h + 0.55, 0);
      dg3D.group.add(valLabel);
    }

    const nameLabel = dgMakeLabelSprite(r.label || ('Item ' + (i + 1)), '#7a8496');
    nameLabel.position.set(mesh.position.x, -0.55, 1.0);
    nameLabel.scale.set(2.6, 0.65, 1);
    dg3D.group.add(nameLabel);
  });

  dg3DAddValueAxis({
    x: -totalW / 2 - 1.7, z: -0.2, worldMax: 6.5,
    valueAtFrac: f => f * maxV,
    caption: opts.yAxisTitle || 'Value'
  });
  const xCap = dgMakeAxisCaptionSprite(opts.xAxisTitle || 'Category');
  xCap.position.set(0, -1.15, 2.3);
  dg3D.group.add(xCap);
  if (opts.trendline && rows.length > 1) {
    const { slope, intercept } = dgLinearRegression(rows.map(r => Number(r.value) || 0));
    const pts = rows.map((r, i) => {
      const predicted = slope * i + intercept;
      const hPred = Math.max(0.05, (Math.abs(predicted) / maxV) * 6.5);
      return new THREE.Vector3(i * spacing - totalW / 2, hPred, 0);
    });
    dg3DAddTrendline(pts);
  }
  dg3DAddTitleAndCaptions(opts);
}

// ── 3D Grouped Bar: same categories/series as the flat Grouped Bar chart, rendered as
// clustered 3D columns — each category gets a slot on the X axis, and every series
// ("Profit 2025", "Profit 2026", ...) gets its own colour-coded bar placed side-by-side
// within that slot, mirroring how the 2D grouped bar chart lays things out. Every mesh this
// builds is a plain THREE.Mesh with real geometry, so it needs no special-casing to pick up
// Hologram mode — dg3DApplyHologramMaterials (called generically by dg3DBuild for every 3D
// type) re-skins it exactly like a 3D Bar chart. ──
function dg3DBuildGroupedBar() {
  let categories = dgState.groupedCategories || [];
  let series = dgState.groupedSeries || [];
  // Safety net: the live editor's grouped state can be empty if the user switched to this
  // type before ever loading a grouped chart (e.g. straight from the gallery, or after a
  // page reload). Rather than silently render nothing, fall back to the first grouped spec
  // still sitting in the chart gallery and sync it into dgState so it sticks.
  if ((!categories.length || !series.length) && Array.isArray(dgMultiCharts) && dgMultiCharts.length) {
    const fallback = dgMultiCharts.find(s => s.type === 'grouped');
    if (fallback) {
      dgState.groupedCategories = categories = fallback.categories.slice();
      dgState.groupedSeries = series = fallback.series.map(s => ({ ...s, values: s.values.slice() }));
    }
  }
  const opts = dgGetOpts();
  dgClear3DGroup();
  if (!categories.length || !series.length) {
    toast('No grouped chart loaded yet \u2014 build or pick one from the chart gallery first', 'info');
    return;
  }

  const n = categories.length;
  const s = series.length;
  const maxV = Math.max(1, ...series.flatMap(sr => sr.values.map(v => Math.abs(Number(v) || 0))));
  // Series bars sit side-by-side along X within each category's slot (a classic clustered-column
  // layout), not staggered along Z depth. Z-depth separation used to collapse visually once the
  // camera zoomed out to fit many categories — a tiny depth gap between bars a few units apart on
  // X becomes imperceptible from that distance, making multi-series data look like one bar per
  // category. Side-by-side bars stay visually distinct at any camera distance or category count.
  const barW = Math.max(0.34, Math.min(0.72, 2.0 / s));
  const barGap = 0.22;
  const barPitch = barW + barGap;
  const clusterWidth = s * barPitch;
  const catSpacing = Math.max(2.6, clusterWidth + 1.6);
  const boxDepth = 0.85, boxHalfDepth = boxDepth / 2;
  const totalW = (n - 1) * catSpacing;
  dg3DAddFloor(Math.max(6, totalW / 2 + 3, clusterWidth / 2 + 3));

  // Value-label sprites default to a fixed width sized for a single bar with room to spare —
  // fine when bars are far apart, but with 2-3 narrow bars sharing one category slot that fixed
  // width is wider than the gap between them, so neighbouring numbers overlap into an unreadable
  // smear. Scale the label to the room actually available, and alternate its height between
  // series within a cluster, so adjacent numbers land in different rows instead of on top of
  // each other regardless of how tight the bars are packed.
  const valueLabelW = Math.max(0.95, Math.min(3.2, barPitch * 2.3));
  const nameLabelW = Math.min(2.6, catSpacing * 0.92);

  categories.forEach((cat, ci) => {
    const xCenter = ci * catSpacing - totalW / 2;
    series.forEach((sr, si) => {
      const v = Number(sr.values[ci]) || 0;
      const h = Math.max(0.05, (Math.abs(v) / maxV) * 6.5);
      const x = xCenter + (si - (s - 1) / 2) * barPitch;
      const z = 0;
      const geo = new THREE.BoxGeometry(barW, h, boxDepth);
      const mat = new THREE.MeshStandardMaterial({ color: new THREE.Color(sr.color), metalness: 0.15, roughness: 0.45 });
      const mesh = new THREE.Mesh(geo, mat);
      mesh.position.set(x, h / 2, z);
      mesh.userData = { dgHover: true, label: cat + ' \u2014 ' + sr.name, sub: dgFormatValueForOpts(v) };
      dg3D.group.add(mesh);

      if (opts.values) {
        const valLabel = dgMakeLabelSprite(dgFormatValueForOpts(v), '#1a2230');
        valLabel.scale.set(valueLabelW, 0.6, 1);
        const stagger = (s > 1 && si % 2 === 1) ? 0.5 : 0;
        valLabel.position.set(x, h + 0.5 + stagger, z);
        dg3D.group.add(valLabel);
      }
    });

    const nameLabel = dgMakeLabelSprite(cat, '#7a8496');
    nameLabel.position.set(xCenter, -0.55, boxHalfDepth + 1.0);
    nameLabel.scale.set(nameLabelW, 0.65, 1);
    dg3D.group.add(nameLabel);
  });

  // A colour-keyed series legend along the right edge — the only thing telling the
  // "Profit 2025" bars apart from the "Profit 2026" bars by name, since colour alone
  // can be hard to eyeball precisely in 3D.
  series.forEach((sr, si) => {
    const legendLabel = dgMakeLabelSprite(sr.name, sr.color);
    legendLabel.position.set(totalW / 2 + 2.3, 6.4 - si * 0.85, 0);
    legendLabel.scale.set(2.5, 0.62, 1);
    dg3D.group.add(legendLabel);
  });

  dg3DAddValueAxis({
    x: -totalW / 2 - 1.7, z: -boxHalfDepth - 0.6, worldMax: 6.5,
    valueAtFrac: f => f * maxV,
    caption: opts.yAxisTitle || 'Value'
  });
  const xCap = dgMakeAxisCaptionSprite(opts.xAxisTitle || 'Category');
  xCap.position.set(0, -1.15, boxHalfDepth + 2.3);
  dg3D.group.add(xCap);
  dg3DAddTitleAndCaptions(opts);
}

// ── 3D Histogram: bins the same values into frequency buckets, so it reads
// as a true statistical distribution rather than one bar per row. ──
function dg3DBuildHistogram() {
  const rows = dgState.rows;
  const opts = dgGetOpts();
  dgClear3DGroup();
  if (!rows.length) return;
  const values = rows.map(r => Number(r.value) || 0);
  const min = Math.min(...values), max = Math.max(...values);
  const binCount = Math.max(3, Math.min(8, Math.ceil(Math.sqrt(values.length)) + 2));
  const span = (max - min) || 1;
  const binW = span / binCount;
  const bins = new Array(binCount).fill(0);
  values.forEach(v => {
    let idx = Math.floor((v - min) / binW);
    if (idx >= binCount) idx = binCount - 1;
    if (idx < 0) idx = 0;
    bins[idx]++;
  });
  const maxFreq = Math.max(1, ...bins);
  const spacing = 2.1;
  const totalW = (binCount - 1) * spacing;
  dg3DAddFloor(Math.max(6, totalW / 2 + 3));
  const scheme = dgCurrentScheme();

  bins.forEach((freq, i) => {
    const h = Math.max(0.05, (freq / maxFreq) * 6.5);
    const rangeLo = min + i * binW, rangeHi = rangeLo + binW;
    const geo = new THREE.BoxGeometry(1.3, h, 1.3);
    const mat = new THREE.MeshStandardMaterial({ color: new THREE.Color(scheme[i % scheme.length]), metalness: 0.15, roughness: 0.45 });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.set(i * spacing - totalW / 2, h / 2, 0);
    mesh.userData = {
      dgHover: true,
      label: dgFormatValueForOpts(rangeLo) + ' – ' + dgFormatValueForOpts(rangeHi),
      sub: freq + (freq === 1 ? ' item' : ' items')
    };
    dg3D.group.add(mesh);

    if (opts.values) {
      const freqLabel = dgMakeLabelSprite(String(freq), '#1a2230');
      freqLabel.position.set(mesh.position.x, h + 0.55, 0);
      dg3D.group.add(freqLabel);
    }

    const rangeLabel = dgMakeLabelSprite(dgFormatValueForOpts(rangeLo) + '–' + dgFormatValueForOpts(rangeHi), '#7a8496');
    rangeLabel.position.set(mesh.position.x, -0.55, 1.2);
    rangeLabel.scale.set(2.8, 0.6, 1);
    dg3D.group.add(rangeLabel);
  });

  dg3DAddValueAxis({
    x: -totalW / 2 - 1.7, z: -0.2, worldMax: 6.5,
    valueAtFrac: f => Math.round(f * maxFreq),
    caption: opts.yAxisTitle || 'Frequency'
  });
  const xCap = dgMakeAxisCaptionSprite(opts.xAxisTitle || 'Value range');
  xCap.position.set(0, -1.15, 2.3);
  dg3D.group.add(xCap);
  if (opts.trendline && bins.length > 1) {
    const { slope, intercept } = dgLinearRegression(bins);
    const pts = bins.map((freq, i) => {
      const predicted = slope * i + intercept;
      const hPred = Math.max(0.05, (Math.abs(predicted) / maxFreq) * 6.5);
      return new THREE.Vector3(i * spacing - totalW / 2, hPred, 0);
    });
    dg3DAddTrendline(pts);
  }
  dg3DAddTitleAndCaptions(opts);
}

// ── 3D Scatter/Bubble: X = row order, Y = value (normalized), Z = a second
// spread axis so points don't all sit on one line; sphere radius doubles as
// the bubble-size encoding when values vary a lot. ──
function dg3DBuildScatter() {
  const rows = dgState.rows;
  const opts = dgGetOpts();
  dgClear3DGroup();
  if (!rows.length) return;
  const values = rows.map(r => Number(r.value) || 0);
  const maxV = Math.max(1, ...values.map(Math.abs));
  const minV = Math.min(...values);
  const n = rows.length;
  const spanX = 10;
  dg3DAddFloor(7);
  const colors = dg3DPalette();

  rows.forEach((r, i) => {
    const v = values[i];
    const x = n > 1 ? (i / (n - 1)) * spanX - spanX / 2 : 0;
    const y = Math.max(0.3, (Math.abs(v) / maxV) * 6 + 0.3);
    // deterministic depth spread from the value itself (not random), so
    // re-rendering the same data always produces the same layout
    const z = ((v - minV) / (maxV - minV || 1) - 0.5) * 6;
    const r3 = 0.28 + (Math.abs(v) / maxV) * 0.55;
    const geo = new THREE.SphereGeometry(r3, 24, 18);
    const mat = new THREE.MeshStandardMaterial({ color: colors[i], metalness: 0.1, roughness: 0.35 });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.set(x, y, z);
    mesh.userData = { dgHover: true, label: r.label || ('Item ' + (i + 1)), sub: dgFormatValueForOpts(v) + ' · bubble size = value' };
    dg3D.group.add(mesh);

    // thin stem down to the floor so depth is easy to read at a glance
    const stemGeo = new THREE.CylinderGeometry(0.02, 0.02, y, 6);
    const stemMat = new THREE.MeshBasicMaterial({ color: 0xd6dde6 });
    const stem = new THREE.Mesh(stemGeo, stemMat);
    stem.position.set(x, y / 2, z);
    dg3D.group.add(stem);

    const label = dgMakeLabelSprite(r.label || ('Item ' + (i + 1)), '#7a8496');
    label.position.set(x, y + r3 + 0.5, z);
    dg3D.group.add(label);

    if (opts.values) {
      const valLabel = dgMakeLabelSprite(dgFormatValueForOpts(v), '#1a2230');
      valLabel.position.set(x, y + r3 + 0.9, z);
      dg3D.group.add(valLabel);
    }
  });

  if (opts.trendline && rows.length > 1) {
    const { slope, intercept } = dgLinearRegression(values);
    const predictedPts = rows.map((r, i) => {
      const x = n > 1 ? (i / (n - 1)) * spanX - spanX / 2 : 0;
      const predicted = slope * i + intercept;
      const y = Math.max(0.3, (Math.abs(predicted) / maxV) * 6 + 0.3);
      return new THREE.Vector3(x, y, 0);
    });
    dg3DAddTrendline(predictedPts);
  }

  dg3DAddValueAxis({
    x: -spanX / 2 - 1.7, z: -3.4, worldMax: 6.3,
    valueAtFrac: f => Math.max(0, (f * 6.3 - 0.3) / 6 * maxV),
    caption: opts.yAxisTitle || 'Value (height)'
  });
  const xCap = dgMakeAxisCaptionSprite(opts.xAxisTitle || 'Items, in order');
  xCap.position.set(0, -1.15, 4.4);
  dg3D.group.add(xCap);
  dg3DAddTitleAndCaptions(opts);
}

// ── 3D Box Plot: classic five-number summary (min, Q1, median, Q3, max) of
// all row values, drawn as a single box + whiskers so the whole dataset's
// spread and skew reads as one statistical shape. ──
function dg3DBuildBoxPlot() {
  const rows = dgState.rows;
  const opts = dgGetOpts();
  dgClear3DGroup();
  if (!rows.length) return;
  const values = rows.map(r => Number(r.value) || 0).sort((a, b) => a - b);
  const q = p => {
    const idx = (values.length - 1) * p;
    const lo = Math.floor(idx), hi = Math.ceil(idx);
    return lo === hi ? values[lo] : values[lo] + (values[hi] - values[lo]) * (idx - lo);
  };
  const min = values[0], max = values[values.length - 1];
  const q1 = q(0.25), median = q(0.5), q3 = q(0.75);
  const span = (max - min) || 1;
  const scale = 6.5 / span;
  const toY = v => (v - min) * scale;
  dg3DAddFloor(5);
  const scheme = dgCurrentScheme();

  // whisker (min → max), a thin vertical rod
  const whiskerGeo = new THREE.CylinderGeometry(0.035, 0.035, toY(max) - toY(min), 8);
  const whisker = new THREE.Mesh(whiskerGeo, new THREE.MeshBasicMaterial({ color: 0x9aa5b3 }));
  whisker.position.set(0, (toY(max) + toY(min)) / 2, 0);
  dg3D.group.add(whisker);
  [['Minimum', min], ['Maximum', max]].forEach(([name, v]) => {
    const capGeo = new THREE.BoxGeometry(1.0, 0.04, 1.0);
    const cap = new THREE.Mesh(capGeo, new THREE.MeshBasicMaterial({ color: 0x9aa5b3 }));
    cap.position.set(0, toY(v), 0);
    cap.userData = { dgHover: true, label: name, sub: dgFormatValueForOpts(v) };
    dg3D.group.add(cap);
  });

  // the box itself: Q1 → Q3
  const boxH = Math.max(0.08, toY(q3) - toY(q1));
  const boxGeo = new THREE.BoxGeometry(2.2, boxH, 2.2);
  const boxMat = new THREE.MeshStandardMaterial({ color: new THREE.Color(scheme[0]), metalness: 0.15, roughness: 0.4, transparent: true, opacity: 0.88 });
  const box = new THREE.Mesh(boxGeo, boxMat);
  box.position.set(0, toY(q1) + boxH / 2, 0);
  box.userData = {
    dgHover: true, label: 'Interquartile range (Q1–Q3)',
    sub: dgFormatValueForOpts(q1) + ' – ' + dgFormatValueForOpts(q3) + ' · middle 50% of values'
  };
  dg3D.group.add(box);

  // median line, a flat slab through the box
  const medGeo = new THREE.BoxGeometry(2.35, 0.05, 2.35);
  const med = new THREE.Mesh(medGeo, new THREE.MeshBasicMaterial({ color: new THREE.Color(scheme[3] || '#1a2230') }));
  med.position.set(0, toY(median), 0);
  med.userData = { dgHover: true, label: 'Median', sub: dgFormatValueForOpts(median) };
  dg3D.group.add(med);

  if (opts.values) {
    [['Max', max], ['Q3', q3], ['Median', median], ['Q1', q1], ['Min', min]].forEach(([name, v]) => {
      const label = dgMakeLabelSprite(name + ': ' + dgFormatValueForOpts(v), '#1a2230');
      label.position.set(1.9, toY(v), 0);
      dg3D.group.add(label);
    });
  }

  const yCap = dgMakeAxisCaptionSprite(opts.yAxisTitle || 'Value');
  yCap.position.set(-2.1, toY(max) + 0.6, 0);
  dg3D.group.add(yCap);
  const summaryCap = dgMakeAxisCaptionSprite((rows.length) + ' data points summarized');
  summaryCap.position.set(0, -1.15, 1.8);
  dg3D.group.add(summaryCap);
  dg3DAddTitleAndCaptions(opts);
}

function dgFormatValueForOpts(v) {
  try { return dgFormatNumber(v, dgGetOpts().numberFormat); } catch (e) { return String(Math.round(v * 100) / 100); }
}

// Row edits (colour, value, label, add/remove) previously only called
// dgDrawChart(), which repaints the 2D <canvas> — invisible while a 3D chart
// type is active, since the WebGL scene is only ever rebuilt on chart-type
// switch. This wrapper keeps the currently-visible view in sync: it always
// repaints the 2D canvas (cheap, and needed for export/thumbnails), and also
// rebuilds + re-renders the 3D scene live whenever it's the one on screen —
// so picking a new colour, editing a value, or adding/removing a row shows
// up immediately in the 3D view too, not just after switching chart types.
function dgRefreshChart() {
  if (dg3D.active && dg3D.renderer) {
    dg3DBuild(dgState.type);
    if (dg3D.scene && dg3D.camera) dg3D.renderer.render(dg3D.scene, dg3D.camera);
  } else {
    dgDrawChart();
  }
}

function dg3DApplyHologramMood(holo) {
  if (!dg3D.renderer) return;
  dg3D.renderer.setClearColor(holo ? 0x030A14 : 0xffffff, 1);
  // Dim the normal studio lighting so the emissive glow on each shape does the
  // work of reading as "lit from within" rather than lit from a lamp — a
  // hologram doesn't cast conventional highlights.
  if (dg3D.ambientLight) dg3D.ambientLight.intensity = holo ? 0.22 : 0.65;
  if (dg3D.keyLight) dg3D.keyLight.intensity = holo ? 0.2 : 0.75;
  if (dg3D.fillLight) dg3D.fillLight.intensity = holo ? 0.15 : 0.3;
}

// Re-skins every solid shape the chart just built (bars, boxplot box, scatter
// spheres, histogram columns, axis rods/ticks — anything with real geometry)
// into a translucent glowing panel with a crisp neon wireframe edge, the
// classic sci-fi "projected" look, without touching the underlying geometry,
// position, or hover data those shapes already carry.
function dg3DApplyHologramMaterials() {
  if (!dg3D.group) return;
  const shapes = dg3D.group.children.filter(o => o.isMesh && o.geometry && !o.userData.dgHoloGlow);
  const edgeLines = [];
  shapes.forEach(mesh => {
    const baseColor = (mesh.material && mesh.material.color) ? mesh.material.color.clone() : new THREE.Color(0x00C2FF);
    mesh.material.dispose();
    mesh.material = new THREE.MeshStandardMaterial({
      color: baseColor, emissive: baseColor, emissiveIntensity: 0.85,
      transparent: true, opacity: 0.38, roughness: 0.3, metalness: 0.05,
      depthWrite: false
    });
    const edges = new THREE.LineSegments(
      new THREE.EdgesGeometry(mesh.geometry),
      new THREE.LineBasicMaterial({ color: 0x00E5FF, transparent: true, opacity: 0.95 })
    );
    edges.position.copy(mesh.position);
    edges.rotation.copy(mesh.rotation);
    edges.scale.copy(mesh.scale);
    edges.userData.dgHoloEdge = true;
    edgeLines.push(edges);
  });
  edgeLines.forEach(l => dg3D.group.add(l));
}

function dg3DBuild(type) {
  const holo = dgHologramOn();
  dg3DApplyHologramMood(holo);
  if (type === '3d-bar') dg3DBuildBar();
  else if (type === '3d-grouped-bar') dg3DBuildGroupedBar();
  else if (type === '3d-histogram') dg3DBuildHistogram();
  else if (type === '3d-scatter') dg3DBuildScatter();
  else if (type === '3d-boxplot') dg3DBuildBoxPlot();
  if (holo) dg3DApplyHologramMaterials();
  // The camera used to sit at one fixed position (11,9,13) regardless of what was just
  // built, so a dataset with more bars/clusters than usual — or the series legend, which
  // is placed further out the more series there are — could end up outside the frustum
  // and get clipped at the edge of the view. Re-fit every rebuild instead.
  dg3DFitCameraToScene();
}

// Reframes the camera around whatever geometry was just built. Keeps the same viewing
// angle (a corner/overhead look, not straight-on) and only changes the distance, so the
// familiar tilt is preserved — but the distance is now derived from the actual bounding
// box of the scene (bars, clusters, axis labels, AND the series legend sprites) instead
// of a fixed guess. This is what keeps the legend and outer bars from being cut off on
// larger datasets while still framing small datasets tightly instead of leaving them
// floating in a sea of empty space.
function dg3DFitCameraToScene() {
  if (!dg3D.camera || !dg3D.group || typeof THREE === 'undefined') return;
  const box = new THREE.Box3().setFromObject(dg3D.group);
  if (box.isEmpty()) return;
  const size = box.getSize(new THREE.Vector3());
  const center = box.getCenter(new THREE.Vector3());
  const maxDim = Math.max(size.x, size.y, size.z, 1);
  const fovRad = (dg3D.camera.fov * Math.PI) / 180;
  // Distance needed for the widest dimension to fit inside the vertical FOV, padded for
  // the camera's off-axis angle (it's looking in from a corner, so the effective frame is
  // narrower than a straight-on shot) plus a small margin so nothing sits flush on the edge.
  const dist = Math.max(9, (maxDim / (2 * Math.tan(fovRad / 2))) * 1.65 + 3);
  const dir = new THREE.Vector3(11, 9, 13).normalize();
  dg3D.camera.position.set(center.x + dir.x * dist, center.y + dir.y * dist + 1, center.z + dir.z * dist);
  dg3D.camera.near = Math.max(0.1, dist / 100);
  dg3D.camera.far = dist * 8;
  dg3D.camera.updateProjectionMatrix();
  if (dg3D.controls) {
    dg3D.controls.target.set(center.x, center.y * 0.6, center.z);
    dg3D.controls.maxDistance = Math.max(40, dist * 2);
    dg3D.controls.update();
  }
}

function dg3DAnimate() {
  if (!dg3D.active) return;
  dg3D.raf = requestAnimationFrame(dg3DAnimate);
  if (dg3D.controls) dg3D.controls.update();
  if (dgHologramOn() && dg3D.group) dg3DHologramFlicker();
  if (dg3D.renderer && dg3D.scene && dg3D.camera) dg3D.renderer.render(dg3D.scene, dg3D.camera);
}

// Subtle, continuous brightness jitter on every glowing shape/edge/glow-disc —
// a real hologram projection never sits perfectly still, so a tiny sine-wave
// wobble (plus occasional micro-glitches) is what keeps it feeling "alive"
// rather than like a static tinted render.
function dg3DHologramFlicker() {
  const t = performance.now() * 0.001;
  const base = 0.85 + Math.sin(t * 2.3) * 0.08 + (Math.sin(t * 17) > 0.985 ? 0.25 : 0);
  dg3D.group.children.forEach(o => {
    if (o.isMesh && o.material && o.material.emissiveIntensity !== undefined) {
      o.material.emissiveIntensity = base;
    } else if (o.userData.dgHoloGlow && o.material) {
      o.material.opacity = 0.75 + Math.sin(t * 1.6) * 0.2;
    }
  });
}

function dgActivate3D(type) {
  dgInit3DEngine();
  if (!dg3D.renderer) return; // Three.js failed to load (offline, blocked CDN, etc.) — caller falls back to 2D
  const canvas2d = document.getElementById('dgCanvas');
  const canvas3d = document.getElementById('dgCanvas3D');
  const overlay = document.getElementById('dgTextOverlay');
  const hint = document.getElementById('dg3DHint');
  if (canvas2d) canvas2d.style.display = 'none';
  if (canvas3d) canvas3d.style.display = 'block';
  if (overlay) overlay.style.display = 'none';
  if (hint) hint.style.display = 'flex';
  dg3DBuild(type);
  if (!dg3D.active) {
    dg3D.active = true;
    dg3DAnimate();
  } else if (dg3D.renderer) {
    dg3D.renderer.render(dg3D.scene, dg3D.camera);
  }
}

function dgDeactivate3D() {
  dg3D.active = false;
  if (dg3D.raf) cancelAnimationFrame(dg3D.raf);
  const canvas2d = document.getElementById('dgCanvas');
  const canvas3d = document.getElementById('dgCanvas3D');
  const overlay = document.getElementById('dgTextOverlay');
  const hint = document.getElementById('dg3DHint');
  const tooltip = document.getElementById('dg3DTooltip');
  if (canvas2d) canvas2d.style.display = '';
  if (canvas3d) canvas3d.style.display = 'none';
  if (overlay) overlay.style.display = '';
  if (hint) hint.style.display = 'none';
  if (tooltip) tooltip.style.display = 'none';
}

// Grouped/comparison charts (Grouped Bar, Diverging Stacked, Tornado, 3D Grouped) live on
// dgState.groupedCategories/groupedSeries, a completely separate data model from the
// single-series dgState.rows that every other chart type (Bar, Pie, Line, Funnel, World
// Map, ...) reads from. Building a grouped chart never touches dgState.rows, so without
// this sync, switching FROM a grouped chart TO a single-series type would silently fall
// back to whatever old/stale dgState.rows happened to be sitting there before the grouped
// chart was built — looking exactly like the current data "disappeared". Rebuilding rows
// from the grouped data's first ticked metric keeps the switch showing the real, current
// dataset instead of orphaned leftovers.
function dgSyncRowsFromGroupedData() {
  const gcats = dgState.groupedCategories || [];
  const gseries = dgState.groupedSeries || [];
  if (!gcats.length || !gseries.length) return;
  const s0 = gseries[0];
  const scheme = dgCurrentScheme();
  dgState.rows = gcats.map((label, i) => ({
    label,
    value: s0.values[i] || 0,
    color: scheme[i % scheme.length]
  }));
  if (gseries.length > 1 && typeof toast === 'function') {
    toast(`Showing "${s0.name}" — this chart type only supports one value per item`, 'info');
  }
}

function dgSetType(type) {
  const wasGrouped = ['grouped', 'hstacked', 'tornado', '3d-grouped-bar'].includes(dgState.type);
  const willBeGrouped = ['grouped', 'hstacked', 'tornado', '3d-grouped-bar'].includes(type);
  if (wasGrouped && !willBeGrouped) dgSyncRowsFromGroupedData();
  dgState.type = type;
  document.querySelectorAll('#dgTypeGrid .dg-type-tile').forEach(t => {
    const active = t.dataset.type === type;
    t.classList.toggle('active', active);
    if (active) {
      const icon = document.getElementById('dgTypeIcon');
      const label = document.getElementById('dgTypeLabel');
      const svg = t.querySelector('svg');
      if (icon && svg) icon.innerHTML = svg.outerHTML;
      if (label) label.textContent = t.dataset.label || t.textContent.trim();
    }
  });
  const dd = document.getElementById('dgTypeDropdown');
  if (dd) dd.classList.remove('open');
  dgSyncRibbonForType();
  dgRender();
}

// ── Ribbon dropdowns: Chart Type / Templates / Colour / Data (fixed-position popovers, same pattern as the PDF editor ribbon) ──
// All four dropdown panels share one registry so opening any one of them
// always closes the others, and a single outside-click listener closes
// whichever panel is open. This keeps them mutually exclusive instead of
// each panel managing its own (previously inconsistent) close logic.
const DG_DROPDOWNS = [
  { groupId: 'dgTypeGroup',      ddId: 'dgTypeDropdown' },
  { groupId: 'dgTitleGroup',     ddId: 'dgTitleDropdown' },
  { groupId: 'dgAxesGroup',      ddId: 'dgAxesDropdown' },
  { groupId: 'dgFormatGroup',    ddId: 'dgFormatDropdown' },
  { groupId: 'dgRadiusGroup',    ddId: 'dgRadiusDropdown' },
  { groupId: 'dgTemplatesGroup', ddId: 'dgTemplatesDropdown' },
  { groupId: 'dgColourGroup',    ddId: 'dgColoursBody' },
  { groupId: 'dgUploadGroup',    ddId: 'dgUploadDropdown' },
  { groupId: 'dgDataGroup',      ddId: 'dgDataDropdown' },
  { groupId: 'dgHistoryGroup',   ddId: 'dgHistoryDropdown' },
  { groupId: 'dgExportGroup',    ddId: 'dgExportDropdown' }
];

function dgCloseAllDropdowns(exceptDdId) {
  DG_DROPDOWNS.forEach(({ ddId }) => {
    if (ddId === exceptDdId) return;
    const dd = document.getElementById(ddId);
    if (dd) dd.classList.remove('open');
  });
}

