  const slider = document.getElementById('dgBarRadiusSlider');
  const label = document.getElementById('dgBarRadiusVal');
  const mainLabel = document.getElementById('dgRadiusMainLabel');
  if (slider) slider.value = dgState.barRadius;
  if (label) label.textContent = dgState.barRadius + 'px';
  if (mainLabel) mainLabel.textContent = dgState.barRadius + 'px';
