// ── Clear All: wipes the current chart to a completely empty canvas —
// all data rows, manual text labels, title and axis titles, colour/radius
// customisations — without touching saved History or upload cache of other
// charts. Confirms first since it can't be undone. ──
function dgClearAll() {
  if (!confirm("Clear everything on this chart — all data, text labels, and titles? This can't be undone.")) return;

  dgState.rows = [];
  // Also clear the grouped/comparison data model — otherwise switching chart type right
  // after a Clear All would resurrect the old grouped data via dgSyncRowsFromGroupedData().
  dgState.groupedCategories = [];
  dgState.groupedSeries = [];
  dgState.texts = [];
  dgSelected.clear();
  dgHidePtxtToolbar();
  dgState.sameColorMode = false;
  dgState.sameColor = '#00C2FF';
  dgState.barRadius = 8;
  dgState.currencySymbol = '$';
  dgState.formatUserSet = false;
  dgUploadParsed = null;
  dgMultiCharts = [];
  dgRenderMultiChartGallery();

  // The "Upload Data" flow keeps its own file-name label, column selectors,
  // and sample-rows preview outside of dgState — clear those out too, or
  // the old uploaded file's data stays visible even after everything else resets.
  const uploadName = document.getElementById('dgUploadFileName');
  if (uploadName) uploadName.textContent = '';
  const labelSel = document.getElementById('dgLabelColSelect');
  if (labelSel) labelSel.innerHTML = '';
  const valueChecks = document.getElementById('dgValueColChecks');
  if (valueChecks) valueChecks.innerHTML = '';
  const uploadHint = document.getElementById('dgUploadHint');
  if (uploadHint) uploadHint.textContent = '';
  const uploadPreview = document.getElementById('dgUploadPreview');
  if (uploadPreview) uploadPreview.innerHTML = '';
  const fileInput = document.getElementById('dgFileInput');
  if (fileInput) fileInput.value = '';

  const titleInput = document.getElementById('dgTitleInput');
  if (titleInput) titleInput.value = 'Chart Title';
  const xAxis = document.getElementById('dgXAxisTitleInput');
  if (xAxis) xAxis.value = '';
  const yAxis = document.getElementById('dgYAxisTitleInput');
  if (yAxis) yAxis.value = '';

  dgSetPaletteScheme('professional'); // recolours + refreshes the palette dropdown UI
  dgSyncBarRadiusUI();
  dgRenderRows(); // rows list is now empty — clears the Data panel's row editor
  dgRenderTextOverlay();
  dgSetType('bar'); // resets chart-type UI, and triggers the final render (empty canvas) + persist

  toast('Chart cleared', 'success');
}

function dgAddRow() {
  const i = dgState.rows.length;
  const color = dgState.sameColorMode ? dgState.sameColor : dgCurrentScheme()[i % dgCurrentScheme().length];
  dgState.rows.push({ label: 'Item ' + (i + 1), value: 25, color });
  dgRenderRows();
  dgRefreshChart();
}

// ── Upload Data (Tabular): hand the tool a CSV/TSV/TXT/XLSX/JSON file, it reads
// and understands the columns (which one is the category, which one is numeric),
// then builds the selected chart straight from that data. Reuses the same
// battle-tested parsing helpers (daSniffDelimiter / daSmartTextToAOA / daNormalize /
// daJsonToAOA) that the Data Analysis tool uses, so both tools understand files
// the same way, but keeps its own state so the two tools never collide. ──
let dgUploadParsed = null; // { headers, rows, fileName } once a file's been read

// ── Chart History: lightweight in-memory snapshots so pushing new table
// data into an existing chart (e.g. from Data Arrangement's "Push to
// Diagrams" button) doesn't silently throw away whatever was already built.
// Each entry captures enough of dgState to fully restore the chart later —
// type, data points, and manual text overlays — plus a label and timestamp
// for the History panel.
let dgChartHistory = [];
const DG_HISTORY_MAX = 15;

// ─── Persistence: keeps the current chart + saved-chart history intact across
// refresh/reopen. Browser-only (localStorage) — nothing is uploaded anywhere,
// it's just written back out on every change instead of living only in memory. ───
const DG_STORAGE_KEY = 'sarvarcDgState_v1';
const DG_HISTORY_STORAGE_KEY = 'sarvarcDgHistory_v1';
let dgPersistTimer = null;
function dgPersist() {
  // try/catch, not just a typeof check: typeof does NOT protect against a
  // `const` still stuck in its temporal dead zone (e.g. if an unrelated
  // script earlier on the page threw before dgHistory could be assigned) —
  // it would still throw here and, since this runs first inside dgRender(),
  // silently prevent the chart from ever redrawing.
  try { dgHistory.checkpoint(); } catch (e) { /* history unavailable this pass — chart still renders */ }
  clearTimeout(dgPersistTimer);
  dgPersistTimer = setTimeout(() => {
    try {
      localStorage.setItem(DG_STORAGE_KEY, JSON.stringify(dgState));
    } catch (e) { console.warn('[Diagrams] could not persist chart state', e); }
    try {
      localStorage.setItem(DG_HISTORY_STORAGE_KEY, JSON.stringify(dgChartHistory));
    } catch (e) { console.warn('[Diagrams] could not persist chart history', e); }
    dgCollabPushChart();
  }, 300);
}
function dgRestore() {
  try {
    const raw = localStorage.getItem(DG_STORAGE_KEY);
    if (raw) {
      const saved = JSON.parse(raw);
      if (saved && typeof saved === 'object') Object.assign(dgState, saved);
    }
  } catch (e) { console.warn('[Diagrams] could not restore chart state', e); }
  try {
    const rawH = localStorage.getItem(DG_HISTORY_STORAGE_KEY);
    if (rawH) {
      const savedH = JSON.parse(rawH);
      if (Array.isArray(savedH)) dgChartHistory = savedH;
    }
  } catch (e) { console.warn('[Diagrams] could not restore chart history', e); }
}
dgRestore();

// ─── LIVE CO-EDITING (see sarvarcCollabRegisterModule / core engine) ───
// Diagrams & Graphs isn't a list of named items like Make Forms/Data
// Arrangement — it's one chart being worked on at a time — so instead of a
// Y.Map keyed by item id, dgState's own top-level properties (type, rows,
// paletteScheme, texts, ...) each become one key in a shared Y.Map. Two
// people editing DIFFERENT properties at once (one picking a palette while
// the other edits data rows) merge cleanly; two people touching the exact
// SAME property at the same instant still resolves last-write-wins for
// that property, same tradeoff Make Forms/Data Arrangement made.
let dgCollabMap = null;
let dgCollabApplyingRemote = false;

function dgCollabPushChart() {
  if (!dgCollabMap || dgCollabApplyingRemote) return;
  const doc = dgCollabMap.doc;
  doc.transact(() => {
    Object.keys(dgState).forEach(k => dgCollabMap.set(k, dgState[k]));
  });
}

function dgCollabReconcileChartFromY() {
  dgCollabApplyingRemote = true;
  try {
    dgCollabMap.forEach((v, k) => { dgState[k] = v; });
    try { localStorage.setItem(DG_STORAGE_KEY, JSON.stringify(dgState)); } catch (e) {}
    // Don't yank a chart mid-drag/mid-edit out from under an active
    // control — text overlay dragging and a couple of ribbon inputs track
    // their own live element refs, so a full dgRender() while the user has
    // one of those focused would fight their input. Skip while any dg*
    // control has focus; the next local change (or remote update) re-syncs.
    const active = document.activeElement;
    const typingInDg = active && active.closest && active.closest('#dgRibbonBar, #dgMainRow, .dg-text-overlay');
    if (!typingInDg && typeof dgRender === 'function') dgRender();
  } finally {
    dgCollabApplyingRemote = false;
  }
}

let dgFlowCollabMap = null;
let dgFlowCollabApplyingRemote = false;

function dgFlowCollabPush() {
  if (!dgFlowCollabMap || dgFlowCollabApplyingRemote) return;
  const ta = document.getElementById('dgFlowInput');
  const ti = document.getElementById('dgFlowTitleInput');
  const doc = dgFlowCollabMap.doc;
  doc.transact(() => {
    dgFlowCollabMap.set('code', ta ? ta.value : '');
    dgFlowCollabMap.set('title', ti ? ti.value : '');
  });
}

function dgFlowCollabReconcileFromY() {
  dgFlowCollabApplyingRemote = true;
  try {
    const ta = document.getElementById('dgFlowInput');
    const ti = document.getElementById('dgFlowTitleInput');
    const code = dgFlowCollabMap.get('code');
    const title = dgFlowCollabMap.get('title');
    try { localStorage.setItem(DG_FLOW_STORAGE_KEY, JSON.stringify({ code: code || '', title: title || '' })); } catch (e) {}
    // Never stomp the box someone's actively typing a diagram/title into.
    if (ta && document.activeElement !== ta && typeof code === 'string' && ta.value !== code) {
      ta.value = code;
      if (typeof dgFlowRender === 'function') dgFlowRender();
    }
    if (ti && document.activeElement !== ti && typeof title === 'string') ti.value = title;
  } finally {
    dgFlowCollabApplyingRemote = false;
  }
}

sarvarcCollabRegisterModule('diagrams', {
  attach(doc, awareness) {
    dgCollabMap = doc.getMap('dgChart');
    if (dgCollabMap.size === 0) {
      doc.transact(() => { Object.keys(dgState).forEach(k => dgCollabMap.set(k, dgState[k])); });
    } else {
      dgCollabReconcileChartFromY();
    }
    dgCollabMap.observe((event, tx) => {
      if (tx.origin !== 'remote') return;
      dgCollabReconcileChartFromY();
    });

    dgFlowCollabMap = doc.getMap('dgFlow');
    const localCode = (document.getElementById('dgFlowInput') || {}).value || '';
    if (dgFlowCollabMap.size === 0 && localCode) {
      const localTitle = (document.getElementById('dgFlowTitleInput') || {}).value || '';
      doc.transact(() => { dgFlowCollabMap.set('code', localCode); dgFlowCollabMap.set('title', localTitle); });
    } else if (dgFlowCollabMap.size > 0) {
      dgFlowCollabReconcileFromY();
    }
    dgFlowCollabMap.observe((event, tx) => {
      if (tx.origin !== 'remote') return;
      dgFlowCollabReconcileFromY();
    });
  },
  detach() { dgCollabMap = null; dgFlowCollabMap = null; }
});

// Used by callers outside this module (Data Arrangement's push button) to
// decide whether to ask before overwriting. The blank canvas someone starts
// on (or gets back to after clearing everything) doesn't count as "existing
// work", so this only goes true once a real file or table has actually been
// loaded in.
function dgHasExistingChart() {
  return !!dgUploadParsed;
}

function dgHistoryTimeLabel(ts) {
  const diffMin = Math.round((Date.now() - ts) / 60000);
  if (diffMin < 1) return 'just now';
  if (diffMin < 60) return diffMin + 'm ago';
  const diffHr = Math.round(diffMin / 60);
  if (diffHr < 24) return diffHr + 'h ago';
  return new Date(ts).toLocaleDateString();
}

function dgSaveCurrentToHistory(label) {
  const titleInput = document.getElementById('dgTitleInput');
  const title = label
    || (titleInput && titleInput.value.trim())
    || (dgUploadParsed && dgUploadParsed.fileName)
    || 'Untitled chart';
  const isGrouped = dgState.type === 'grouped' || dgState.type === 'hstacked' || dgState.type === 'tornado';
  dgChartHistory.unshift({
    id: 'dgh_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7),
    title,
    type: dgState.type,
    rows: JSON.parse(JSON.stringify(dgState.rows)),
    groupedCategories: isGrouped ? JSON.parse(JSON.stringify(dgState.groupedCategories || [])) : [],
    groupedSeries: isGrouped ? JSON.parse(JSON.stringify(dgState.groupedSeries || [])) : [],
    texts: JSON.parse(JSON.stringify(dgState.texts || [])),
    savedAt: Date.now()
  });
  if (dgChartHistory.length > DG_HISTORY_MAX) dgChartHistory.length = DG_HISTORY_MAX;
  dgRenderHistoryList();
}

function dgHistoryPointCount(h) {
  const isGrouped = h.type === 'grouped' || h.type === 'hstacked' || h.type === 'tornado';
  return isGrouped ? (h.groupedCategories || []).length : (h.rows || []).length;
}

function dgRenderHistoryList() {
  dgPersist();
  const wrap = document.getElementById('dgHistoryList');
  const badge = document.getElementById('dgHistoryBadge');
  if (badge) {
    badge.textContent = dgChartHistory.length ? String(dgChartHistory.length) : '';
    badge.style.display = dgChartHistory.length ? '' : 'none';
  }
  if (!wrap) return;
  if (!dgChartHistory.length) {
    wrap.innerHTML = '<div class="dg-history-empty">Saved charts show up here when you choose to keep a previous one before loading new data.</div>';
    return;
  }
  wrap.innerHTML = dgChartHistory.map(h => `
    <div class="dg-history-item" data-id="${h.id}">
      <div class="dg-history-item-main" onclick="dgLoadHistoryItem('${h.id}')">
        <div class="dg-history-item-title">${dgEsc(h.title)}</div>
        <div class="dg-history-item-meta">${dgEsc(h.type)} \u00b7 ${dgHistoryPointCount(h)} point${dgHistoryPointCount(h) !== 1 ? 's' : ''} \u00b7 ${dgHistoryTimeLabel(h.savedAt)}</div>
      </div>
      <button type="button" class="dg-history-item-del" onclick="dgDeleteHistoryItem('${h.id}')" title="Remove from history">
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/></svg>
      </button>
    </div>
  `).join('');
}

function dgLoadHistoryItem(id) {
  const h = dgChartHistory.find(x => x.id === id);
  if (!h) return;
  // Restoring a History item swaps the editor to a chart that has nothing to
  // do with whichever gallery card it last synced to — deselect that card so
  // the next dgRender() doesn't overwrite the wrong gallery slot with this
  // unrelated chart's data.
  dgActiveMultiChartIdx = null;
  document.querySelectorAll('.dg-multi-gallery-card').forEach(el => el.classList.remove('active'));
  dgResetFormatForNewChart(); // restoring a saved chart is loading "a different chart" too — don't let a % (or currency) choice made on the chart you were just looking at leak into this one
  dgState.type = h.type;
  dgState.rows = JSON.parse(JSON.stringify(h.rows));
  dgState.groupedCategories = JSON.parse(JSON.stringify(h.groupedCategories || []));
  dgState.groupedSeries = JSON.parse(JSON.stringify(h.groupedSeries || []));
  dgState.texts = JSON.parse(JSON.stringify(h.texts || []));
  // The title box is what smart format-detection reads its hint from (see dgGetOpts) — if
  // it's left holding whatever title the previous chart had, restoring this chart would
  // silently borrow that leftover title's currency/percent hint instead of its own.
  const titleInput = document.getElementById('dgTitleInput');
  if (titleInput) titleInput.value = h.title || '';
  dgRenderRows();
  dgRender();
  if (typeof dgFitZoomToHolder === 'function') setTimeout(dgFitZoomToHolder, 0);
  dgCloseAllDropdowns();
  toast(`Restored "${h.title}" from history`, 'success');
}


function dgDeleteHistoryItem(id) {
  dgChartHistory = dgChartHistory.filter(x => x.id !== id);
  dgRenderHistoryList();
}

function dgHandleFileSelect(e) {
  const file = e.target.files && e.target.files[0];
  if (file) dgProcessUploadedFile(file);
  e.target.value = '';
}

function dgHandleDrop(e) {
  e.preventDefault();
  e.currentTarget.classList.remove('dragover');
  const file = e.dataTransfer.files && e.dataTransfer.files[0];
  if (file) dgProcessUploadedFile(file);
}

function dgProcessUploadedFile(file) {
  const ext = (file.name.split('.').pop() || '').toLowerCase();
  const zone = document.getElementById('dgUploadZone');
  if (zone) zone.classList.add('scanning');
  const reader = new FileReader();
  const stopScanning = () => { if (zone) zone.classList.remove('scanning'); };
  reader.onerror = () => { toast('Could not read that file', 'error'); stopScanning(); };

  if (ext === 'xlsx' || ext === 'xls') {
    reader.onload = () => {
      try {
        const wb = XLSX.read(new Uint8Array(reader.result), { type: 'array' });
        const ws = wb.Sheets[wb.SheetNames[0]];
        const aoa = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '', blankrows: false, raw: false });
        dgOnUploadParsed(aoa, file.name);
      } catch (err) { toast('Could not parse that spreadsheet', 'error'); }
      stopScanning();
    };
    reader.readAsArrayBuffer(file);
  } else if (ext === 'json') {
    reader.onload = () => {
      try {
        const parsed = JSON.parse(reader.result);
        const aoa = daJsonToAOA(parsed);
        dgOnUploadParsed(aoa, file.name);
      } catch (err) { toast('Invalid JSON file', 'error'); }
      stopScanning();
    };
    reader.readAsText(file);
  } else if (ext === 'docx' || ext === 'pdf' || ext === 'doc' || ext === 'rtf') {
    toast('For diagrams, upload a tabular file: CSV, TSV, TXT, Excel, or JSON', 'info');
    stopScanning();
  } else {
    // csv / tsv / txt / anything else plain-text
    reader.onload = () => {
      try {
        const forcedDelim = ext === 'tsv' ? '\t' : null;
        const aoa = daSmartTextToAOA(reader.result, forcedDelim);
        dgOnUploadParsed(aoa, file.name);
      } catch (err) { toast('Could not read that file as a table', 'error'); }
      stopScanning();
    };
    reader.readAsText(file);
  }
}

// Scans a freshly-parsed table for a birth-date-looking column (by header text) and, if every
// sampled cell in it actually parses as a date, appends a derived "Age (years)" column computed
// against today's date — so a roster/HR/student list with a DOB column gets an age chart
// available to plot immediately, with no manual date-subtraction step. Non-destructive: the
// original DOB column stays exactly as uploaded, this only adds a new column alongside it, and
// it's skipped entirely if an "age" column already exists in the sheet.
function dgInjectDerivedAgeColumn(headers, rows) {
  const hasAgeAlready = headers.some(h => /\bage\b/i.test(String(h || '')));
  if (hasAgeAlready) return;
  const dobIdx = headers.findIndex(h => dgIsBirthDateHeader(h));
  if (dobIdx === -1) return;
  const today = new Date();
  let parsedCount = 0;
  const ages = rows.map(r => {
    const d = dgParseDateCell(r[dobIdx]);
    if (!d) return '';
    parsedCount++;
    return dgComputeAge(d, today);
  });
  // Require most rows to actually parse as dates before committing to the derived column —
  // a header that merely contains "birthday" but holds free-text notes shouldn't get a bogus
  // Age column bolted on.
  if (rows.length && parsedCount / rows.length < 0.6) return;
  headers.push('Age (years)');
  rows.forEach((r, i) => r.push(ages[i]));
  if (typeof toast === 'function') {
    toast(`Detected a birth-date column ("${headers[dobIdx]}") — added an "Age (years)" column you can plot directly`, 'info');
  }
}

function dgOnUploadParsed(aoa, fileName) {
  const { headers, rows, titleRow } = daNormalize(aoa);
  if (!rows.length || headers.length < 1) { toast('No tabular data found in that file', 'info'); return; }
  dgInjectDerivedAgeColumn(headers, rows);
  dgUploadParsed = { headers, rows, fileName };
  if (typeof dgState !== 'undefined') dgState.formatUserSet = false; // fresh dataset — let sign auto-detection have a say again
  const nameEl = document.getElementById('dgUploadFileName');
  if (nameEl) nameEl.textContent = fileName;
  dgPopulateUploadSelectors();
  const ribbonHint = document.getElementById('dgUploadRibbonHint');
  if (ribbonHint) ribbonHint.style.display = 'block';
  const columnsChip = document.getElementById('dgColumnsChip');
  if (columnsChip) columnsChip.classList.add('active');
  const titleInput = document.getElementById('dgTitleInput');
  if (titleInput && (!titleInput.value.trim() || titleInput.value.trim() === 'Chart Title')) {
    // Prefer a title actually detected inside the sheet (e.g. a spanning
    // report title sitting above the real header row) over the filename —
    // it's a far more accurate label than "Sheet1" or "export_final_v2".
    titleInput.value = titleRow || daBaseName(fileName);
  }
  dgGenerateChartFromUpload();
  // The grouped/comparison/per-column suggestion popup is about clustering numeric
  // columns for ordinary charts — it doesn't know about world maps and would only
  // confuse or overwrite the per-country gallery dgGenerateChartFromUpload just built.
  if (dgActiveMode !== 'map') dgMaybeSuggestMultiChart();
}

// ── Big-data intelligence: census tables, revenue reports, and similar files often carry several
// numeric measures (e.g. Population / Median Income / Growth %) or far more rows than one chart can
// show cleanly. Rather than silently picking one column and quietly truncating the rest, we look at
// what was actually uploaded and, when it looks richer than a single chart can represent, ask the
// person how they'd like it handled instead of guessing on their behalf. ──
let dgMultiCharts = [];
// Which dgMultiCharts[] slot (if any) the main live-preview editor is currently
// standing in for. Set when a gallery card is opened for editing; cleared when
// the gallery is rebuilt from scratch or the editor switches to something that
// ISN'T that gallery chart (a restored History item, a brand-new upload). Lets
// dgRender() write every edit straight back into that slot — see
// dgSyncActiveMultiChartFromState below — instead of the edit only living in
// dgState and vanishing the moment the person clicks another card or Push.
let dgActiveMultiChartIdx = null;
let dgMultiSuggestChoice = null;

function dgAnalyzeUpload() {
  if (!dgUploadParsed) return null;
  const { headers, rows } = dgUploadParsed;
  const labelSel = document.getElementById('dgLabelColSelect');
  const labelIdx = labelSel && labelSel.value !== '' ? parseInt(labelSel.value, 10) : 0;
  const numericIdxs = headers.map((_, i) => i).filter(i => i !== labelIdx && dgColumnIsNumeric(i));
  return { headers, rows, labelIdx, numericIdxs, rowCount: rows.length };
}

// A table shaped like "a handful of metrics (rows) tracked across a handful of named
// options/entities (numeric columns)" — a competitor comparison, a before/after benchmark, a
// scenario matrix — is a different animal from a long single-measure list. For that shape, the
// most useful charts aren't "one per column" (that would plot every metric for one competitor on
// one axis, mixing seconds with percentages with raw counts) — it's one clean comparison per
// metric, plus a normalized overview. Kept deliberately conservative (small-ish row/column counts)
// so it only fires for genuine side-by-side comparison tables, not generic long-format data.
function dgDetectComparisonShape(info) {
  if (!info) return false;
  const { numericIdxs, rowCount } = info;
  return numericIdxs.length >= 2 && numericIdxs.length <= 8 && rowCount >= 2 && rowCount <= 20;
}

// ── Smart grouped-bar clustering ──────────────────────────────────────────────────────────
// Most uploaded tables are the OPPOSITE shape from the "metrics as rows" comparison matrix
// above: one row per real-world category (a department, a month, a product) and several
// numeric columns that are measures of it (Profit 2025, Profit 2026, Growth %, Employees).
// The right chart for that shape is a single clustered/grouped bar chart — one bar per
// comparable column, side by side, per category — but only for columns that are actually
// comparable. Blindly grouping every numeric column together would put a $495,000 profit bar
// next to an 18% growth bar on the same axis, which is meaningless. So columns are clustered
// first, using two independent signals, and only clusters of 2+ columns become a grouped chart;
// anything left on its own falls back to being its own single-series chart.
//
//   1. A shared unit/label stem — "Profit 2025 ($)" and "Profit 2026 ($)" share the "($)" unit
//      AND the "profit" word stem once the year is stripped out. This is the strongest signal
//      (it's literally the same measurement, tracked twice) and is checked first.
//   2. Similar magnitude — lacking a clean text match, columns whose typical values sit within
//      one order of magnitude of each other (e.g. two headcount-like columns) are still grouped,
//      since a shared axis won't visually crush either of them.
function dgColumnUnit(header) {
  const h = String(header || '').trim();
  const paren = h.match(/\(([^)]+)\)\s*$/);
  if (paren) return paren[1].trim().toLowerCase();
  if (/%\s*$/.test(h)) return '%';
  if (/\$/.test(h)) return '$';
  return null;
}

// Strips a trailing year/number and unit parenthetical so "Profit 2025 ($)" and
// "Profit 2026 ($)" reduce to the same stem ("profit"), while leaving genuinely different
// metrics ("Growth %", "Employees") distinct.
function dgColumnStem(header) {
  return String(header || '')
    .toLowerCase()
    .replace(/\([^)]*\)\s*$/, '')
    .replace(/\b(19|20)\d{2}\b/g, '')
    .replace(/[^a-z]+/g, ' ')
    .trim();
}

// ── Total/summary-row & summary-column detection ──────────────────────────────────────────
// Uploaded tables (financial exports, especially) very often bake a trailing "Total" /
// "Grand Total" / "Subtotal" / "Average" row right into the same sheet as the real data, or
// carry a "Total" column alongside the components it adds up. Plotted as just another bar,
// that row/column is many times bigger than every real data point and visually crushes the
// actual comparison the chart exists to show — so it's treated as a summary, not a data
// point, and left out of charts by default (never silently: every place this fires also
// says so in the toast, and it's never removed from the underlying table/data-arrangement
// view — only from what gets auto-plotted).
const DG_AGGREGATE_LABEL_RE = /^(grand\s+)?(sub[\s-]?)?totals?\s*:?$|^(overall|combined|aggregate|net)\s*totals?$|^sum(mary)?\s*:?$|^averages?\s*:?$|^means?\s*:?$|^overall$|^grand\s+sum$/i;

function dgIsAggregateLabel(label) {
  const l = String(label ?? '').trim().toLowerCase().replace(/[:*]+$/, '').trim();
  if (!l) return false;
  return DG_AGGREGATE_LABEL_RE.test(l);
}

// Same idea for a whole COLUMN — a header literally called "Total" (or "Total ($)",
// "Grand Total 2026") sitting next to its own component columns is a computed sum, not an
// independent measure, so it shouldn't be auto-clustered with the columns it adds up or
// picked as the default single value column.
function dgIsAggregateHeader(header) {
  const h = String(header ?? '').trim().toLowerCase()
    .replace(/\([^)]*\)\s*$/, '')      // strip trailing unit, e.g. "Total ($)"
    .replace(/\b(19|20)\d{2}\b/g, '')  // strip trailing year, e.g. "Total 2026"
    .trim();
  return dgIsAggregateLabel(h);
}

// Label-agnostic safety net: even when a summary row isn't spelled with any of the words
// above (a different language, an unusual header like "TOTAL 2026", etc.), a row whose
// value is essentially the SUM of every other row's value in the same column is
// mathematically a total, not its own data point. Only the single strongest match is
// flagged (with a tolerance for rounding) to avoid false positives on small datasets where
// two real values coincidentally add up.
function dgFindMathematicalTotalIdx(values) {
  if (values.length < 3) return -1; // too few rows for "total of the rest" to be meaningful
  const sum = values.reduce((a, b) => a + b, 0);
  for (let i = 0; i < values.length; i++) {
    const rest = sum - values[i];
    if (Math.abs(rest) > 0 && Math.abs(values[i] - rest) <= Math.abs(rest) * 0.02) return i;
  }
  return -1;
}

// Given parallel label/value arrays for one chart's worth of rows, returns the set of row
// indices that look like summary rows (by label text OR, failing that, by being the
// arithmetic sum of the rest) so callers can leave them out of the actual chart.
function dgFindAggregateRowIdxs(labels, values) {
  const idxs = new Set();
  labels.forEach((label, i) => { if (dgIsAggregateLabel(label)) idxs.add(i); });
  if (!idxs.size) {
    const mathIdx = dgFindMathematicalTotalIdx(values);
    if (mathIdx !== -1) idxs.add(mathIdx);
  }
  return idxs;
}

function dgColumnMagnitude(rows, colIdx) {
  const vals = rows.map(r => Math.abs(dgParseNumericCell(r[colIdx]))).filter(v => !isNaN(v) && v > 0);
  if (!vals.length) return null;
  vals.sort((a, b) => a - b);
  const median = vals[Math.floor(vals.length / 2)];
  return Math.log10(median || 1);
}

// Groups numeric column indices into clusters of columns worth showing on one shared axis.
// Returns an array of arrays of column indices, in first-seen order.
function dgGroupNumericColumns(headers, numericIdxs, rows) {
  // A column literally named "Total"/"Grand Total"/etc is a computed sum of its siblings,
  // not another measure of the same thing — clustering it alongside its own components
  // would put a bar 3-4x taller than the rest in the same group. Pull those out first and
  // give each its own standalone group; only genuinely comparable measure columns go
  // through the stem/magnitude clustering below.
  const normalIdxs = numericIdxs.filter(idx => !dgIsAggregateHeader(headers[idx]));
  const aggregateIdxs = numericIdxs.filter(idx => dgIsAggregateHeader(headers[idx]));
  const meta = normalIdxs.map(idx => ({
    idx,
    unit: dgColumnUnit(headers[idx]),
    stem: dgColumnStem(headers[idx]),
    mag: dgColumnMagnitude(rows, idx)
  }));
  const groups = [];
  meta.forEach(col => {
    let target = null;
    for (const g of groups) {
      const head = g[0];
      const unitsCompatible = head.unit === col.unit; // both null counts as "no conflict"
      // Same underlying metric is the strongest signal there is — e.g. "Profit
      // 2025" and "Profit 2026" both reduce to stem "profit" and should group
      // even when NEITHER header carries an explicit unit suffix like "($)".
      // The old check required both headers to already have a unit before it
      // would even look at the stem, so plain unitless same-metric columns
      // only grouped by magnitude coincidence (and failed to group at all if
      // the values happened to differ by more than 10x, e.g. profit growing
      // sharply year over year).
      const sameStem = head.stem && col.stem && head.stem === col.stem && unitsCompatible;
      // Magnitude-only fallback (no shared stem) is the riskier path, so it's
      // tightened: requires an ACTUAL shared unit symbol (not just "both have
      // no unit") and a closer magnitude match, so two unrelated unitless
      // metrics that happen to be similarly sized (e.g. "Age" and "Score")
      // don't get clustered into the same chart just by coincidence.
      const closeMagnitude = !sameStem && head.unit && unitsCompatible &&
        head.mag != null && col.mag != null && Math.abs(head.mag - col.mag) <= 0.5;
      if (sameStem || closeMagnitude) { target = g; break; }
    }
    if (target) target.push(col);
    else groups.push([col]);
  });
  aggregateIdxs.forEach(idx => groups.push([{ idx }])); // each Total-like column stands alone
  return groups.map(g => g.map(c => c.idx));
}

// True when at least one cluster of comparable numeric columns has 2+ members — i.e. there's
// a genuine "one bar per column, grouped by row" chart worth offering.
function dgDetectGroupedShape(info) {
  if (!info) return false;
  const { headers, numericIdxs, rows, rowCount } = info;
  if (numericIdxs.length < 2 || rowCount < 1 || rowCount > 60) return false;
  const groups = dgGroupNumericColumns(headers, numericIdxs, rows);
  return groups.some(g => g.length >= 2);
}

// Builds the grouped-bar chart set: one clustered bar chart per group of 2+ comparable
// numeric columns (categories = the label column's rows, series = the grouped columns), plus
// a plain single-series bar chart for any numeric column that didn't cluster with anything.
function dgBuildSmartGroupedCharts() {
  const info = dgAnalyzeUpload();
  if (!info || info.numericIdxs.length < 2) { toast('Need at least two numeric columns to group', 'info'); return; }
  const scheme = dgCurrentScheme();
  const MAX_CATEGORIES = 30;
  const groups = dgGroupNumericColumns(info.headers, info.numericIdxs, info.rows);

  // Leave summary rows (a trailing "Total"/"Grand Total"/"Average" row baked into the
  // sheet) out of every group's categories — otherwise every clustered chart gets one
  // category whose bars dwarf all the real ones.
  const categories = [];
  const rowsUsed = [];
  let excludedTotalRows = 0;
  for (let i = 0; i < info.rows.length && categories.length < MAX_CATEGORIES; i++) {
    const r = info.rows[i];
    const label = String(r[info.labelIdx] ?? '').trim() || `Item ${categories.length + 1}`;
    if (dgIsAggregateLabel(label)) { excludedTotalRows++; continue; }
    categories.push(label);
    rowsUsed.push(r);
  }
  if (!categories.length) { toast('Could not find any rows to chart', 'error'); return; }

  const specs = [];
  groups.forEach(colIdxs => {
    if (colIdxs.length >= 2) {
      const series = colIdxs.map((colIdx, si) => ({
        name: String(info.headers[colIdx] || ('Column ' + (colIdx + 1))),
        color: scheme[si % scheme.length],
        values: rowsUsed.map(r => { const v = dgParseNumericCell(r[colIdx]); return isNaN(v) ? 0 : v; })
      }));
      // Columns in this group already share a unit (that's why they clustered) — a
      // sign detected off the first one applies to the whole grouped chart's table.
      const groupSign = dgDetectValueSign(rowsUsed.map(r => r[colIdxs[0]]), info.headers[colIdxs[0]]);
      specs.push({
        title: 'Grouped comparison \u2014 ' + series.map(s => s.name).join(' vs '),
        type: 'grouped',
        categories: categories.slice(),
        series,
        format: groupSign ? groupSign.format : null, formatSymbol: groupSign ? groupSign.symbol : null
      });
    } else {
      const colIdx = colIdxs[0];
      const built = rowsUsed.map((r, i) => {
        const v = dgParseNumericCell(r[colIdx]);
        return { label: categories[i], value: isNaN(v) ? 0 : v, color: scheme[i % scheme.length] };
      });
      const sign = dgDetectValueSign(rowsUsed.map(r => r[colIdx]), info.headers[colIdx]);
      specs.push({
        title: String(info.headers[colIdx] || ('Column ' + (colIdx + 1))), type: 'bar', rows: built,
        format: sign ? sign.format : null, formatSymbol: sign ? sign.symbol : null
      });
    }
  });

  if (!specs.length) { toast('Could not build a chart from those columns', 'error'); return; }
  dgMultiCharts = specs;
  dgRenderMultiChartGallery();
  const groupedCount = groups.filter(g => g.length >= 2).length;
  const totalNote = excludedTotalRows ? ` (left out ${excludedTotalRows} summary row${excludedTotalRows === 1 ? '' : 's'} like Total/Average)` : '';
  toast((groupedCount
    ? `Built ${groupedCount} grouped bar chart${groupedCount === 1 ? '' : 's'}\u2014 comparable columns clustered together automatically`
    : `Built ${specs.length} charts`) + totalNote, 'success');
  // Building the gallery alone doesn't populate dgState.groupedCategories/groupedSeries —
  // that only happens when a card is clicked (dgLoadMultiChart). Without this, switching
  // straight to 3D Grouped Bar or Hologram right after building finds empty series data and
  // renders a blank scene with no indication why. Auto-load the first grouped result into the
  // live editor immediately so 3D/Hologram have real data the moment they're switched on.
  const firstGroupedIdx = specs.findIndex(s => s.type === 'grouped');
  if (firstGroupedIdx !== -1) dgLoadMultiChart(firstGroupedIdx);
}

function dgMaybeSuggestMultiChart() {
  const info = dgAnalyzeUpload();
  if (!info) return;
  const manyMetrics = info.numericIdxs.length >= 2;
  const bigRowCount = info.rowCount > 40;
  const isGrouped = dgDetectGroupedShape(info);
  const isComparison = dgDetectComparisonShape(info);
  if (!manyMetrics && !bigRowCount) return; // a plain small table — the single auto-built chart is enough

  const statsEl = document.getElementById('dgMultiSuggestStats');
  const groupedBtn = document.getElementById('dgMultiSuggestGroupedBtn');
  const groupedHead = document.getElementById('dgMultiSuggestGroupedHead');
  const groupedDesc = document.getElementById('dgMultiSuggestGroupedDesc');
  const compareBtn = document.getElementById('dgMultiSuggestCompareBtn');
  const compareHead = document.getElementById('dgMultiSuggestCompareHead');
  const compareDesc = document.getElementById('dgMultiSuggestCompareDesc');
  const perColBtn = document.getElementById('dgMultiSuggestPerColumnBtn');
  const perColHead = document.getElementById('dgMultiSuggestPerColumnHead');
  const perColDesc = document.getElementById('dgMultiSuggestPerColumnDesc');
  const subEl = document.getElementById('dgMultiSuggestSub');
  const titleEl = document.getElementById('dgMultiSuggestTitle');
  if (statsEl) {
    statsEl.innerHTML = `
      <div class="dg-multi-suggest-stat"><b>${info.rowCount}</b><span>Rows detected</span></div>
      <div class="dg-multi-suggest-stat"><b>${info.numericIdxs.length}</b><span>Numeric columns</span></div>
      <div class="dg-multi-suggest-stat"><b>${info.headers.length}</b><span>Total columns</span></div>
    `;
  }
  if (titleEl) {
    titleEl.textContent = isGrouped ? 'This looks like a per-category comparison'
      : isComparison ? 'This looks like a comparison table' : 'This looks like a rich dataset';
  }
  if (subEl) {
    const numHeaders = info.headers.filter((_, i) => info.numericIdxs.includes(i)).join(', ');
    subEl.textContent = isGrouped
      ? `Found ${info.numericIdxs.length} numeric columns (${numHeaders}) tracked per row — comparable ones (e.g. matching units, same measure across periods) can be grouped into one clustered bar chart per row.`
      : isComparison
        ? `Found ${info.numericIdxs.length} columns (${numHeaders}) measured across ${info.rowCount} metrics — that reads like a side-by-side comparison.`
        : manyMetrics && bigRowCount
          ? `Found ${info.numericIdxs.length} numeric columns across ${info.rowCount} rows — that's more than one chart usually shows cleanly.`
          : manyMetrics
            ? `Found ${info.numericIdxs.length} separate numeric columns — each could be its own chart.`
            : `Found ${info.rowCount} rows — one chart may get crowded. Here's how you'd like it handled.`;
  }
  if (groupedBtn) groupedBtn.style.display = isGrouped ? '' : 'none';
  if (groupedHead && groupedDesc) {
    const groups = dgGroupNumericColumns(info.headers, info.numericIdxs, info.rows).filter(g => g.length >= 2);
    const exampleGroup = groups[0];
    groupedHead.textContent = 'Grouped bar chart (recommended)';
    groupedDesc.textContent = exampleGroup
      ? `Builds a clustered chart with ${exampleGroup.map(i => info.headers[i]).join(' and ')} shown as side-by-side coloured bars for every row${groups.length > 1 ? `, plus ${groups.length - 1} more grouped chart${groups.length - 1 === 1 ? '' : 's'} for the other comparable columns` : ''}.`
      : `Puts side-by-side coloured bars per row for every group of comparable columns.`;
  }
  if (compareBtn) compareBtn.style.display = (isComparison && !isGrouped) ? '' : 'none';
  if (compareHead && compareDesc) {
    compareHead.textContent = `Compare side-by-side (recommended)`;
    compareDesc.textContent = `Treats each row as its own metric and each numeric column as an entity being compared — one bar chart per metric, plus a normalized radar overview. Better fit when columns are options (e.g. competitors) rather than repeated measures.`;
  }
  if (perColBtn) perColBtn.style.display = manyMetrics ? '' : 'none';
  if (perColHead && perColDesc) {
    perColHead.textContent = (isGrouped || isComparison)
      ? `One chart per column instead (${info.numericIdxs.length} charts)`
      : `One chart per numeric column (${info.numericIdxs.length} charts)`;
  }
  const overlay = document.getElementById('dgMultiSuggestOverlay');
  if (overlay) overlay.classList.add('open');
}

function dgDismissMultiSuggest() {
  const overlay = document.getElementById('dgMultiSuggestOverlay');
  if (overlay) overlay.classList.remove('open');
}

function dgConfirmMultiSuggest(choice) {
  dgDismissMultiSuggest();
  if (choice === 'grouped') dgBuildSmartGroupedCharts();
  else if (choice === 'compare') dgBuildComparisonCharts();
  else if (choice === 'perColumn') dgBuildMultiChartsPerColumn();
  else if (choice === 'topGrouped') dgGenerateChartFromUpload(true);
  // 'single' needs no further action — the auto-built chart is already showing
}

// Builds one independent chart per numeric column (besides the label column), all sharing the
// same category labels — the natural shape for census tables, financial statements, survey
// results, or any file where several measures were tracked per row.
function dgBuildMultiChartsPerColumn() {
  const info = dgAnalyzeUpload();
  if (!info || info.numericIdxs.length < 2) { toast('Need at least two numeric columns for multiple charts', 'info'); return; }
  const scheme = dgCurrentScheme();
  const MAX_POINTS = 40;
  const type = dgState.type;
  let excludedTotalRows = 0;
  dgMultiCharts = info.numericIdxs.map(valueIdx => {
    const built = [];
    for (let i = 0; i < info.rows.length && built.length < MAX_POINTS; i++) {
      const r = info.rows[i];
      const value = dgParseNumericCell(r[valueIdx]);
      if (isNaN(value)) continue;
      const label = String(r[info.labelIdx] ?? '').trim() || `Item ${built.length + 1}`;
      // Skip summary rows ("Total"/"Grand Total"/"Average"...) — a bar many times the
      // size of the real data points isn't a data point, it's the sum of them.
      if (dgIsAggregateLabel(label)) { excludedTotalRows++; continue; }
      built.push({ label, value, color: scheme[built.length % scheme.length] });
    }
    // Detect a currency/percent sign from this column's own raw cells (before
    // dgParseNumericCell stripped it out) — the paired table pushed with this
    // chart shows its figures with that sign instead of bare numbers, the same
    // way the live editor's own Number Format would once someone opened it.
    const sign = dgDetectValueSign(info.rows.map(r => r[valueIdx]), info.headers[valueIdx]);
    return {
      title: String(info.headers[valueIdx] || ('Column ' + (valueIdx + 1))), type, rows: built,
      format: sign ? sign.format : null, formatSymbol: sign ? sign.symbol : null
    };
  }).filter(c => c.rows.length);
  if (!dgMultiCharts.length) { toast('Could not find usable numeric data in those columns', 'error'); return; }
  dgRenderMultiChartGallery();
  const totalNote = excludedTotalRows ? ` (left out summary rows like Total/Average)` : '';
  toast(`Built ${dgMultiCharts.length} charts \u2014 one per numeric column${totalNote}`, 'success');
}

// Metric labels like "Processing Time" or "Support Response" are lower-is-better — a smaller
// number is the win. Min-max normalizing those the same direction as "Monthly Active Users"
// would make the radar chart lie (small value = closer to center = looks worse, even when it's
// actually the best result). This flags that class of metric from its label text so the radar
// axis can be inverted for it — keeping a single, honest rule across the whole chart: further
// out always means better, on every axis.
const DG_LOWER_IS_BETTER_HINTS = [
  'time', 'latency', 'response', 'wait', 'delay', 'downtime', 'duration',
  'cost', 'price', 'expense', 'spend',
  'error', 'bug', 'defect', 'complaint', 'churn', 'bounce', 'failure', 'outage',
  'load time', 'turnaround'
];
function dgIsLowerBetterMetric(label) {
  const l = String(label || '').toLowerCase();
  return DG_LOWER_IS_BETTER_HINTS.some(hint => l.includes(hint));
}

// Builds the "smart comparison" set for a table shaped like metrics-as-rows /
// entities-as-columns (a competitor matrix, a before/after benchmark, a scenario comparison):
//   1. One bar chart PER METRIC, bars for every entity colour-matched consistently across every
//      card — each metric keeps its own natural scale, so "2.4 sec" never gets crushed to
//      invisible next to "12,500 users" on a shared axis.
//   2. One radar chart giving the big-picture shape: every metric (axis) is independently
//      min-max normalized to 0–100 across entities, so mixed units can share one chart without
//      one metric's scale swamping the rest. Axes detected as lower-is-better (processing time,
//      support response, cost, error rate, etc.) are inverted during normalization, so the rule
//      stays constant across the whole chart: further from the center always means better,
//      never "further means bigger." Raw values are kept alongside for reference/tooltips.
// Rows where none of the entity columns parse as numbers (e.g. a qualitative row like
// "Privacy Model: Browser-first / Cloud / Cloud") are left out of both — they're categorical,
// not chartable, and forcing them into a bar would misrepresent them as quantities.
function dgBuildComparisonCharts() {
  const info = dgAnalyzeUpload();
  if (!info || info.numericIdxs.length < 2) { toast('Need at least two numeric columns to compare', 'info'); return; }
  const scheme = dgCurrentScheme();
  const MAX_METRICS = 14;

  const entityNames = info.numericIdxs.map((idx, si) => String(info.headers[idx] || ('Column ' + (idx + 1))));
  const entityColors = entityNames.map((_, si) => scheme[si % scheme.length]);

  const metrics = [];
  let excludedTotalRows = 0;
  for (let i = 0; i < info.rows.length && metrics.length < MAX_METRICS; i++) {
    const r = info.rows[i];
    const parsed = info.numericIdxs.map(idx => dgParseNumericCell(r[idx]));
    if (parsed.every(v => isNaN(v))) continue;
    const label = String(r[info.labelIdx] ?? '').trim() || `Metric ${metrics.length + 1}`;
    // A "Total"/"Grand Total" row here is a summary metric, not a real point of
    // comparison between entities — skip it the same way as any other chart shape.
    if (dgIsAggregateLabel(label)) { excludedTotalRows++; continue; }
    metrics.push({ label, values: parsed.map(v => isNaN(v) ? 0 : v), lowerBetter: dgIsLowerBetterMetric(label) });
  }
  if (!metrics.length) { toast('Could not find rows with comparable numeric values across those columns', 'error'); return; }

  const perMetricSpecs = metrics.map(m => ({
    title: m.label + (m.lowerBetter ? ' (lower is better)' : ''),
    type: 'bar',
    rows: entityNames.map((name, si) => ({ label: name, value: m.values[si], color: entityColors[si] }))
  }));

  const radarSeries = entityNames.map((name, si) => ({ name, color: entityColors[si], values: [], rawValues: [] }));
  let anyInverted = false;
  metrics.forEach(m => {
    const vals = m.values;
    const min = Math.min(...vals), max = Math.max(...vals);
    const span = max - min;
    if (m.lowerBetter) anyInverted = true;
    vals.forEach((v, si) => {
      let pct = span > 0 ? ((v - min) / span) * 100 : 50;
      if (m.lowerBetter) pct = 100 - pct; // flip so "further out" still reads as "better" on this axis
      radarSeries[si].values.push(Math.round(pct));
      radarSeries[si].rawValues.push(v);
    });
  });
  const radarSpec = {
    title: 'Overview — Normalized Comparison (further out = better on every axis)',
    type: 'radar',
    categories: metrics.map(m => m.label + (m.lowerBetter ? ' ↓' : '')),
    series: radarSeries
  };

  dgMultiCharts = [radarSpec, ...perMetricSpecs];
  dgRenderMultiChartGallery();
  const totalNote = excludedTotalRows ? ` (left out ${excludedTotalRows} summary row${excludedTotalRows === 1 ? '' : 's'} like Total/Average)` : '';
  toast((anyInverted
    ? `Built a normalized radar overview (lower-is-better axes inverted) + ${perMetricSpecs.length} per-metric comparison charts`
    : `Built a normalized radar overview + ${perMetricSpecs.length} per-metric comparison charts`) + totalNote, 'success');
}

function dgCloseMultiGallery() {
  dgMultiCharts = [];
  dgActiveMultiChartIdx = null;
  const gallery = document.getElementById('dgMultiGallery');
  if (gallery) gallery.classList.remove('open');
}

function dgRenderMultiChartGallery() {
  const gallery = document.getElementById('dgMultiGallery');
  const strip = document.getElementById('dgMultiGalleryStrip');
  const countEl = document.getElementById('dgMultiGalleryCount');
  if (!gallery || !strip) return;
  // Every caller reassigns dgMultiCharts right before calling this, i.e. this
  // is always a fresh batch — whatever slot the editor was previously synced
  // to no longer means anything against the new array.
  dgActiveMultiChartIdx = null;
  if (!dgMultiCharts.length) { gallery.classList.remove('open'); return; }
  gallery.classList.add('open');
  if (countEl) countEl.textContent = ` \u00b7 ${dgMultiCharts.length} chart${dgMultiCharts.length === 1 ? '' : 's'} \u00b7 click one to edit it, or push them all at once`;
  strip.innerHTML = dgMultiCharts.map((c, i) => `
    <div class="dg-multi-gallery-card" data-idx="${i}" onclick="dgLoadMultiChart(${i})">
      <canvas width="320" height="200" data-thumb="${i}"></canvas>
      <div class="dg-multi-gallery-card-label" title="${dgEsc(c.title)}">${dgEsc(c.title)}</div>
    </div>
  `).join('');
  dgMultiCharts.forEach((c, i) => {
    const canvas = strip.querySelector(`canvas[data-thumb="${i}"]`);
    if (canvas) dgDrawChartSpec(canvas, c);
  });
}

// Loads one gallery chart into the main live-preview editor so it can be tweaked, recoloured,
// or exported like any other chart, without disturbing the other charts still sitting in the gallery.
// A manual Number Format pick (the person clicking "%" or "Currency" in the dropdown)
// is a decision about THAT chart, not a standing preference — so every place that swaps
// in a different chart's data (gallery cards, History) must call this first. Without it,
// dgState.formatUserSet stays stuck true from whichever chart was open when the person
// last touched the dropdown, which blocks auto-detection from ever running again — so
// picking "%" on chart A silently forces every chart loaded afterwards onto "%" too, even
// ones with plain numbers or a totally different currency. Resetting both the flag and the
// dropdown itself (back to 'plain') before the new chart's title/data get applied lets
// dgGetOpts's per-render detection read that chart's OWN hint fresh, the same way it does
// right after a brand-new upload.
function dgResetFormatForNewChart() {
  if (typeof dgState !== 'undefined') dgState.formatUserSet = false;
  const select = document.getElementById('dgFormatSelect');
  if (select) select.value = 'plain';
  if (typeof dgSyncFormatUI === 'function') dgSyncFormatUI();
}

function dgLoadMultiChart(idx) {
  const spec = dgMultiCharts[idx];
  if (!spec) return;
  document.querySelectorAll('.dg-multi-gallery-card').forEach(el => el.classList.toggle('active', el.dataset.idx == idx));
  // Radar overview charts hold multiple normalized series (one per entity), not the single
  // label/value list the row editor works with — so it stays a gallery-only preview, still fully
  // exportable and pushable, rather than being silently flattened into something misleading.
  if (spec.type === 'radar') {
    dgActiveMultiChartIdx = null; // not editable here, so nothing should sync back into it
    toast('This radar overview compares every metric at once — push it as-is, or open the per-metric cards to edit colours', 'info');
    return;
  }
  // From here on the editor IS this gallery chart — every dgRender() (chart-type
  // switch, colour pick, row edit, title edit, radius, axes…) writes straight back
  // into dgMultiCharts[idx] and repaints its thumbnail, so the edit isn't lost the
  // moment the person clicks another card or hits "Push all to Workspace".
  dgActiveMultiChartIdx = idx;
  dgResetFormatForNewChart();
  if (spec.type === 'grouped' || spec.type === 'hstacked' || spec.type === 'tornado') {
    dgState.groupedCategories = spec.categories.slice();
    dgState.groupedSeries = spec.series.map(s => ({ ...s, values: s.values.slice() }));
    dgState.type = spec.type;
    const titleInput = document.getElementById('dgTitleInput');
    if (titleInput) titleInput.value = spec.title;
    dgRender();
    if (typeof dgFitZoomToHolder === 'function') setTimeout(dgFitZoomToHolder, 0);
    return;
  }
  dgState.rows = spec.rows.map(r => ({ ...r }));
  dgState.type = spec.type;
  const titleInput = document.getElementById('dgTitleInput');
  if (titleInput) titleInput.value = spec.title;
  dgRenderRows();
  dgRender();
  if (typeof dgFitZoomToHolder === 'function') setTimeout(dgFitZoomToHolder, 0);
}

// Writes whatever's currently in the editor back into the gallery slot it came
// from (if any), and repaints just that one thumbnail — called from dgRender()
// so every kind of edit (chart type, colours, data points, title, radius, axes)
// stays in sync without every single edit handler needing its own call-back.
function dgSyncActiveMultiChartFromState() {
  if (dgActiveMultiChartIdx == null) return;
  const spec = dgMultiCharts[dgActiveMultiChartIdx];
  if (!spec) { dgActiveMultiChartIdx = null; return; }
  const titleInput = document.getElementById('dgTitleInput');
  const updated = { ...spec, type: dgState.type, title: (titleInput && titleInput.value) || spec.title };
  if (dgState.type === 'grouped' || dgState.type === 'hstacked' || dgState.type === 'tornado') {
    updated.categories = (dgState.groupedCategories || []).slice();
    updated.series = (dgState.groupedSeries || []).map(s => ({ ...s, values: (s.values || []).slice() }));
    delete updated.rows;
  } else {
    updated.rows = (dgState.rows || []).map(r => ({ ...r }));
    delete updated.categories; delete updated.series;
  }
  dgMultiCharts[dgActiveMultiChartIdx] = updated;

  const strip = document.getElementById('dgMultiGalleryStrip');
  if (!strip) return;
  const canvas = strip.querySelector(`canvas[data-thumb="${dgActiveMultiChartIdx}"]`);
  if (canvas) dgDrawChartSpec(canvas, updated);
  const card = strip.querySelector(`.dg-multi-gallery-card[data-idx="${dgActiveMultiChartIdx}"] .dg-multi-gallery-card-label`);
  if (card) { card.textContent = updated.title; card.title = updated.title; }
}

function dgOpenMultiPushChoice() {
  if (!dgMultiCharts.length) return;
  if (typeof pdfed === 'undefined' || typeof navigate !== 'function') { toast('Workspace editor is unavailable right now', 'error'); return; }
  const sub = document.getElementById('dgMultiPushChoiceSub');
  if (sub) sub.textContent = `Choose where these ${dgMultiCharts.length} charts should go`;
  const overlay = document.getElementById('dgMultiPushChoiceOverlay');
  if (overlay) overlay.classList.add('open');
}
function dgCloseMultiPushChoice() {
  const overlay = document.getElementById('dgMultiPushChoiceOverlay');
  if (overlay) overlay.classList.remove('open');
}
function dgConfirmMultiPushChoice(mode, cardEl) {
  if (cardEl) sarvarcAnimatedPush(cardEl, 'navIcon-workspace');
  dgCloseMultiPushChoice();
  dgPushAllMultiCharts(mode);
}

// A4 raw-pixel size (same coordinate space Workspace already stores placedImages in),
// falling back to the currently-open page's own size if it has one set.
function dgPageRawSize(page) {
  const EXPORT_PXMM = 3.7795;
  const [mmW, mmH] = (page && page.pageMM) || [210, 297];
  return { w: Math.round(mmW * EXPORT_PXMM), h: Math.round(mmH * EXPORT_PXMM) };
}

// Renders one chart spec at full (non-thumbnail) quality, for baking into the Workspace —
// same visual detail as a chart built and pushed by hand (title, values, gridlines, etc).
function dgRenderSpecFullCanvas(spec) {
  const canvas = document.createElement('canvas');
  canvas.width = 1160; canvas.height = 650;
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, W, H);
  const opts = { title: spec.title, values: true, legend: false, numberFormat: 'plain', trendline: false };
  let top = 30;
  if (opts.title) {
    ctx.fillStyle = '#101820';
    ctx.font = '700 26px Inter, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(dgFitLabel(ctx, opts.title, W - 60), W / 2, 44);
    top = 84;
  }
  const rows = spec.rows || [];
  const axisChartTypes = ['bar', 'stacked', 'waterfall', 'pareto', 'line', 'area'];
  const maxLabelLen = Math.max(0, ...rows.map(r => String(r.label || '').length));
  opts.rotateLabels = axisChartTypes.includes(spec.type) && (rows.length > 8 || maxLabelLen > 10);
  const bottom = H - (opts.rotateLabels ? 90 : 64);
  const rightMargin = spec.type === 'pareto' ? 84 : 46;
  const area = { x: 78, y: top, w: W - 78 - rightMargin, h: bottom - top };
  if (spec.type === 'bar' || spec.type === 'stacked') dgDrawBars(ctx, rows, area, opts, spec.type === 'stacked');
  else if (spec.type === 'line' || spec.type === 'area') dgDrawLine(ctx, rows, area, opts, spec.type === 'area');
  else if (spec.type === 'pie' || spec.type === 'donut') dgDrawPie(ctx, rows, { x: W / 2, y: top + area.h / 2, r: Math.min(area.w, area.h) / 2 - 12 }, opts, spec.type === 'donut');
  else if (spec.type === 'waterfall') dgDrawWaterfall(ctx, rows, area, opts);
  else if (spec.type === 'pareto') dgDrawPareto(ctx, rows, area, opts);
  else if (spec.type === 'funnel') dgDrawFunnel(ctx, rows, area, opts);
  else if (spec.type === 'countryzoom') {
    // Per-country map cards (built by dgBuildPerCountryMaps for the multi-chart
    // gallery) were falling through every branch here with nothing drawn — the
    // canvas stayed blank white above its own data table once baked into the
    // Workspace page. This resolves the row's label to its canonical country
    // (same lookup the live editor uses) and actually draws the shape.
    const r0 = rows[0];
    const target = { country: r0 ? dgResolveCountry(r0.label) : null, value: r0 ? r0.value : null };
    dgDrawCountryZoom(ctx, target, area, opts);
  }
  else if (spec.type === 'worldmap') {
    const match = dgAssignWorldMapColors(rows);
    opts.legend = true;
    dgDrawWorldMap(ctx, match, area, opts);
  }
  else if (spec.type === 'radar') { opts.legend = true; dgDrawRadar(ctx, spec.categories, spec.series, { x: 40, y: top, w: W - 80, h: bottom - top }, opts); }
  else if (spec.type === 'grouped' || spec.type === 'hstacked' || spec.type === 'tornado') {
    opts.legend = true;
    const legendLines = dgLayoutLegend(ctx, spec.series.map(s => ({ label: s.name, value: 0, color: s.color })), { ...opts, values: false }, W - 60);
    const legendH = legendLines.length ? legendLines.length * 24 + 16 : 0;
    const groupedArea = { x: area.x, y: area.y, w: area.w, h: area.h - legendH };
    if (spec.type === 'grouped') dgDrawGroupedBars(ctx, spec.categories, spec.series, groupedArea, opts);
    else if (spec.type === 'hstacked') dgDrawDivergingStackedBars(ctx, spec.categories, spec.series, groupedArea, opts);
    else dgDrawTornadoBars(ctx, spec.categories, spec.series, groupedArea, opts);
    if (legendLines.length) dgDrawLegend(ctx, legendLines, W, H - legendH + 10, opts);
  }
  return canvas;
}

// Same rendering as dgRenderSpecFullCanvas, but with the title suppressed so the
// full canvas height goes to the chart itself. Used when the chart is about to be
// tiled down small (Push All Charts to Workspace): a title baked into the raster
// shrinks right along with everything else and turns into unreadable pixel noise
// at tile size, so the caption is placed as its own real, crisply-rendered
// placedText box above the image instead (see dgPushAllMultiCharts) — legible at
// any tile size and editable afterwards like any other text on the page.
function dgRenderSpecChartOnlyCanvas(spec) {
  return dgRenderSpecFullCanvas(Object.assign({}, spec, { title: null }));
}

// Bakes a chart image directly onto a page's placedImages array — the same end state the
// interactive "drag, resize, then Stamp" flow produces, but done in code so many charts can
// be placed in one go without a manual drop for each one.
// Formats a single value with whatever sign was detected for THIS spec (currency symbol or
// percent) rather than the single global dgState.currencySymbol — a batch of pushed charts can
// mix a ₹ revenue column with a plain headcount column with a % growth column, and each one's
// paired table needs to keep showing its own sign, not whichever chart happens to be open live.
function dgFormatValueWithSign(val, format, symbol) {
  const num = Number(val) || 0;
  if (format === 'currency') {
    const sym = symbol || '$';
    const glue = sym.length > 1 ? sym + ' ' : sym;
    return glue + Math.round(num).toLocaleString();
  }
  if (format === 'percent') return (Math.round(num * 10) / 10) + '%';
  return Math.round(num).toLocaleString();
}

// Turns a chart spec's own underlying data into plain table cells — the exact
// figures behind that chart, so they can be placed right alongside it, laid
// out LANDSCAPE (wide: labels/categories run across the header row, values
// fill in below) instead of a tall, narrow two-column list. A short, wide
// table reads more like a real report exhibit and uses the page width the
// chart itself already occupies, instead of trailing on far past the chart.
// Handles both spec shapes used across the module: rows: [{label,value}] for
// a single-series chart, and categories/series for grouped/radar/tornado-style
// charts. Values pick up whatever currency/percent sign was detected for this
// spec (see dgDetectValueSign at spec-build time) via dgFormatValueWithSign.
function dgSpecToTableCells(spec) {
  const fmt = v => {
    try {
      return spec.format
        ? dgFormatValueWithSign(v, spec.format, spec.formatSymbol)
        : dgFormatNumber(v, spec.format || 'auto');
    } catch (e) { return String(v); }
  };
  if (Array.isArray(spec.categories) && Array.isArray(spec.series) && spec.series.length) {
    // One row per series, one column per category — landscape even when there
    // are many categories, since the row count stays pinned to series count.
    const headers = ['Series', ...spec.categories.map(c => String(c ?? ''))];
    const rows = spec.series.map(s => [String(s.name || 'Series'), ...(s.values || []).map(v => fmt(v))]);
    return { headers, rows };
  }
  // Single-series: one header row of labels, one data row of values —
  // the same information the old Label/Value list held, just turned
  // sideways so it reads as a wide strip instead of a tall column.
  const srcRows = spec.rows || [];
  const headers = ['', ...srcRows.map(r => String(r.label ?? ''))];
  const rows = [[spec.title || 'Value', ...srcRows.map(r => fmt(r.value))]];
  return { headers, rows };
}

// Builds a compact placedTable — sized/fitted to availW x availH — straight
// from a chart spec's own data. This is the table that "belongs to" that
// chart: pushing a chart to the Workspace now always brings its numbers
// along, placed directly under it, so a report reads chart-then-its-table,
// next chart-then-its-table, without Refine Report having to guess which
// table (if any) goes with which chart.
function dgBuildTableForSpec(spec, x, y, availW, availH) {
  const { headers, rows } = dgSpecToTableCells(spec);
  if (!rows.length) return null;
  // Landscape orientation means the point count now lives in COLUMNS, not
  // rows (a single-series chart is always exactly 1 data row; a grouped
  // chart is one row per series). Cap the column count instead of the row
  // count so a 40-category upload doesn't produce 40 unreadably narrow
  // columns — the chart's own axis already shows every point in full;
  // the table is meant to be read at a glance, not scanned like raw data.
  const MAX_COLS = 10;
  let displayHeaders = headers, displayRows = rows, truncated = 0;
  const dataColCount = headers.length - 1;
  if (dataColCount > MAX_COLS) {
    truncated = dataColCount - MAX_COLS;
    displayHeaders = [headers[0], ...headers.slice(1, 1 + MAX_COLS), `+${truncated} more`];
    displayRows = rows.map(r => [r[0], ...r.slice(1, 1 + MAX_COLS), '']);
  }
  const layout = daComputeTableLayout(displayHeaders, displayRows);
  const fitted = daFitTableToPage(displayHeaders, displayRows, layout, availW, availH);
  const cells = [displayHeaders, ...displayRows];
  return {
    id: 'tbl_' + (++pdfedTableSeq),
    x, y,
    rows: cells.length,
    cols: displayHeaders.length,
    colWidths: fitted.colWidths.slice(),
    rowHeights: fitted.rowHeights,
    fontSize: fitted.fontSize,
    headerRow: true,
    cells,
    cellStyles: daBuildCellStyles(cells),
    locked: false,
  };
}

function dgBakePlacedImage(pg, dataUrl, x, y, w, h, kind) {
  if (!pg.placedImages) pg.placedImages = [];
  pg.placedImages.push({
    id: 'pimg_' + (++pdfedAnnotState.placedImgSeq),
    dataUrl, x, y, w, h,
    locked: false,
    zIndex: pdfedNextZ(pg),
    // Tags this as a chart/map/etc so Refine Report can treat it differently
    // from a logo or a random dropped-in photo. Multi-chart gallery pushes
    // are always charts (maps are pushed one at a time via dgInsertIntoWorkspace).
    kind: kind || 'chart'
  });
}

// Pushes every chart in the gallery to the Workspace, either as its own new page per chart,
// or all tiled onto the page currently open there — the same two destinations the single-chart
// "Push Chart to Workspace" choice offers, just applied to the whole batch at once.
async function dgPushAllMultiCharts(mode) {
  if (!dgMultiCharts.length) return;
  if (typeof pdfed === 'undefined' || typeof navigate !== 'function') { toast('Workspace editor is unavailable right now', 'error'); return; }

  const noWorkspaceYet = !pdfed.pages || pdfed.pages.length === 0;
  if (noWorkspaceYet) {
    const { w: eW, h: eH } = dgPageRawSize(null);
    const bg = document.createElement('canvas');
    bg.width = eW; bg.height = eH;
    const bctx = bg.getContext('2d');
    bctx.fillStyle = '#ffffff';
    bctx.fillRect(0, 0, eW, eH);
    pdfed.pages = [{ type: 'blank', dataUrl: bg.toDataURL('image/png'), modified: true, edits: {}, textBlocks: [], placedTexts: [], placedImages: [], label: 'Diagram', bgColor: '#ffffff', pageMM: [210, 297] }];
    pdfed.pdfDoc = null;
    pdfed.file = { name: 'Diagrams & Graphs' };
    ['pdfedExportBtn', 'pdfedRefineBtn', 'pdfedExportBtn2', 'pdfedCloseBtn', 'pdfedPageInfoPill'].forEach(id => {
      const el = document.getElementById(id);
      if (el) el.style.display = '';
    });
    const upBtn = document.getElementById('pdfedUploadBtn'); if (upBtn) upBtn.style.display = 'none';
    const fnEl = document.getElementById('pdfedFileName'); if (fnEl) fnEl.textContent = pdfed.file.name;
    const ph = document.getElementById('pdfedPlaceholder'); if (ph) ph.style.display = 'none';
    const cw = document.getElementById('pdfedCanvasWrap'); if (cw) cw.style.display = 'inline-block';
    const tb = document.getElementById('pdfedToolbar'); if (tb) tb.style.visibility = 'visible';
    if (state && state.stats) { state.stats.pdfs++; state.stats.pages++; }
    if (typeof updateStats === 'function') updateStats();
  }

  try {
    if (mode === 'new') {
      // One brand-new page per chart, each sized to fill most of its page.
      let firstNewIdx = -1;
      dgMultiCharts.forEach(spec => {
        const { w: eW, h: eH } = dgPageRawSize(null);
        const canvas = dgRenderSpecChartOnlyCanvas(spec);
        const dataUrl = canvas.toDataURL('image/png');
        const bg = document.createElement('canvas');
        bg.width = eW; bg.height = eH;
        const bctx = bg.getContext('2d');
        bctx.fillStyle = '#ffffff';
        bctx.fillRect(0, 0, eW, eH);
        const pg = { type: 'blank', dataUrl: bg.toDataURL('image/png'), modified: true, edits: {}, textBlocks: [], placedTexts: [], placedImages: [], placedTables: [], label: 'Diagram', bgColor: '#ffffff', pageMM: [210, 297] };
        const margin = Math.round(eW * 0.08);
        const w = eW - margin * 2;
        const availH = eH - margin * 2;
        // A real, crisp title sits above the chart as its own text box (see
        // dgRenderSpecChartOnlyCanvas above) — reserve its strip first, then
        // the chart takes the top ~62% of what's left, and its own data
        // table (built from this same spec) fills the rest below it, so
        // title, chart and table travel together as one paired unit.
        const titleH = 34;
        const chartH = Math.min(Math.round(w * (canvas.height / canvas.width)), Math.round((availH - titleH) * 0.62));
        const chartW = Math.round(chartH * (canvas.width / canvas.height));
        const chartX = Math.max(margin, Math.round((eW - chartW) / 2));
        const chartY = margin + titleH;
        pg.placedTexts.push({
          id: 'ptxt_' + (++pdfedPlacedTextSeq),
          text: spec.title || 'Chart', x: margin, y: margin, fontSize: 18,
          fontFamily: 'Inter, sans-serif', color: '#101820',
          bold: true, italic: false, underline: false, align: 'center',
          locked: false, zIndex: pdfedNextZ(pg), w
        });
        dgBakePlacedImage(pg, dataUrl, chartX, chartY, chartW, chartH);
        const tableY = chartY + chartH + Math.round(margin * 0.5);
        const tableAvailH = eH - margin - tableY;
        const table = dgBuildTableForSpec(spec, margin, tableY, w, tableAvailH);
        if (table) {
          const tblW = table.colWidths.reduce((a, b) => a + b, 0);
          table.x = Math.max(margin, Math.round((eW - tblW) / 2));
          table.zIndex = pdfedNextZ(pg);
          pg.placedTables.push(table);
        }
        pdfed.pages.push(pg);
        if (firstNewIdx === -1) firstNewIdx = pdfed.pages.length - 1;
        if (state && state.stats) state.stats.pages++;
      });
      if (typeof updateStats === 'function') updateStats();
      navigate('pdfeditor');
      if (typeof pdfedBuildStrip === 'function') await pdfedBuildStrip();
      if (typeof pdfedGoto === 'function') await pdfedGoto(firstNewIdx);
      setTimeout(() => { if (typeof pdfedZoomFit === 'function') pdfedZoomFit(); }, 120);
      toast(`Added ${dgMultiCharts.length} charts (each with its own data table) as new Workspace pages`, 'success');
    } else {
      // All charts tiled onto the page currently open, sized to fit without overlapping.
      let idx = pdfed.active;
      if (typeof idx !== 'number' || idx < 0 || idx >= pdfed.pages.length) idx = 0;
      const pg = pdfed.pages[idx];
      const { w: pageW, h: pageH } = dgPageRawSize(pg);
      const n = dgMultiCharts.length;
      const cols = n <= 1 ? 1 : 2;
      const rows = Math.ceil(n / cols);
      const margin = Math.round(pageW * 0.04);
      const cellW = (pageW - margin * (cols + 1)) / cols;
      const cellH = (pageH - margin * (rows + 1)) / rows;
      if (!pg.placedTables) pg.placedTables = [];
      dgMultiCharts.forEach((spec, i) => {
        const canvas = dgRenderSpecChartOnlyCanvas(spec);
        const dataUrl = canvas.toDataURL('image/png');
        const aspect = canvas.height / canvas.width;
        const col = i % cols, row = Math.floor(i / cols);
        const cellX = margin + col * (cellW + margin);
        const cellY = margin + row * (cellH + margin);
        // Each cell stacks three things: a real title text box (crisp at any
        // tile size, unlike a title baked into the shrunken chart raster
        // used to be), the chart, then its own data table underneath — same
        // paired idea as the "new page per chart" destination above, just
        // scaled down to fit inside one tile.
        const titleH = Math.min(20, Math.round(cellH * 0.09));
        pg.placedTexts.push({
          id: 'ptxt_' + (++pdfedPlacedTextSeq),
          text: spec.title || 'Chart', x: cellX, y: cellY, fontSize: 11,
          fontFamily: 'Inter, sans-serif', color: '#101820',
          bold: true, italic: false, underline: false, align: 'center',
          locked: false, zIndex: pdfedNextZ(pg), w: cellW
        });
        const chartCellTop = cellY + titleH;
        const chartCellH = (cellH - titleH) * 0.62;
        let w = cellW, h = w * aspect;
        if (h > chartCellH) { h = chartCellH; w = h / aspect; }
        const x = cellX + (cellW - w) / 2;
        const y = chartCellTop + (chartCellH - h) / 2;
        dgBakePlacedImage(pg, dataUrl, x, y, w, h);
        const tableY = chartCellTop + chartCellH + Math.round(cellH * 0.03);
        const tableAvailH = cellY + cellH - tableY;
        const table = dgBuildTableForSpec(spec, cellX, tableY, cellW, tableAvailH);
        if (table) {
          table.zIndex = pdfedNextZ(pg);
          pg.placedTables.push(table);
        }
      });
      pdfedMarkModified(idx);
      navigate('pdfeditor');
      if (typeof pdfedBuildStrip === 'function') await pdfedBuildStrip();
      if (typeof pdfedGoto === 'function') await pdfedGoto(idx);
      pdfedRenderPlacedImages(idx);
      pdfedRenderPlacedTexts(idx);
      if (typeof pdfedRenderPlacedTables === 'function') pdfedRenderPlacedTables(idx);
      setTimeout(() => { if (typeof pdfedZoomFit === 'function') pdfedZoomFit(); }, 120);
      toast(`Added ${dgMultiCharts.length} charts (with their data tables) to the live Workspace page`, 'success');
    }
  } catch (err) {
    console.error(err);
    toast('Could not push charts: ' + err.message, 'error');
  }
}

// Lightweight standalone renderer used for gallery thumbnails: draws a chart spec onto its own
// canvas without touching the shared dgState/live-preview canvas.
function dgDrawChartSpec(canvas, spec) {
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, W, H);
  ctx.fillStyle = '#101820';
  ctx.font = '700 13px Inter, sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText(dgFitLabel(ctx, spec.title, W - 20), W / 2, 18);
  const opts = { title: '', values: false, legend: spec.type === 'radar', numberFormat: 'auto', trendline: false };
  const area = { x: 34, y: 28, w: W - 34 - 14, h: H - 28 - 24 };
  const rows = spec.rows || [];
  if (spec.type === 'bar' || spec.type === 'stacked') dgDrawBars(ctx, rows, area, opts, spec.type === 'stacked');
  else if (spec.type === 'line' || spec.type === 'area') dgDrawLine(ctx, rows, area, opts, spec.type === 'area');
  else if (spec.type === 'pie' || spec.type === 'donut') dgDrawPie(ctx, rows, { x: W / 2, y: area.y + area.h / 2, r: Math.min(area.w, area.h) / 2 - 6 }, opts, spec.type === 'donut');
  else if (spec.type === 'waterfall') dgDrawWaterfall(ctx, rows, area, opts);
  else if (spec.type === 'pareto') dgDrawPareto(ctx, rows, area, opts);
  else if (spec.type === 'funnel') dgDrawFunnel(ctx, rows, area, opts);
  else if (spec.type === 'radar') dgDrawRadar(ctx, spec.categories, spec.series, area, opts);
  else if (spec.type === 'grouped') dgDrawGroupedBars(ctx, spec.categories, spec.series, area, opts);
  else if (spec.type === 'hstacked') dgDrawDivergingStackedBars(ctx, spec.categories, spec.series, area, opts);
  else if (spec.type === 'tornado') dgDrawTornadoBars(ctx, spec.categories, spec.series, area, opts);
  else if (spec.type === 'worldmap') dgDrawWorldMap(ctx, dgAssignWorldMapColors(rows), area, opts);
  else if (spec.type === 'countryzoom') {
    const r0 = rows[0];
    dgDrawCountryZoom(ctx, { country: r0 ? dgResolveCountry(r0.label) : null, value: r0 ? r0.value : null }, area, opts);
  }
}

// Parses a raw spreadsheet/PDF-table cell into a number, handling the real-world
// formats that a plain "strip everything but digits" pass gets wrong:
//   • Accounting-style negatives — "(45,000)" or a trailing "45,000-" both mean
//     a loss/expense in exported reports, even with no leading "-". Missing this
//     silently flips a negative into a positive.
//   • US vs European decimal separators — "1,234.56" and "1.234,56" are the same
//     number in two conventions; treating both the same way (old code just
//     stripped commas and kept every dot) reads the European form as 1.234,
//     off by ~1000x. Whichever of "." or "," appears LAST is the true decimal
//     point; the other is thousands grouping to discard.
//   • Scientific notation — "1.2e6" previously lost its "e" in the character
//     strip and became 1.26. Detected and parsed directly instead.
function dgParseNumericCell(v) {
  if (typeof v === 'number') return v;
  let s = String(v ?? '').trim();
  if (s === '') return NaN;

  let negative = false;
  if (/^\(.*\)$/.test(s)) { negative = true; s = s.slice(1, -1).trim(); }
  if (/^-/.test(s)) { negative = true; }
  else if (/-\s*$/.test(s)) { negative = true; s = s.replace(/-\s*$/, ''); }

  const sci = s.match(/^-?(\d+(?:\.\d+)?)[eE]([+-]?\d+)$/);
  if (sci) {
    const n = parseFloat(s);
    return isNaN(n) ? NaN : (negative && n > 0 ? -n : n);
  }

  s = s.replace(/[^0-9.,]/g, '');
  const lastDot = s.lastIndexOf('.');
  const lastComma = s.lastIndexOf(',');
  if (lastDot !== -1 && lastComma !== -1) {
    // Both separators present: the later one in the string is the decimal point.
    s = lastComma > lastDot ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  } else if (lastComma !== -1) {
    // Comma-only: a single comma followed by 1-2 digits reads as a decimal
    // comma ("12,5" -> 12.5); anything else ("12,345", or 2+ commas) is
    // thousands grouping.
    const afterLastComma = s.length - lastComma - 1;
    const commaCount = (s.match(/,/g) || []).length;
    s = (commaCount === 1 && afterLastComma > 0 && afterLastComma <= 2)
      ? s.replace(',', '.')
      : s.replace(/,/g, '');
  }
  // Dot-only is left as-is: a single dot reads as a decimal point (the common
  // case here), matching prior behaviour for the everyday "1234.56" case.

  if (s === '' || s === '.') return NaN;
  const n = parseFloat(s);
  if (isNaN(n)) return NaN;
  return negative ? -Math.abs(n) : n;
}

// ── Sign / currency auto-detection: dgParseNumericCell (above) strips out every
// non-digit character to get a clean number, which is right for math but throws away
// a real signal — if the cells actually uploaded were "₹45,000" or "12.5%", that ₹ or %
// says something about how the chart should be LABELLED, not just what the value is.
// This scans the raw (pre-strip) cell text for a percent sign or one of the common
// currency symbols and reports back whichever one a clear majority of sampled cells
// agree on, so Number Format can default to it automatically instead of always
// falling back to plain numbers or a hardcoded $.
const DG_CURRENCY_SIGNS = ['₹', '$', '€', '£', '¥', '₩', '₽', '₺', '₦', '₫', 'R$', 'CHF'];

function dgDetectValueSign(rawCells, headerHint) {
  const samples = (rawCells || []).map(v => String(v ?? '').trim()).filter(Boolean).slice(0, 60);
  const hint = String(headerHint || '');
  // The column header / chart title is a deliberate, human-typed label — e.g. "Growth %"
  // or "Revenue ($)" — and is a more reliable signal than the data cells themselves,
  // which are often bare numbers (13, 21, ...) with no sign attached at all. Check it
  // first so a plainly-numeric "Growth %" column doesn't fall through to whatever
  // currency symbol happened to be active from a previous, unrelated chart.
  const hintIsPercent = /%/.test(hint);
  let hintCurrencySym = null;
  for (const sym of DG_CURRENCY_SIGNS) { if (hint.includes(sym)) { hintCurrencySym = sym; break; } }

  if (samples.length < 3) {
    // Too few cells to trust a majority read from the data itself — fall back to the
    // header/title hint alone, if it says anything.
    if (hintIsPercent) return { format: 'percent', symbol: null };
    if (hintCurrencySym) return { format: 'currency', symbol: hintCurrencySym };
    return null;
  }

  let percentCount = 0;
  const currencyCounts = {};
  let anyCurrencyCount = 0; // total cells carrying ANY currency sign, regardless of which one
  samples.forEach(s => {
    if (/%\s*$/.test(s)) percentCount++;
    for (const sym of DG_CURRENCY_SIGNS) {
      if (s.includes(sym)) { currencyCounts[sym] = (currencyCounts[sym] || 0) + 1; anyCurrencyCount++; break; }
    }
  });
  const n = samples.length;
  const CONFIDENCE = 0.6; // require a clear majority, not just a stray cell or two
  if (percentCount / n >= CONFIDENCE) return { format: 'percent', symbol: null };

  // Multiple-currency-sign handling: real-world data pasted from mixed sources can carry
  // more than one symbol (e.g. some rows in $ and some in ₹, or a stray € typo). Judging
  // "is this currency data?" against a single winning symbol's share would miss that —
  // two symbols at 35%/30% clearly read as currency together even though neither alone
  // crosses CONFIDENCE. So the majority check is against ALL currency-tagged cells
  // combined; only the *symbol choice* (which one to render with) is per-symbol.
  let bestSym = null, bestCount = 0;
  Object.entries(currencyCounts).forEach(([sym, c]) => { if (c > bestCount) { bestCount = c; bestSym = sym; } });
  if (bestSym && anyCurrencyCount / n >= CONFIDENCE) return { format: 'currency', symbol: bestSym };

  // No clear majority in the cells themselves — defer to the header/title hint rather
  // than silently returning null and leaving a stale format (e.g. ₹) from an earlier,
  // unrelated chart in place.
  if (hintIsPercent) return { format: 'percent', symbol: null };
  if (hintCurrencySym) return { format: 'currency', symbol: hintCurrencySym };
  return null;
}

// Applies a detected sign to the Number Format dropdown + dgState, unless the person has
// already manually chosen a format for this chart (dgState.formatUserSet) — auto-detection
// helps on first load, but never fights someone's deliberate choice afterwards.
function dgApplyDetectedSign(detected) {
  if (!detected || (typeof dgState !== 'undefined' && dgState.formatUserSet)) return false;
  if (detected.format === 'currency' && detected.symbol) dgState.currencySymbol = detected.symbol;
  const select = document.getElementById('dgFormatSelect');
  if (select) select.value = detected.format;
  if (typeof dgSyncFormatUI === 'function') dgSyncFormatUI();
  if (typeof toast === 'function') {
    const what = detected.format === 'percent' ? 'a % sign' : `the ${detected.symbol} sign`;
    toast(`Detected ${what} in your data \u2014 Number Format set to ${detected.format === 'percent' ? 'Percentage' : 'Currency (' + detected.symbol + ')'}`, 'info');
  }
  return true;
}

// ── Date / time / age intelligence ──────────────────────────────────────────────────────
// Uploaded tables very often carry a date, timestamp, or birth-date column, and treating those
// columns as plain text (alphabetical sort, raw string labels) or — worse — silently mangling
// them into a giant meaningless number (dgParseNumericCell strips the separators out of
// "2024-01-15" and would otherwise read it as 20240115) makes for a much worse chart than the
// data actually supports. This block recognises real-world date formats, tells a genuine date
// column apart from an ordinary numeric one, and turns a detected birth-date column into a
// ready-to-plot "Age (years)" measure — so someone uploading a roster with a DOB column gets an
// age chart without doing the subtraction by hand, and someone uploading monthly sales gets a
// properly time-ordered line/x-axis instead of whatever order the rows happened to be typed in.
const DG_MONTH_NAMES = {
  jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5, jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11,
  january: 0, february: 1, march: 2, april: 3, june: 5, july: 6, august: 7,
  september: 8, october: 9, november: 10, december: 11
};

// Parses a single cell into a Date, or null if it doesn't look like one. Deliberately narrow
// (a handful of common, unambiguous shapes) rather than a permissive `new Date(str)` call, since
// the built-in parser accepts all sorts of non-date strings and would make ordinary text/number
// columns misfire as dates.
function dgParseDateCell(v) {
  if (v instanceof Date) return isNaN(v) ? null : v;
  if (typeof v === 'number' && isFinite(v)) {
    // Excel/Sheets serial date (days since 1899-12-30). Only trusted inside a plausible
    // real-world date range (~1950-2100) so an ordinary numeric column (age, price, count)
    // that happens to hold a 5-digit number never gets misread as a date.
    if (v > 18262 && v < 73050) {
      const d = new Date(Math.round((v - 25569) * 86400000));
      return isNaN(d) ? null : d;
    }
    return null;
  }
  const s = String(v ?? '').trim();
  if (!s) return null;

  let m = s.match(/^(\d{4})[-\/](\d{1,2})[-\/](\d{1,2})(?:[T\s].*)?$/); // ISO: 2024-01-15[T..]
  if (m) { const d = new Date(+m[1], +m[2] - 1, +m[3]); return isNaN(d) ? null : d; }

  m = s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})$/); // 15/01/2024, 01-15-2024, etc.
  if (m) {
    let a = +m[1], b = +m[2], y = +m[3];
    if (y < 100) y += y < 50 ? 2000 : 1900;
    const day = a > 12 ? a : b, month = a > 12 ? b : a; // day-first when unambiguous, else month-first
    const d = new Date(y, month - 1, day);
    return isNaN(d) ? null : d;
  }

  m = s.match(/^(\d{1,2})(?:st|nd|rd|th)?[\s,-]+([A-Za-z]{3,9})[\s,-]+(\d{2,4})$/); // "15 Jan 2024"
  if (m) {
    const mon = DG_MONTH_NAMES[m[2].toLowerCase()];
    if (mon != null) { let y = +m[3]; if (y < 100) y += y < 50 ? 2000 : 1900; const d = new Date(y, mon, +m[1]); return isNaN(d) ? null : d; }
  }
  m = s.match(/^([A-Za-z]{3,9})[\s,-]+(\d{1,2})(?:st|nd|rd|th)?[\s,]+(\d{2,4})$/); // "Jan 15, 2024"
  if (m) {
    const mon = DG_MONTH_NAMES[m[1].toLowerCase()];
    if (mon != null) { let y = +m[3]; if (y < 100) y += y < 50 ? 2000 : 1900; const d = new Date(y, mon, +m[2]); return isNaN(d) ? null : d; }
  }

  m = s.match(/^(19|20)\d{2}$/); // bare year, e.g. a "Year" column — treated as Jan 1 of that year
  if (m) { const d = new Date(+s, 0, 1); return isNaN(d) ? null : d; }

  return null;
}

// Column-level date detection, sampled the same way dgColumnIsNumeric samples for numbers.
function dgColumnIsDate(colIdx) {
  if (!dgUploadParsed) return false;
  const allRows = dgUploadParsed.rows;
  const SAMPLE_SIZE = 40;
  let sample;
  if (allRows.length <= SAMPLE_SIZE) sample = allRows;
  else {
    const stride = allRows.length / SAMPLE_SIZE;
    sample = [];
    for (let i = 0; i < SAMPLE_SIZE; i++) sample.push(allRows[Math.floor(i * stride)]);
  }
  let dateLike = 0, total = 0;
  sample.forEach(r => {
    const v = r[colIdx];
    if (String(v ?? '').trim() === '') return;
    total++;
    if (dgParseDateCell(v)) dateLike++;
  });
  // A lone 4-digit number is ambiguous with a plain small integer column, so a column read as
  // dates ONLY via the bare-year fallback needs every sampled cell to agree before it counts —
  // any other date shape (slashes, dashes, month names) is unambiguous and uses a normal majority.
  const allBareYears = total > 0 && sample.every(r => { const v = String(r[colIdx] ?? '').trim(); return v === '' || /^(19|20)\d{2}$/.test(v); });
  const threshold = allBareYears ? 1.0 : 0.6;
  return total > 0 && (dateLike / total) >= threshold;
}

// Header text hint for "this column is probably someone's birth date" — used to auto-offer a
// derived Age column rather than making people compute it by hand.
function dgIsBirthDateHeader(header) {
  return /\b(dob|d\.o\.b\.?|birth\s*-?date|date\s*of\s*birth|birthday)\b/i.test(String(header || ''));
}

// Whole-years age between a birth date and a reference date (default: today), accounting for
// whether the birthday has actually happened yet this year rather than just subtracting years.
function dgComputeAge(birthDate, refDate) {
  const ref = refDate || new Date();
  let age = ref.getFullYear() - birthDate.getFullYear();
  const m = ref.getMonth() - birthDate.getMonth();
  if (m < 0 || (m === 0 && ref.getDate() < birthDate.getDate())) age--;
  return age;
}

// Picks a label granularity that fits the actual spread of dates in a column — years apart
// shows just the year, a same-year spread shows "Jan 2024", and a tight day-to-day range shows
// the full date — so a time-series axis never prints a redundant year on every tick or, at the
// other extreme, an unreadably long date for a chart spanning a decade.
function dgDetectDateGranularity(dates) {
  if (!dates.length) return 'day';
  const sorted = [...dates].sort((a, b) => a - b);
  const spanDays = (sorted[sorted.length - 1] - sorted[0]) / 86400000;
  if (spanDays > 730) return 'year';
  if (spanDays > 60) return 'month';
  return 'day';
}

function dgFormatDateLabel(date, granularity) {
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  if (granularity === 'year') return String(date.getFullYear());
  if (granularity === 'month') return `${months[date.getMonth()]} ${date.getFullYear()}`;
  return `${months[date.getMonth()]} ${date.getDate()}, ${date.getFullYear()}`;
}

// A dense time series (hundreds/thousands of individual dated rows) can't be plotted one bar
// per row — the bars shrink to hairlines and, worse, simply truncating to the first MAX_POINTS
// rows in chronological order only ever shows the EARLIEST slice of the range (e.g. just the
// first month of a year of data), while every one of those bars still gets labelled at whatever
// granularity fits the FULL span ("Jan 2025" repeated on 40 different daily bars). This sums
// the value column into buckets — day, then week, then month, then quarter, then year — walking
// up the ladder only as far as needed to land at or under maxPoints buckets, so the chart always
// (a) covers the whole date range the person actually has, (b) never shows two bars with an
// identical label representing different periods, and (c) stays at a bar count wide screens can
// render without hairlines.
function dgBucketDateRows(parsed, maxPoints) {
  const ladder = ['day', 'week', 'month', 'quarter', 'year'];
  const baseGranularity = dgDetectDateGranularity(parsed.map(p => p.dateVal));
  let startIdx = ladder.indexOf(baseGranularity);
  if (startIdx < 0) startIdx = 0;

  const quarterOf = d => Math.floor(d.getMonth() / 3) + 1;
  const mondayOf = d => {
    const wd = new Date(d.getFullYear(), d.getMonth(), d.getDate());
    const offset = (wd.getDay() + 6) % 7; // 0 = Monday
    wd.setDate(wd.getDate() - offset);
    return wd;
  };
  const bucketKey = (date, g) => {
    if (g === 'year') return `${date.getFullYear()}`;
    if (g === 'quarter') return `${date.getFullYear()}-Q${quarterOf(date)}`;
    if (g === 'month') return `${date.getFullYear()}-${date.getMonth()}`;
    if (g === 'week') return `wk-${mondayOf(date).getTime()}`;
    return `${date.getFullYear()}-${date.getMonth()}-${date.getDate()}`;
  };
  const bucketLabel = (date, g) => {
    if (g === 'quarter') return `Q${quarterOf(date)} ${date.getFullYear()}`;
    if (g === 'week') return `Wk of ${dgFormatDateLabel(mondayOf(date), 'day')}`;
    return dgFormatDateLabel(date, g);
  };

  for (let i = startIdx; i < ladder.length; i++) {
    const g = ladder[i];
    const map = new Map();
    parsed.forEach(p => {
      const key = bucketKey(p.dateVal, g);
      let b = map.get(key);
      if (!b) { b = { label: bucketLabel(p.dateVal, g), value: 0, dateVal: p.dateVal }; map.set(key, b); }
      b.value += p.value;
      if (p.dateVal < b.dateVal) b.dateVal = p.dateVal;
    });
    if (map.size <= maxPoints || g === 'year') {
      return { granularity: g, rows: Array.from(map.values()).sort((a, b) => a.dateVal - b.dateVal) };
    }
  }
  return { granularity: 'year', rows: parsed.slice(0, maxPoints) }; // unreachable, ladder ends on 'year'
}

function dgColumnIsNumeric(colIdx) {
  if (!dgUploadParsed) return false;
  // A genuine date column (even a slash/dash-formatted one that's technically all digits once
  // the separators are stripped) should never be treated as a numeric measure — plotting
  // "2024-01-15" as the number 20240115 is never what anyone wants.
  if (dgColumnIsDate(colIdx)) return false;
  const allRows = dgUploadParsed.rows;
  const SAMPLE_SIZE = 40;
  // Spread the sample across the WHOLE column, not just the first 25 rows —
  // a stray subtotal row, units row, or blank cluster near the top of a long
  // file previously could skew a genuinely-numeric column into reading as
  // text (or vice versa). Striding across the full row range gives a
  // representative read regardless of where in the file anomalies sit.
  let sample;
  if (allRows.length <= SAMPLE_SIZE) {
    sample = allRows;
  } else {
    const stride = allRows.length / SAMPLE_SIZE;
    sample = [];
    for (let i = 0; i < SAMPLE_SIZE; i++) sample.push(allRows[Math.floor(i * stride)]);
  }
  let numeric = 0, total = 0;
  sample.forEach(r => {
    const v = r[colIdx];
    if (String(v ?? '').trim() === '') return;
    total++;
    if (!isNaN(dgParseNumericCell(v))) numeric++;
  });
  return total > 0 && (numeric / total) > 0.6;
}

// ── Identifier-column detection ──────────────────────────────────────────
// "Order ID", "Invoice No", "Customer ID" columns parse as numeric (they're
// digits) but they're LABELS, not measures — an ID has no meaningful sum,
// average, or trend. Charted as a value next to real measures like Revenue
// or Unit Price, an ID column produces stats that are arithmetically valid
// but semantically nonsense.
//
// This is deliberately NOT a header-keyword lookup. A wordlist ("id", "no",
// "code"...) only understands columns that happen to be spelled in English
// the way the wordlist expects — it fails silently on "Sr.", "Roll", a
// Hindi/Gujarati header, or any header at all if the sheet has none. What
// actually makes a column an identifier isn't its name, it's how its values
// behave relative to the rows they sit in. Three structural signals, none
// of them language-dependent:
//   1. Near-total uniqueness — a real measure (price, quantity, revenue)
//      naturally repeats across rows; an identifier is ~1 distinct value
//      per row. Required baseline for every route below.
//   2. Row-order correlation — an identifier is fundamentally an
//      enumeration of the rows themselves, so its values track row
//      position (Pearson r against row index) whether it counts 1,2,3,...
//      or 1005,1010,1015,... or counts downward. A genuine measure has no
//      structural reason to move in lockstep with upload row order.
//   3. Alphanumeric code shape — letters mixed with digits in most values
//      (ORD1001, INV-2026-045) is a shape business measures don't take,
//      independent of whether the codes happen to be sequential.
// A column only needs to clear (1) plus EITHER (2) or (3) — it's read from
// what the column IS, not what it's called.
function dgRowOrderCorrelation(nums) {
  const n = nums.length;
  if (n < 3) return 0;
  const meanIdx = (n - 1) / 2;
  const meanVal = nums.reduce((a, b) => a + b, 0) / n;
  let cov = 0, varIdx = 0, varVal = 0;
  for (let i = 0; i < n; i++) {
    const dx = i - meanIdx, dy = nums[i] - meanVal;
    cov += dx * dy; varIdx += dx * dx; varVal += dy * dy;
  }
  if (varIdx === 0 || varVal === 0) return 0;
  return cov / Math.sqrt(varIdx * varVal);
}

function dgValuesLookLikeAlnumCode(vals) {
  // Mixed letters-and-digits in a consistent shape (ORD1001, INV-2026-045,
  // TXN-00931) — real measures don't take this shape; codes do.
  const codeLike = vals.filter(v => /[a-z]/i.test(v) && /\d/.test(v));
  return vals.length > 0 && (codeLike.length / vals.length) > 0.8;
}

function dgIsIdentifierColumn(colIdx) {
  if (!dgUploadParsed) return false;
  const rows = dgUploadParsed.rows;
  const vals = rows.map(r => String(r[colIdx] ?? '').trim()).filter(v => v !== '');
  if (vals.length < 3) return false; // too few rows to judge shape/uniqueness meaningfully
  const uniqueRatio = new Set(vals).size / vals.length;
  if (uniqueRatio <= 0.85) return false; // real measures repeat; identifiers essentially never do

  // Certain: mixed letters+digits is a shape real business measures don't take at
  // all, sequential or not — safe to treat as a hard identifier.
  if (dgValuesLookLikeAlnumCode(vals)) return 'hard';

  // Ambiguous: a purely numeric column that tracks row order near-perfectly IS
  // what a row index looks like, but it's also EXACTLY what a genuinely rising,
  // all-unique measure looks like (a running balance, cumulative revenue, a
  // steadily climbing KPI) — the two are structurally identical from values
  // alone, with no reliable way to tell them apart without semantic context this
  // function doesn't have. So this is a signal to default off and flag, not a
  // reason to hide the column outright — the person uploading it still knows
  // whether it's really an index or a real measure, even when the statistics
  // can't.
  const nums = vals.map(v => dgParseNumericCell(v)).filter(n => !isNaN(n));
  if (nums.length === vals.length && Math.abs(dgRowOrderCorrelation(nums)) > 0.9) return 'soft';

  return false;
}



// ── Map mode: "country column" detection ────────────────────────────────
// Scores a column by how many of its sampled cells resolve against the
// world-map dataset (dgResolveCountry) — the same sampling approach as
// dgColumnIsNumeric above, just checking "looks like a country" instead of
// "looks like a number".
function dgColumnCountryMatchRatio(colIdx) {
  if (!dgUploadParsed) return 0;
  const allRows = dgUploadParsed.rows;
  const SAMPLE_SIZE = 40;
  let sample;
  if (allRows.length <= SAMPLE_SIZE) {
    sample = allRows;
  } else {
    const stride = allRows.length / SAMPLE_SIZE;
    sample = [];
    for (let i = 0; i < SAMPLE_SIZE; i++) sample.push(allRows[Math.floor(i * stride)]);
  }
  let matched = 0, total = 0;
  sample.forEach(r => {
    const v = r[colIdx];
    if (String(v ?? '').trim() === '') return;
    total++;
    if (dgResolveCountry(v)) matched++;
  });
  return total > 0 ? matched / total : 0;
}

// Picks whichever column looks most like a country column — highest match ratio,
// as long as it clears a "this is genuinely countries, not a coincidence" bar —
// used to flag and default the Label Column dropdown when the Map tab is active.
function dgBestCountryColumnIdx() {
  if (!dgUploadParsed) return -1;
  const { headers } = dgUploadParsed;
  let bestIdx = -1, bestScore = 0;
  headers.forEach((_, i) => {
    const score = dgColumnCountryMatchRatio(i);
    if (score > bestScore) { bestScore = score; bestIdx = i; }
  });
  return bestScore >= 0.5 ? bestIdx : -1;
}

// Re-tags the Label Column dropdown's option text for the current mode (called when
// switching in/out of the Map tab on data that's already loaded, since
// dgPopulateUploadSelectors only runs at upload time). Leaves the person's current
// selection alone if it already looks like a country column; otherwise jumps to the
// detected one so Map mode doesn't silently try to plot the wrong column.
function dgRefreshLabelColDetection() {
  if (!dgUploadParsed) return;
  const labelSel = document.getElementById('dgLabelColSelect');
  if (!labelSel) return;
  const { headers } = dgUploadParsed;
  const isMapMode = dgActiveMode === 'map';
  const bestCountryIdx = isMapMode ? dgBestCountryColumnIdx() : -1;
  const prevIdx = labelSel.value !== '' ? parseInt(labelSel.value, 10) : -1;
  const optionsHtml = headers.map((h, i) => {
    const tag = (i === bestCountryIdx) ? ' \u2014 Country column detected \ud83c\udf0d' : '';
    return `<option value="${i}">${daEsc(h)}${tag}</option>`;
  }).join('');
  labelSel.innerHTML = optionsHtml;
  const currentLooksLikeCountry = prevIdx >= 0 && dgColumnCountryMatchRatio(prevIdx) >= 0.5;
  const nextIdx = (isMapMode && bestCountryIdx >= 0 && !currentLooksLikeCountry) ? bestCountryIdx : prevIdx;
  labelSel.value = nextIdx >= 0 ? nextIdx : 0;
  dgRenderValueColChecks();
  dgGenerateChartFromUpload();
}

function dgPopulateUploadSelectors() {
  if (!dgUploadParsed) return;
  const { headers } = dgUploadParsed;
  const labelSel = document.getElementById('dgLabelColSelect');
  if (!labelSel) return;
  const numericFlags = headers.map((_, i) => dgColumnIsNumeric(i));
  const dateFlags = headers.map((_, i) => dgColumnIsDate(i));
  // Map mode: the Label Column dropdown IS the "which column holds my countries" picker,
  // so flag whichever column actually looks like a country list right in its option text
  // instead of leaving the person to guess from the header name alone.
  const isMapMode = dgActiveMode === 'map';
  const bestCountryIdx = isMapMode ? dgBestCountryColumnIdx() : -1;
  // A date column is the natural x-axis/category for a time series, so flag it in the Label
  // Column dropdown the same way a detected country column is flagged for the Map tab.
  const bestDateIdx = !isMapMode ? dateFlags.findIndex(Boolean) : -1;
  const optionsHtml = headers.map((h, i) => {
    let tag = '';
    if (i === bestCountryIdx) tag = ' \u2014 Country column detected \ud83c\udf0d';
    else if (i === bestDateIdx) tag = ' \u2014 Date column detected \ud83d\udcc5';
    return `<option value="${i}">${daEsc(h)}${tag}</option>`;
  }).join('');
  labelSel.innerHTML = optionsHtml;
  const firstLabelIdx = numericFlags.findIndex(n => !n);
  // Prefer a genuine measure column over a "Total"/"Grand Total" column as the default
  // value column — if someone uploads Product | Q1 | Q2 | Q3 | Total, the default chart
  // should plot Q1 (a real, comparable number), not a column that's the sum of the other
  // three. Only falls back to the Total column if it's the ONLY numeric column present.
  const firstNonAggregateNumericIdx = numericFlags.findIndex((n, i) => n && !dgIsAggregateHeader(headers[i]) && !dgIsIdentifierColumn(i));
  const firstNumericIdx = firstNonAggregateNumericIdx >= 0 ? firstNonAggregateNumericIdx
    : (numericFlags.findIndex((n, i) => n && !dgIsIdentifierColumn(i)) >= 0 ? numericFlags.findIndex((n, i) => n && !dgIsIdentifierColumn(i)) : numericFlags.findIndex(n => n));
  // On the Map tab, default straight to the detected country column when there is one; otherwise
  // prefer a detected date column as the x-axis (time series read far better than an arbitrary
  // row order), and only fall back to the old "first non-numeric column" guess after that.
  labelSel.value = bestCountryIdx >= 0 ? bestCountryIdx : (bestDateIdx >= 0 ? bestDateIdx : (firstLabelIdx >= 0 ? firstLabelIdx : 0));
  let valueIdx = firstNumericIdx >= 0 ? firstNumericIdx : (headers.length > 1 ? 1 : 0);
  if (valueIdx === parseInt(labelSel.value, 10) && headers.length > 1) {
    valueIdx = (valueIdx + 1) % headers.length;
  }
  dgRenderValueColChecks(valueIdx);
  const hint = document.getElementById('dgUploadHint');
  if (hint) {
    const numCount = numericFlags.filter(Boolean).length;
    const dateNote = bestDateIdx >= 0 ? ` \u00b7 date column found \u2014 charted in chronological order` : '';
    const hardIdIdxs = headers.map((_, i) => i).filter(i => numericFlags[i] && dgIsIdentifierColumn(i) === 'hard');
    const softIdIdxs = headers.map((_, i) => i).filter(i => numericFlags[i] && dgIsIdentifierColumn(i) === 'soft');
    const hardNote = hardIdIdxs.length ? ` \u00b7 ${hardIdIdxs.length} ID column${hardIdIdxs.length === 1 ? '' : 's'} (${hardIdIdxs.map(i => headers[i]).join(', ')}) kept out of Values \u2014 use as Label instead` : '';
    const softNote = softIdIdxs.length ? ` \u00b7 ${softIdIdxs.map(i => headers[i]).join(', ')} look${softIdIdxs.length === 1 ? 's' : ''} like a row index \u2014 left unticked, but available if it's really a measure` : '';
    hint.textContent = `${dgUploadParsed.rows.length} rows detected \u00b7 ${numCount} numeric column${numCount === 1 ? '' : 's'} found${dateNote}${hardNote}${softNote}. Tick just one column for a normal chart, or 2+ to build a side-by-side comparison.`;
  }
  dgRenderUploadPreview(numericFlags, dateFlags);
}

// Reads which value-column checkboxes the person has ticked, in the order they appear
// (i.e. column order in the file) — a stable order so series colouring stays consistent
// across re-renders instead of shuffling based on click order.
function dgGetCheckedValueCols() {
  return Array.from(document.querySelectorAll('#dgValueColChecks input[type="checkbox"]:checked'))
    .map(cb => parseInt(cb.value, 10))
    .sort((a, b) => a - b);
}

// Builds the "Value column(s)" checklist: every numeric column except whichever one is
// currently chosen as the label column. Ticking just one behaves like the old single-value
// dropdown; ticking 2+ is an explicit, no-guessing way to say "these are the same measure,
// compare them" — the manual counterpart to the automatic Profit-2025/2026/2027 stem detector.
function dgRenderValueColChecks(defaultIdx) {
  const wrap = document.getElementById('dgValueColChecks');
  if (!wrap || !dgUploadParsed) return;
  const { headers } = dgUploadParsed;
  const labelSel = document.getElementById('dgLabelColSelect');
  const labelIdx = labelSel && labelSel.value !== '' ? parseInt(labelSel.value, 10) : -1;
  const scheme = dgCurrentScheme();
  // Hard identifiers (alphanumeric codes — ORD1001, CMP-2026-01) are excluded
  // outright: that shape is never a real business measure, so offering them as
  // tickable "values" only invites comparing a code against a revenue total.
  // "Soft" flags (a purely numeric column that tracks row order almost
  // perfectly) stay in the list — that shape is genuinely ambiguous, it can be
  // a row index OR a real climbing measure (running balance, cumulative
  // total) — so those are kept selectable, just unchecked by default and
  // visibly labeled, so the person decides instead of the heuristic deciding
  // for them. Either way, an ID column is still fully available as the Label
  // Column, which is where an identifier actually belongs.
  const numericIdxs = headers.map((_, i) => i).filter(i => i !== labelIdx && dgColumnIsNumeric(i) && dgIsIdentifierColumn(i) !== 'hard');
  const prevChecked = new Set(dgGetCheckedValueCols());
  wrap.innerHTML = numericIdxs.length ? numericIdxs.map((i, si) => {
    const idLevel = dgIsIdentifierColumn(i);
    const checked = prevChecked.size ? prevChecked.has(i) : (!idLevel && i === defaultIdx);
    const flagNote = idLevel === 'soft' ? ' <span class="dg-upload-value-flag" title="Values track row order almost perfectly \u2014 looks like a row index. Tick only if this is really a measure you want to chart.">\u26a0\ufe0f looks like a row index</span>' : '';
    return `
      <label class="dg-upload-value-check">
        <input type="checkbox" value="${i}" ${checked ? 'checked' : ''} onchange="dgGenerateChartFromUpload()">
        <span class="dg-upload-value-swatch" style="background:${scheme[si % scheme.length]}"></span>
        <span class="dg-upload-value-check-label" title="${daEsc(headers[i])}">${daEsc(headers[i])}</span>${flagNote}
      </label>`;
  }).join('') : `<div class="dg-upload-hint" style="margin:0">No other numeric columns found</div>`;
  dgSyncQuickAxisSelects();
}

// Changing the label column can change which columns are even eligible as value columns
// (a column can't be both), so the checklist needs rebuilding before the chart re-plots.
function dgOnLabelColSelectChange() {
  dgRenderValueColChecks();
  dgGenerateChartFromUpload();
}

// Keeps the always-visible "quick" X/Y pickers (one pair in the main toolbar, one pair
// duplicated in the Map Explorer modal header) mirroring whatever the fuller Columns panel
// currently has selected. Called every time dgRenderValueColChecks() runs — i.e. on upload,
// on label-column change, on swap — so the quick pickers never drift out of sync with the
// underlying #dgLabelColSelect / #dgValueColChecks they're driving. Cheap to just rebuild
// both pairs' <option> lists each time rather than diffing; these lists are tiny (one entry
// per column).
function dgSyncQuickAxisSelects() {
  if (!dgUploadParsed) return;
  const labelSel = document.getElementById('dgLabelColSelect');
  if (!labelSel) return;
  const xTargets = [document.getElementById('dgQuickXSelect'), document.getElementById('dgMapxQuickXSelect')];
  xTargets.forEach(sel => { if (sel) { sel.innerHTML = labelSel.innerHTML; sel.value = labelSel.value; } });

  // Build the Y option list from whatever dgRenderValueColChecks just put in the checklist
  // (it already excludes the label column and hard-identifier columns), rather than
  // recomputing eligibility rules a second time here.
  const checkboxes = Array.from(document.querySelectorAll('#dgValueColChecks input[type="checkbox"]'));
  const checked = checkboxes.filter(cb => cb.checked).map(cb => cb.value);
  const yOptionsHtml = checkboxes.map(cb => {
    const labelText = cb.closest('.dg-upload-value-check')?.querySelector('.dg-upload-value-check-label')?.textContent || cb.value;
    return `<option value="${cb.value}">${daEsc(labelText)}</option>`;
  }).join('');
  const multi = checked.length > 1;
  const yTargets = [document.getElementById('dgQuickYSelect'), document.getElementById('dgMapxQuickYSelect')];
  yTargets.forEach(sel => {
    if (!sel) return;
    sel.innerHTML = yOptionsHtml || '<option value="">—</option>';
    if (checked.length) sel.value = checked[0];
    // Multiple Y columns can still be ticked programmatically (e.g. an auto-detected
    // comparison chart), which the single quick-select can't represent — disable it in
    // that case rather than silently collapsing the comparison the moment it's touched.
    sel.disabled = multi || !checkboxes.length;
    sel.title = multi
      ? 'Multiple Y-Axis columns are currently plotted for comparison'
      : 'Column plotted on the Y-Axis';
  });
}

// Fires from either quick X-Axis dropdown (toolbar or Map Explorer). Just forwards the
// choice into the real #dgLabelColSelect and reuses its existing change handler, so every
// downstream effect (rebuilding eligible Y columns, re-detecting country/date columns,
// re-rendering the chart, refreshing the Map Explorer markers if it's open) stays identical
// to picking the same column from the Columns panel.
function dgQuickSetXAxis(idxStr) {
  const labelSel = document.getElementById('dgLabelColSelect');
  if (!labelSel || idxStr === '') return;
  labelSel.value = idxStr;
  dgOnLabelColSelectChange();
}

// Fires from either quick Y-Axis dropdown. Ticks exactly that one value-column checkbox
// (unticking any others) and re-renders — the quick picker's single-select shape only ever
// represents "one Y column," matching what it shows once dgSyncQuickAxisSelects disables it
// during a multi-column comparison.
function dgQuickSetYAxis(idxStr) {
  if (idxStr === '') return;
  const checkboxes = document.querySelectorAll('#dgValueColChecks input[type="checkbox"]');
  checkboxes.forEach(cb => { cb.checked = (cb.value === idxStr); });
  dgGenerateChartFromUpload();
  dgSyncQuickAxisSelects();
}

// Collapses/expands the raw-data preview table inside the Columns panel — it's useful for a
// sanity check but takes up a lot of vertical space, so it starts closed and stays out of the
// way of the two controls (X-Axis, Y-Axis) people actually need on every visit.
function dgToggleUploadPreview() {
  const wrap = document.getElementById('dgUploadPreview');
  const toggle = document.getElementById('dgUploadPreviewToggle');
  if (!wrap || !toggle) return;
  const open = wrap.style.display !== 'none';
  wrap.style.display = open ? 'none' : '';
  toggle.classList.toggle('open', !open);
}

// One-click "Swap X / Y": the current X-Axis column becomes a Y-Axis value, and the first
// ticked Y-Axis value becomes the new X-Axis. Saves re-opening two separate controls to flip
// which column drives the categories vs. the plotted numbers.
function dgSwapAxes() {
  const labelSel = document.getElementById('dgLabelColSelect');
  if (!labelSel || !dgUploadParsed) return;
  const checked = dgGetCheckedValueCols();
  if (!checked.length) { toast('Tick a Y-Axis value first, then swap', 'error'); return; }
  const oldLabelIdx = parseInt(labelSel.value, 10);
  const newLabelIdx = checked[0];
  labelSel.value = String(newLabelIdx);
  dgRenderValueColChecks(oldLabelIdx);
  dgGenerateChartFromUpload();
}

// Complex uploads (many columns, mixed types, big row counts) are hard to reason about from a
// bare pair of dropdowns. This gives a quick visual sanity-check — column type badges plus a
// peek at the first few rows — before the person commits to a label/value mapping.
function dgRenderUploadPreview(numericFlags, dateFlags) {
  const wrap = document.getElementById('dgUploadPreview');
  if (!wrap || !dgUploadParsed) return;
  const { headers, rows } = dgUploadParsed;
  const flags = numericFlags || headers.map((_, i) => dgColumnIsNumeric(i));
  const dFlags = dateFlags || headers.map((_, i) => dgColumnIsDate(i));
  const dateCount = dFlags.filter(Boolean).length;
  const numCount = flags.filter(Boolean).length;
  const textCount = headers.length - numCount - dateCount;
  const sampleRows = rows.slice(0, 4);
  const chips = `
    <div class="dg-upload-preview-chips">
      <span class="dg-upload-chip">${rows.length} rows</span>
      <span class="dg-upload-chip">${headers.length} columns</span>
      <span class="dg-upload-chip">${numCount} numeric</span>
      ${dateCount ? `<span class="dg-upload-chip date">${dateCount} date/time</span>` : ''}
      ${textCount ? `<span class="dg-upload-chip text">${textCount} text</span>` : ''}
    </div>`;
  const theadCells = headers.map((h, i) => {
    const kind = dFlags[i] ? 'date' : (flags[i] ? '' : 'text');
    const label = dFlags[i] ? '\ud83d\udcc5 Date' : (flags[i] ? '123 Numeric' : 'ABC Text');
    return `<th title="${daEsc(h)}">${daEsc(h)}<span class="dg-upload-preview-type${kind ? ' ' + kind : ''}">${label}</span></th>`;
  }).join('');
  const bodyRows = sampleRows.map(r => `
    <tr>${headers.map((_, i) => `<td title="${daEsc(String(r[i] ?? ''))}">${daEsc(String(r[i] ?? ''))}</td>`).join('')}</tr>
  `).join('');
  wrap.innerHTML = `
    ${chips}
    <div class="dg-upload-preview-table-wrap">
      <table class="dg-upload-preview-table">
        <thead><tr>${theadCells}</tr></thead>
        <tbody>${bodyRows}</tbody>
      </table>
    </div>`;
}

function dgGenerateChartFromUpload(topGrouped) {
  if (!dgUploadParsed) { toast('Upload a data file first', 'info'); return; }
  const labelSel = document.getElementById('dgLabelColSelect');
  if (!labelSel || labelSel.value === '') return;
  const labelIdx = parseInt(labelSel.value, 10);
  let valueIdxs = dgGetCheckedValueCols();
  if (!valueIdxs.length) { toast('Tick at least one value column to plot', 'info'); return; }
  const scheme = dgCurrentScheme();
  const MAX_POINTS = 40;
  const rawRows = dgUploadParsed.rows;

  if (valueIdxs.length >= 2) {
    // Comparability guard \u2014 ticking 2+ columns is an explicit "compare these" request,
    // but that request can still mix incompatible measures (Unit Price vs. Total Sales, a
    // raw count vs. a currency total) if someone ticks whatever happens to look numeric.
    // Reuse the exact same unit/stem/magnitude clustering the automatic stem-detector uses
    // (dgGroupNumericColumns, above) so a manual multi-tick gets the same protection
    // instead of silently charting apples against oranges on one shared axis.
    const clusters = dgGroupNumericColumns(dgUploadParsed.headers, valueIdxs, rawRows);
    if (clusters.length > 1) {
      // Keep whichever cluster the FIRST ticked column belongs to \u2014 the column ticked
      // first is the best signal of what the person actually meant to compare \u2014 and
      // drop the rest. Never silent: uncheck those boxes and say exactly why.
      const keepCluster = clusters.find(c => c.includes(valueIdxs[0])) || clusters[0];
      const dropped = valueIdxs.filter(i => !keepCluster.includes(i));
      if (dropped.length) {
        dropped.forEach(i => {
          const cb = document.querySelector(`#dgValueColChecks input[type="checkbox"][value="${i}"]`);
          if (cb) cb.checked = false;
        });
        const droppedNames = dropped.map(i => dgUploadParsed.headers[i]).join(', ');
        const keptNames = keepCluster.map(i => dgUploadParsed.headers[i]).join(', ');
        toast(`${droppedNames} isn\u2019t on the same scale as ${keptNames} \u2014 left out so the axis stays meaningful. Chart it on its own if you need it.`, 'info');
      }
      valueIdxs = keepCluster.slice().sort((a, b) => a - b);
    }
    // 2+ (now comparability-checked) columns ticked \u2014 build the same categories/series
    // shape the automatic stem detector builds, so it plugs straight into the existing 2D
    // grouped bar, 3D grouped bar, and Hologram renderers untouched.
    const MAX_CATEGORIES = 30;
    // Same time-series awareness as the single-series path below: a date label column gets
    // sorted chronologically and re-labelled at a fitting granularity, so a grouped/clustered
    // comparison chart built from monthly or yearly data reads left-to-right through time
    // instead of in upload row order.
    const groupedLabelColIsDate = dgColumnIsDate(labelIdx);
    let candidateRows = rawRows.map(r => ({ r, dateVal: groupedLabelColIsDate ? dgParseDateCell(r[labelIdx]) : null }))
      .filter(x => !groupedLabelColIsDate || x.dateVal);
    if (groupedLabelColIsDate) candidateRows.sort((a, b) => a.dateVal - b.dateVal);
    const groupedGranularity = groupedLabelColIsDate ? dgDetectDateGranularity(candidateRows.map(x => x.dateVal)) : null;
    const categories = [];
    const rowsUsed = [];
    let excludedTotalRows = 0;
    for (let i = 0; i < candidateRows.length && categories.length < MAX_CATEGORIES; i++) {
      const r = candidateRows[i].r;
      const label = groupedLabelColIsDate
        ? dgFormatDateLabel(candidateRows[i].dateVal, groupedGranularity)
        : (String(r[labelIdx] ?? '').trim() || `Item ${categories.length + 1}`);
      // A "Total"/"Grand Total"/"Average" row baked into the sheet isn't its own category
      // — it's the sum of the others, and would dwarf every real bar in the group.
      if (dgIsAggregateLabel(label)) { excludedTotalRows++; continue; }
      categories.push(label);
      rowsUsed.push(r);
    }
    if (!categories.length) { toast('Could not find any rows to chart', 'error'); return; }
    // Sniff the first ticked column's raw cells for a currency/percent sign — grouped
    // series are plotted on one shared axis, so one shared format is what matters here.
    // Also pass the column header + current chart title as a hint (e.g. a "Growth %"
    // column of bare numbers should read as percent even though no individual cell
    // carries a % sign).
    const signHint1 = [dgUploadParsed.headers[valueIdxs[0]], document.getElementById('dgTitleInput')?.value].filter(Boolean).join(' ');
    dgApplyDetectedSign(dgDetectValueSign(rowsUsed.map(r => r[valueIdxs[0]]), signHint1));
    const series = valueIdxs.map((colIdx, si) => ({
      name: String(dgUploadParsed.headers[colIdx] || ('Column ' + (colIdx + 1))),
      color: scheme[si % scheme.length],
      values: rowsUsed.map(r => { const v = dgParseNumericCell(r[colIdx]); return isNaN(v) ? 0 : v; })
    }));
    dgState.groupedCategories = categories;
    dgState.groupedSeries = series;
    const titleInput = document.getElementById('dgTitleInput');
    if (titleInput && (!titleInput.value || titleInput.value === 'Chart Title')) {
      titleInput.value = 'Comparison \u2014 ' + series.map(s => s.name).join(' vs ');
    }
    // Land on whichever grouped view fits the current context: if a grouped view (2D or
    // 3D) is already showing, keep it as-is so this just updates its data in place. Any
    // OTHER chart type — including other 3D types like 3D Bar, which physically cannot
    // render more than one series — must switch to the grouped equivalent instead of
    // being left alone, or the tick here gets silently ignored on screen.
    let nextType;
    if (dgState.type === '3d-grouped-bar' || dgState.type === 'grouped' || dgState.type === 'hstacked' || dgState.type === 'tornado') nextType = dgState.type;
    else if (dgIs3DType(dgState.type)) nextType = '3d-grouped-bar';
    else nextType = 'grouped';
    if (nextType !== dgState.type) dgSetType(nextType); else dgRender();
    const totalNote = excludedTotalRows ? ` (left out ${excludedTotalRows} summary row${excludedTotalRows === 1 ? '' : 's'} like Total/Average)` : '';
    toast(`Comparing ${series.length} columns side-by-side \u2014 ${series.map(s => s.name).join(', ')}` + totalNote, 'success');
    return;
  }

  // Exactly one value column ticked \u2014 original single-series behaviour.
  const valueIdx = valueIdxs[0];
  const signHint2 = [dgUploadParsed.headers[valueIdx], document.getElementById('dgTitleInput')?.value].filter(Boolean).join(' ');
  dgApplyDetectedSign(dgDetectValueSign(rawRows.map(r => r[valueIdx]), signHint2));
  // A date/time label column means this is a time series: parse each row's real date so the
  // points can be put back in chronological order (never trust upload row order for this — a
  // sheet sorted newest-first, or with a few rows out of order, would otherwise plot a chart
  // that zig-zags across time) and re-labelled at whatever granularity actually fits the span
  // of dates present (see dgDetectDateGranularity), instead of printing the raw cell text.
  const labelColIsDate = dgColumnIsDate(labelIdx);
  const rawParsed = [];
  for (let i = 0; i < rawRows.length; i++) {
    const r = rawRows[i];
    const value = dgParseNumericCell(r[valueIdx]);
    if (isNaN(value)) continue;
    let label = String(r[labelIdx] ?? '').trim() || `Item ${rawParsed.length + 1}`;
    let dateVal = null;
    if (labelColIsDate) { dateVal = dgParseDateCell(r[labelIdx]); if (!dateVal) continue; }
    rawParsed.push({ label, value, dateVal });
  }
  if (!rawParsed.length) { toast('Could not find numeric values in that column — try a different Value column', 'error'); return; }

  if (labelColIsDate) {
    rawParsed.sort((a, b) => a.dateVal - b.dateVal);
    const granularity = dgDetectDateGranularity(rawParsed.map(p => p.dateVal));
    rawParsed.forEach(p => { p.label = dgFormatDateLabel(p.dateVal, granularity); });
  }

  // Leave summary rows out of the actual chart — by label ("Total", "Grand Total",
  // "Average"...) first, and if none are spelled that way, fall back to catching a row
  // that's mathematically the sum of every other row (the same signal without needing
  // the word "total" to be present at all).
  const aggIdxs = dgFindAggregateRowIdxs(rawParsed.map(p => p.label), rawParsed.map(p => p.value));
  const excludedRows = rawParsed.filter((_, i) => aggIdxs.has(i));
  const parsed = aggIdxs.size ? rawParsed.filter((_, i) => !aggIdxs.has(i)) : rawParsed;
  if (!parsed.length) { toast('Could not find numeric values in that column — try a different Value column', 'error'); return; }

  let built, infoMsg;
  if (labelColIsDate && parsed.length > MAX_POINTS) {
    // Dense time series (e.g. 1000 daily order rows) can't be one bar per row without every
    // bar shrinking to a hairline — and just keeping the first MAX_POINTS rows in date order
    // would only ever show the EARLIEST slice of the range, with every bar mislabelled at the
    // same "Jan 2025"-style granularity that was only picked for the full span. Aggregate into
    // day/week/month/quarter/year buckets instead (dgBucketDateRows walks up that ladder until
    // the bucket count fits), so the chart covers the whole range, every label is unique, and
    // the bar count stays readable.
    const { granularity: bucketGranularity, rows: bucketed } = dgBucketDateRows(parsed, MAX_POINTS);
    built = bucketed.map((r, i) => ({ label: r.label, value: r.value, color: scheme[i % scheme.length] }));
    const adj = { day: 'daily', week: 'weekly', month: 'monthly', quarter: 'quarterly', year: 'yearly' }[bucketGranularity] || bucketGranularity;
    infoMsg = `Chart generated \u2014 ${parsed.length} rows grouped into ${built.length} ${adj} totals`;
  } else if (topGrouped && parsed.length > MAX_POINTS - 1 && !labelColIsDate) {
    // (Skipped for date-labelled data — collapsing the smallest points into an "Other" bucket
    // would destroy the chronological order that's the whole point of a time series chart.)
    // Instead of silently cutting the data off after MAX_POINTS rows, keep the largest
    // entries (by magnitude) visible on their own and fold everything smaller into one
    // "Other" bucket, so the total the chart represents still adds up to the real total.
    const TOP_N = MAX_POINTS - 1;
    const sorted = [...parsed].sort((a, b) => Math.abs(b.value) - Math.abs(a.value));
    const top = sorted.slice(0, TOP_N);
    const rest = sorted.slice(TOP_N);
    const otherSum = rest.reduce((s, r) => s + r.value, 0);
    built = top.map((r, i) => ({ label: r.label, value: r.value, color: scheme[i % scheme.length] }));
    if (rest.length) built.push({ label: `Other (${rest.length})`, value: otherSum, color: '#8a94a3' });
    infoMsg = `Chart generated \u2014 showing the top ${TOP_N} of ${parsed.length} rows, remaining ${rest.length} grouped into "Other"`;
  } else {
    built = parsed.slice(0, MAX_POINTS).map((r, i) => ({ label: r.label, value: r.value, color: scheme[i % scheme.length] }));
    infoMsg = parsed.length > MAX_POINTS ? `Chart generated \u2014 showing the first ${MAX_POINTS} of ${parsed.length} rows` : null;
  }

  dgState.sameColorMode = false;
  const sameToggle = document.getElementById('dgSameColorToggle');
  if (sameToggle) sameToggle.checked = false;
  dgState.rows = built;
  // A time series reads far better as a line than as a row of disconnected bars — but only
  // switch automatically while the chart is still sitting at the app's plain default ('bar'
  // with nothing plotted yet); once someone has deliberately picked a chart type for THIS
  // dataset, that choice is respected and left alone on every subsequent re-tick/re-upload.
  let dateTypeNote = '';
  if (labelColIsDate && dgState.type === 'bar' && dgActiveMode !== 'map') {
    dgSetType('line');
    dateTypeNote = ' \u2014 switched to a line chart for the time series';
  } else {
    dgRender();
  }
  dgSyncPerCountryGallery(built);
  if (dgMapx.map && document.getElementById('dgMapExplorerModal').classList.contains('open')) dgRefreshMapExplorerMarkers();

  // Map mode — before falling back to the plain "no match" toast, check whether the labels
  // are actually state/province names of ONE recognisable country (e.g. a sheet of Indian
  // states, or US states) and, if so, jump straight to that country's big zoomed-in
  // state-level map instead of leaving a flat, mostly-grey world map.
  //
  // IMPORTANT: we can't gate this on "zero rows matched a country name", because a handful of
  // state/province names are ALSO the name of a sovereign country — most notably "Georgia"
  // (a US state AND a country). A 50-row US-states upload will almost always contain that one
  // row, which used to make the whole sheet look "partially country-matched" and silently
  // block this fallback for every other US state in the sheet. Instead, count both signals and
  // trust whichever one a clear majority of the sheet actually agrees with.
  let stateAutoNote = '';
  if (dgActiveMode === 'map' && dgState.type === 'worldmap') {
    const countryMatchedCount = built.filter(r => dgResolveCountry(r.label)).length;
    const stateGuess = dgDetectStatesCountry(built);
    // A state-name guess only counts as "the real signal" once it's backed by a clear majority
    // of the sheet (dgDetectStatesCountry already enforces that internally) AND it explains more
    // of the sheet than the handful of incidental country-name lookalikes did.
    if (stateGuess && stateGuess.matched > countryMatchedCount) {
      dgAutoShowStateMap(stateGuess.country);
      stateAutoNote = ` \u2014 recognised ${stateGuess.matched} ${stateGuess.country} state${stateGuess.matched === 1 ? '' : 's'}, opened the ${stateGuess.country} map`;
    }
  }

  const totalNote = excludedRows.length
    ? ` \u2014 left out ${excludedRows.length === 1 ? `"${excludedRows[0].label}"` : excludedRows.length + ' summary rows'} (looked like a total/average, not a real data point)`
    : '';
  if (infoMsg) toast(infoMsg + totalNote + stateAutoNote + dateTypeNote, 'info');
  else toast('Chart generated from your uploaded data' + totalNote + stateAutoNote + dateTypeNote, (totalNote || stateAutoNote || dateTypeNote) ? 'info' : 'success');
}

function dgRemoveRow(idx) {
  if (dgState.rows.length <= 1) { toast('Keep at least one data point', 'info'); return; }
  dgState.rows.splice(idx, 1);
  dgRenderRows();
  dgRefreshChart();
}

function dgOnLabelInput(idx, val) { if (dgState.rows[idx]) { dgState.rows[idx].label = val; dgRefreshChart(); } }
function dgOnValueInput(idx, val) {
  if (!dgState.rows[idx]) return;
  // Allow negative numbers (needed for waterfall deltas, profit/loss bars,
  // temperature-style lines, etc). We only reject genuinely non-numeric
  // input; we do NOT clamp negatives to 0, since that was silently
  // corrupting real data (e.g. a "-40000" cost hit becoming 0).
  const parsed = parseFloat(val);
  dgState.rows[idx].value = Number.isFinite(parsed) ? parsed : 0;
  dgRefreshChart();
}
function dgOnColorInput(idx, val) { if (dgState.rows[idx]) { dgState.rows[idx].color = val; dgRefreshChart(); } }

function dgEsc(s) {
  return String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c]));
}

// Converts "#rgb" / "#rrggbb" to an "r, g, b" string for rgba(var(...), alpha).
// Returns null for anything unparseable so callers can fall back safely.
// (Local copy: the Make Forms module has its own private hexToRgbStr, but
// it's scoped inside that module's IIFE and isn't reachable from here — the
// Diagrams engine needs its own.)
function hexToRgbStr(hex) {
  if (!hex) return null;
  const m = String(hex).trim().match(/^#?([a-f\d]{3}|[a-f\d]{6})$/i);
  if (!m) return null;
  let h = m[1];
  if (h.length === 3) h = h.split('').map(c => c + c).join('');
  const r = parseInt(h.slice(0, 2), 16);
  const g = parseInt(h.slice(2, 4), 16);
  const b = parseInt(h.slice(4, 6), 16);
  return `${r}, ${g}, ${b}`;
}

function dgRenderRows() {
  const wrap = document.getElementById('dgRows');
  if (!wrap) return;
  const locked = dgState.sameColorMode;
  wrap.innerHTML = dgState.rows.map((r, i) => `
    <div class="dg-row">
      <input type="color" value="${r.color}" oninput="dgOnColorInput(${i}, this.value)" title="Colour" ${locked ? 'disabled' : ''}>
      <input type="text" value="${dgEsc(r.label)}" oninput="dgOnLabelInput(${i}, this.value)" placeholder="Label">
      <input type="number" value="${r.value}" oninput="dgOnValueInput(${i}, this.value)" placeholder="Value">
      <div class="dg-row-del" onclick="dgRemoveRow(${i})" title="Remove">✕</div>
    </div>
  `).join('');
}

function dgRenderPalette() {
  const wrap = document.getElementById('dgPaletteRow');
  const sel = document.getElementById('dgSchemeSelect');
  if (sel) sel.value = dgState.paletteScheme;
  if (!wrap) return;
  wrap.innerHTML = dgCurrentScheme().map((c, i) => `
    <div class="dg-palette-swatch" style="background:${c}" title="Recolour from here" onclick="dgApplyPaletteFrom(${i})"></div>
  `).join('');
}

function dgRenderCustomSwatches() {
  const wrap = document.getElementById('dgCustomSwatchRow');
  if (!wrap) return;
  if (!dgState.customSwatches.length) {
    wrap.innerHTML = '<span class="dg-empty-swatch-hint">Pick a colour above and hit "Save Colour"</span>';
    return;
  }
  wrap.innerHTML = dgState.customSwatches.map((c, i) => `
    <div class="dg-custom-swatch-wrap">
      <div class="dg-palette-swatch" style="background:${c}" title="Recolour from here" onclick="dgApplyCustomSwatchFrom(${i})"></div>
      <div class="dg-custom-swatch-del" onclick="event.stopPropagation();dgRemoveCustomSwatch(${i})" title="Remove">✕</div>
    </div>
  `).join('');
}

// Grouped Bar, Diverging Stacked Bar, and Tornado charts all share one categories+series
// data model (dgState.groupedCategories / dgState.groupedSeries) instead of the single-series
// dgState.rows list — colour tools below need to know which one to recolour.
function dgUsesGroupedData() {
  return dgState.type === 'grouped' || dgState.type === 'hstacked' || dgState.type === 'tornado';
}

function dgApplyPaletteFrom(startIdx) {
  const scheme = dgCurrentScheme();
  dgState.sameColorMode = false;
  const toggle = document.getElementById('dgSameColorToggle');
  if (toggle) toggle.checked = false;
  if (dgUsesGroupedData()) {
    dgState.groupedSeries.forEach((s, i) => { s.color = scheme[(startIdx + i) % scheme.length]; });
  } else {
    dgState.rows.forEach((r, i) => { r.color = scheme[(startIdx + i) % scheme.length]; });
    dgRenderRows();
  }
  dgRefreshChart();
}

function dgApplyCustomSwatchFrom(startIdx) {
  const arr = dgState.customSwatches;
  if (!arr.length) return;
  dgState.sameColorMode = false;
  const toggle = document.getElementById('dgSameColorToggle');
  if (toggle) toggle.checked = false;
  if (dgUsesGroupedData()) {
    dgState.groupedSeries.forEach((s, i) => { s.color = arr[(startIdx + i) % arr.length]; });
  } else {
    dgState.rows.forEach((r, i) => { r.color = arr[(startIdx + i) % arr.length]; });
    dgRenderRows();
  }
  dgRefreshChart();
}

function dgAddCustomSwatch() {
  const hex = dgState.customColorHex;
  if (dgState.customSwatches.includes(hex)) { toast('Already saved', 'info'); return; }
  dgState.customSwatches.push(hex);
  if (dgState.customSwatches.length > 16) dgState.customSwatches.shift();
  dgRenderCustomSwatches();
  toast('Colour saved to Your Colours', 'success');
}

function dgRemoveCustomSwatch(idx) {
  dgState.customSwatches.splice(idx, 1);
  dgRenderCustomSwatches();
}

function dgToggleSameColor(checked) {
  dgState.sameColorMode = checked;
  if (checked) {
    const master = document.getElementById('dgSameColorInput').value;
    dgState.sameColor = master;
    if (dgUsesGroupedData()) dgState.groupedSeries.forEach(s => { s.color = master; });
    else dgState.rows.forEach(r => { r.color = master; });
  }
  dgRenderRows();
  dgRefreshChart();
}

function dgOnSameColorInput(val) {
  dgState.sameColor = val;
  if (dgState.sameColorMode) {
    if (dgUsesGroupedData()) dgState.groupedSeries.forEach(s => { s.color = val; });
    else dgState.rows.forEach(r => { r.color = val; });
    dgRenderRows();
    dgRefreshChart();
  }
}

function dgApplyWheelToAll() {
  const hex = dgState.customColorHex;
  dgState.sameColorMode = true;
  dgState.sameColor = hex;
  const toggle = document.getElementById('dgSameColorToggle');
  const input = document.getElementById('dgSameColorInput');
  if (toggle) toggle.checked = true;
  if (input) input.value = hex;
  if (dgUsesGroupedData()) dgState.groupedSeries.forEach(s => { s.color = hex; });
  else dgState.rows.forEach(r => { r.color = hex; });
  dgRenderRows();
  dgRefreshChart();
  toast('Applied to every data point', 'success');
}

function dgToggleColoursPanel(e) {
  if (e) e.stopPropagation();
  const body = document.getElementById('dgColoursBody');
  const trigger = document.getElementById('dgColourTriggerBtn');
  if (!body || !trigger) return;
  dgCloseAllDropdowns('dgColoursBody');
  const isOpen = body.classList.toggle('open');
  if (isOpen) {
    const rect = trigger.getBoundingClientRect();
    const panelW = 236;
    let left = rect.left;
    if (left + panelW > window.innerWidth - 8) left = window.innerWidth - panelW - 8;
    body.style.top = (rect.bottom + 6) + 'px';
    body.style.left = left + 'px';
    dgRenderPalette();
    dgRenderCustomSwatches();
  }
}
