function dgApplyTemplate(key) {
  const t = DG_TEMPLATES[key];
  if (!t) return;
  const scheme = dgCurrentScheme();
  dgState.sameColorMode = false;
  const sameToggle = document.getElementById('dgSameColorToggle');
  if (sameToggle) sameToggle.checked = false;
  dgState.rows = t.rows.map((r, i) => ({ label: r.label, value: r.value, color: scheme[i % scheme.length] }));
  dgState.type = t.type;
  dgState.currencySymbol = '$'; // sample templates are illustrative USD figures
  dgState.formatUserSet = true; // the template's own format is deliberate — don't let a later upload's auto-detection silently override it
  const titleInput = document.getElementById('dgTitleInput');
  if (titleInput) titleInput.value = t.title;
  const fmtSelect = document.getElementById('dgFormatSelect');
  if (fmtSelect) fmtSelect.value = t.format || 'plain';
  if (typeof dgSyncFormatUI === 'function') dgSyncFormatUI();
  document.querySelectorAll('#dgTypeGrid .dg-type-tile').forEach(el => {
    const active = el.dataset.type === t.type;
    el.classList.toggle('active', active);
    if (active) {
      const icon = document.getElementById('dgTypeIcon');
      const label = document.getElementById('dgTypeLabel');
      const svg = el.querySelector('svg');
      if (icon && svg) icon.innerHTML = svg.outerHTML;
      if (label) label.textContent = el.textContent.trim();
    }
  });
  const templatesDD = document.getElementById('dgTemplatesDropdown');
  if (templatesDD) templatesDD.classList.remove('open');
  dgRenderRows();
  dgRender();
  toast('Template loaded — tweak the numbers to fit your data', 'success');
}

function dgPickFixedColor(hex) {
  dgState.customColorHex = hex;
  const input = document.getElementById('dgCustomColorInput');
  const hexLabel = document.getElementById('dgCustomColorHex');
  if (input) input.value = hex;
  if (hexLabel) hexLabel.textContent = hex.toUpperCase();
}

// ── Custom colour (plain native colour picker — no bespoke wheel to maintain) ──
function dgOnCustomColorInput(val) {
  dgState.customColorHex = val;
  const hexLabel = document.getElementById('dgCustomColorHex');
  if (hexLabel) hexLabel.textContent = val.toUpperCase();
}

function dgGetOpts() {
  const title = (document.getElementById('dgTitleInput') || {}).value || '';
  const xAxisTitle = (document.getElementById('dgXAxisTitleInput') || {}).value || '';
  const yAxisTitle = (document.getElementById('dgYAxisTitleInput') || {}).value || '';
  let numberFormat = (document.getElementById('dgFormatSelect') || {}).value || 'plain';
  // Smart symbol detection, generalized to run on EVERY render — not just right after a
  // file upload. dgApplyDetectedSign (used by the upload path) reads the raw data cells;
  // that signal doesn't exist for manually-typed rows (the value inputs are type="number",
  // so a person can't type "$" or "%" into them). But the chart/axis TITLE is free text
  // either way, so "Revenue ($)" or "Growth %" typed straight into the title fields is
  // still a reliable hint. Re-checking it on every render means manual-entry charts get
  // the right currency/percent symbol on their bars and axis automatically, the same way
  // uploaded ones already do — without the person having to remember the Number Format
  // dropdown. Only kicks in when the person hasn't deliberately chosen a format themselves
  // (dgState.formatUserSet), so it never fights a real manual choice.
  if (!(typeof dgState !== 'undefined' && dgState.formatUserSet)) {
    const hint = [title, yAxisTitle, xAxisTitle].filter(Boolean).join(' ');
    const detected = (typeof dgDetectValueSign === 'function') ? dgDetectValueSign([], hint) : null;
    if (detected) {
      numberFormat = detected.format;
      if (detected.format === 'currency' && detected.symbol && typeof dgState !== 'undefined') dgState.currencySymbol = detected.symbol;
      const select = document.getElementById('dgFormatSelect');
      if (select) select.value = numberFormat;
    }
  }
  return {
    title,
    xAxisTitle,
    yAxisTitle,
    legend: !!(document.getElementById('dgLegendToggle') || {}).checked,
    values: !!(document.getElementById('dgValuesToggle') || {}).checked,
    numberFormat,
    trendline: !!(document.getElementById('dgTrendlineToggle') || {}).checked,
    growthMode: !!(document.getElementById('dgGrowthToggle') || {}).checked,
    hologram: dgHologramOn(),
    barRadius: dgState.barRadius != null ? dgState.barRadius : 8
  };
}

// Fits text into a pixel width using the canvas's own font metrics (rather than a fixed
// character count), so truncation is exact regardless of font, zoom, or how wide the
// available slot actually is — the root cause of labels overlapping neighbouring ones.
function dgFitLabel(ctx, text, maxWidth) {
  text = String(text == null ? '' : text);
  if (maxWidth <= 0) return '';
  if (ctx.measureText(text).width <= maxWidth) return text;
  let lo = 0, hi = text.length;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    const candidate = text.slice(0, mid).trimEnd() + '\u2026';
    if (ctx.measureText(candidate).width <= maxWidth) lo = mid; else hi = mid - 1;
  }
  return lo <= 0 ? '\u2026' : text.slice(0, lo).trimEnd() + '\u2026';
}

// Draws one x-axis category label under a bar/point. When there are many items or the
// labels are long, it rotates them on a diagonal instead of cramming them in horizontally —
// the same trick spreadsheet chart tools use to keep dense axes readable instead of letting
// adjacent labels run into each other.
function dgDrawAxisLabel(ctx, text, x, y, availW, rotate) {
  ctx.save();
  ctx.fillStyle = '#5b6474';
  ctx.font = '11.5px Inter, sans-serif';
  if (rotate) {
    // A rotated label's horizontal footprint (the direction adjacent labels can collide in)
    // is roughly its pixel length × cos(45°) ≈ length × 0.707. A fixed 90px fitted-text
    // allowance here regardless of how narrow each bar's actual slot (availW) is meant
    // adjacent diagonal labels overlapped each other once there were more than ~12 bars —
    // so derive the max text length from the real slot width instead: length = availW / 0.707.
    const maxDiagLen = Math.max(24, availW / 0.7071);
    ctx.translate(x, y + 4);
    ctx.rotate(-Math.PI / 4);
    ctx.textAlign = 'right';
    ctx.textBaseline = 'middle';
    ctx.fillText(dgFitLabel(ctx, text, Math.min(90, maxDiagLen)), 0, 0);
  } else {
    ctx.textAlign = 'center';
    ctx.fillText(dgFitLabel(ctx, text, availW), x, y);
  }
  ctx.restore();
}

// Splits legend entries across as many rows as needed to fit the canvas width, instead of
// one long centred row that quietly runs off both edges once there are more than a handful
// of categories. Capped to 3 rows — beyond that, a "+N more" pill takes the place of the
// remaining entries so a large dataset (12+ categories) reads as a tidy legend block
// instead of sprawling into an ever-taller wall of swatches.
function dgLayoutLegend(ctx, rows, opts, maxW) {
  ctx.font = '12px Inter, sans-serif';
  const MAX_ROWS = 3;
  const items = rows.map(r => {
    const valStr = ' (' + dgFormatNumber(r.value, opts.numberFormat) + ')';
    const w = ctx.measureText(r.label).width + (opts.values ? ctx.measureText(valStr).width : 0) + 30;
    return { r, w, valStr };
  });

  const lines = [];
  let cur = [], curW = 0, used = 0;
  for (let i = 0; i < items.length; i++) {
    const it = items[i];
    if (cur.length && curW + it.w > maxW) {
      lines.push(cur);
      if (lines.length === MAX_ROWS) { cur = null; break; }
      cur = []; curW = 0;
    }
    cur.push(it); curW += it.w; used++;
  }
  if (cur && cur.length) lines.push(cur);

  if (used < items.length) {
    const remaining = items.length - used;
    const moreText = `+${remaining} more`;
    const more = { more: true, moreText, w: ctx.measureText(moreText).width + 18 };
    const lastLine = lines[lines.length - 1];
    let lastW = lastLine.reduce((s, x) => s + x.w, 0);
    while (lastW + more.w > maxW && lastLine.length > 1) {
      lastW -= lastLine.pop().w;
    }
    lastLine.push(more);
  }

  lines.blockW = Math.max(0, ...lines.map(l => l.reduce((s, it) => s + it.w, 0)));
  return lines;
}

// exportCanvas/exportScale: optional — when omitted, this renders straight onto the
// live #dgCanvas at 1x exactly as before (every existing call site passes no args).
// When dgDownloadPNG4K() wants a crisp high-resolution copy (built for the World Map's
// choropleth detail, but works for any chart type on this canvas), it passes its own
// offscreen <canvas> plus a supersampling factor here instead — the live canvas, the
// on-screen zoom/pan/text-overlay state, and every other export path are untouched.
function dgDrawChart(exportCanvas, exportScale) {
  const canvas = exportCanvas || document.getElementById('dgCanvas');
  if (!canvas) return;
  const scale = exportScale || 1;
  const isExport = !!exportCanvas;
  const ctx = canvas.getContext('2d');
  const opts = dgGetOpts();
  let rows = dgState.rows;
  const type = dgState.type;
  const isGrouped = type === 'grouped' || type === 'hstacked' || type === 'tornado';
  const gcats = dgState.groupedCategories || [];
  const gseries = dgState.groupedSeries || [];
  // Growth % mode: single-series bar/line/area charts get replotted as percentage change
  // from the first data point instead of raw values — the clearest way to answer "how much
  // did this grow", and the only sane read when comparing series on very different scales
  // (e.g. revenue vs. headcount) that raw numbers can't be directly compared on. Values,
  // axis ticks, and tooltips all switch to the 'percent' number format automatically since
  // they're formatted through opts.numberFormat.
  const growthEligible = !isGrouped && ['bar', 'line', 'area'].includes(type);
  if (opts.growthMode && growthEligible && rows.length > 1 && rows[0] && rows[0].value !== 0) {
    const base = rows[0].value;
    rows = rows.map(r => ({ ...r, value: ((r.value - base) / Math.abs(base)) * 100 }));
    opts.numberFormat = 'percent';
    if (!opts.yAxisTitle) opts.yAxisTitle = `% change vs. ${rows[0].label || 'first value'}`;
  } else if (opts.growthMode && growthEligible && rows.length > 1 && rows[0] && rows[0].value === 0 && typeof toast === 'function') {
    // Asked for growth mode but it can't be computed (zero baseline) — fall back to plain
    // values rather than silently ignoring the toggle, and say why.
    toast('Growth % needs a non-zero first value — showing raw values instead', 'info');
  }
  // Grouped charts always show their series legend — that's the only thing that tells
  // "Profit 2025" bars apart from "Profit 2026" bars — regardless of the global legend toggle.
  // Diverging stacked and tornado charts are built from the same multi-series data and need
  // the same series legend for the same reason.
  if (isGrouped) opts.legend = true;

  // World Map: resolve row labels against the country dataset and colour them up front so
  // the same legend pipeline everything else uses (dgLayoutLegend/dgDrawLegend, keyed off
  // row.color) picks up the choropleth colours for free — matched countries, biggest first.
  let dgWorldMapMatch = null;
  if (type === 'worldmap') {
    dgWorldMapMatch = dgAssignWorldMapColors(rows);
    rows = dgWorldMapMatch.rows;
    opts.legend = true;
  }

  // Per-country zoom (gallery card loaded into the live editor): resolve the single
  // row's label to a canonical country up front, the same way World Map does above.
  // No legend needed here — the country name is already the chart title, and its
  // value is drawn directly under the shape by dgDrawCountryZoom.
  let dgCountryZoomTarget = null;
  if (type === 'countryzoom') {
    const r0 = rows[0];
    dgCountryZoomTarget = { country: r0 ? dgResolveCountry(r0.label) : null, value: r0 ? r0.value : null };
    opts.legend = false;
  }

  // The canvas height flexes (width stays fixed) to fit whatever legend rows / rotated
  // axis labels the current data needs, capped at MAX_H — so a 12-category legend gets
  // real room to sit under the chart instead of being squeezed and clipped at a fixed
  // 460px, while a simple 3-bar chart still renders at the compact default size.
  const BASE_W = 1200, BASE_H = 675, MAX_H = 900;
  let W = BASE_W, H = BASE_H;
  let legendLines = [], legendH = 0;
  const axisChartTypes = ['bar', 'stacked', 'waterfall', 'pareto', 'line', 'area', 'grouped'];
  const hasAxes = axisChartTypes.includes(type);
  // Extra chrome reserved only when this is an axis-based chart AND the user has actually
  // typed an axis title — a bar chart with no title set keeps its original compact layout.
  const xTitleExtra = hasAxes && opts.xAxisTitle ? 24 : 0;
  const yTitleExtra = hasAxes && opts.yAxisTitle ? 20 : 0;

  const dataLen = isGrouped ? gcats.length : rows.length;
  if (dataLen) {
    const maxLabelLen = isGrouped
      ? Math.max(0, ...gcats.map(c => String(c || '').length))
      : Math.max(0, ...rows.map(r => String(r.label || '').length));
    opts.rotateLabels = axisChartTypes.includes(type) && (dataLen > 8 || maxLabelLen > 10);

    ctx.font = '12px Inter, sans-serif';
    // Grouped charts need a legend of SERIES (Profit 2025 / Profit 2026), not one entry per
    // category bar — so it's laid out from pseudo-rows built off dgState.groupedSeries instead
    // of the category rows dgLayoutLegend normally expects.
    const legendSourceRows = isGrouped
      ? gseries.map(s => ({ label: s.name, value: 0, color: s.color }))
      : rows;
    const legendOpts = isGrouped ? { ...opts, values: false } : opts;
    legendLines = opts.legend ? dgLayoutLegend(ctx, legendSourceRows, legendOpts, W - 40) : [];
    legendH = legendLines.length ? legendLines.length * 24 + 16 : 0;

    const topSpace = opts.title ? 78 : 30;
    const axisSpace = (opts.rotateLabels ? 84 : 60) + xTitleExtra;
    const minChartH = 260;
    H = Math.max(BASE_H, Math.min(MAX_H, topSpace + minChartH + axisSpace + legendH));
  }

  const physW = Math.round(W * scale), physH = Math.round(H * scale);
  if (canvas.width !== physW) canvas.width = physW;
  if (canvas.height !== physH) canvas.height = physH;
  // Supersample: everything below still draws in the same logical W×H coordinate
  // space as always (fonts, line widths, layout math all untouched) — this transform
  // is what turns those same draw calls into `scale`x the physical pixels, the same
  // technique already used for the Mermaid diagram export (dgFlowRasterizeAndCache).
  ctx.setTransform(scale, 0, 0, scale, 0, 0);
  if (!isExport) {
    const overlay = document.getElementById('dgTextOverlay');
    if (overlay) { overlay.style.width = W + 'px'; overlay.style.height = H + 'px'; }
  }

  ctx.clearRect(0, 0, W, H);
  // Card background: soft shadow + rounded corners so the chart reads as a
  // self-contained report tile rather than a bare rectangle. This is drawn
  // straight onto the canvas (not layered on with CSS), so it bakes into
  // every exported image too — PNG, JPEG, PDF, and the DOCX embed.
  ctx.save();
  ctx.shadowColor = 'rgba(16,24,40,0.12)';
  ctx.shadowBlur = 16;
  ctx.shadowOffsetY = 3;
  dgRoundRectPath(ctx, 1, 1, W - 2, H - 2, 14);
  ctx.fillStyle = '#ffffff';
  ctx.fill();
  ctx.restore();
  const dgDrawCardBorder = () => {
    dgRoundRectPath(ctx, 1, 1, W - 2, H - 2, 14);
    ctx.strokeStyle = '#e2e6ec';
    ctx.lineWidth = 1.5;
    ctx.stroke();
  };

  let top = 30;
  if (opts.title) {
    ctx.fillStyle = '#101820';
    ctx.font = '700 24px Inter, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(dgFitLabel(ctx, opts.title, W - 40), W / 2, 42);
    top = 78;
  }

  if (!dataLen) {
    ctx.fillStyle = '#b8c0cc';
    ctx.font = '600 14px Inter, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('No data yet', W / 2, H / 2 - 10);
    ctx.font = '400 12px Inter, sans-serif';
    ctx.fillText(isGrouped ? 'Upload a file with 2+ comparable numeric columns to build a grouped chart' : 'Add a data point or upload a file to build a chart', W / 2, H / 2 + 12);
    dgDrawCardBorder();
    if (!isExport) dgRenderInsightsStrip();
    return;
  }

  const baseAxisSpace = opts.rotateLabels ? 84 : 60;
  const bottom = H - baseAxisSpace - xTitleExtra - legendH;
  const rightMargin = type === 'pareto' ? 74 : 40;
  // Left margin sizes itself to the widest y-axis tick label instead of a fixed
  // 70px — large formatted numbers (e.g. "$2,703,650") were getting clipped
  // against the left edge of the canvas at the old fixed width. We estimate the
  // tick values the same way dgYScale/dgDrawAxisGrid will, measure each
  // formatted label at the actual axis font, and pad the margin to fit the
  // widest one (plus room for the tick mark itself).
  let dynLeftMargin = 70;
  if (hasAxes && type !== 'funnel') {
    const vals = isGrouped ? gseries.flatMap(s => s.values) : rows.map(r => r.value);
    const probeScale = dgYScale(vals, { y: 0, h: 100 });
    ctx.font = '11px Inter, sans-serif';
    let maxLabelW = 0;
    for (let i = 0; i <= probeScale.tickCount; i++) {
      const v = probeScale.min + probeScale.step * i;
      const w = ctx.measureText(dgFormatNumber(v, opts.numberFormat)).width;
      if (w > maxLabelW) maxLabelW = w;
    }
    dynLeftMargin = Math.max(70, Math.ceil(maxLabelW) + 11 /* tick mark */ + 20 /* padding */);
  } else if (type === 'hstacked') {
    // Diverging stacked bars carry their category labels (month names, department names,
    // etc.) in the left margin instead of along a bottom axis, so the margin needs to fit
    // the widest ACTUAL label text, not a fixed 70px guess that clips longer names.
    ctx.font = '600 12px Inter, sans-serif';
    const maxLabelW = Math.max(0, ...gcats.map(c => ctx.measureText(String(c || '')).width));
    dynLeftMargin = Math.max(70, Math.ceil(maxLabelW) + 24 /* padding */);
  }
  const leftMargin = dynLeftMargin + yTitleExtra;
  const chartArea = { x: leftMargin, y: top, w: W - leftMargin - rightMargin, h: bottom - top };

  if (type === 'grouped') {
    dgDrawGroupedBars(ctx, gcats, gseries, chartArea, opts);
  } else if (type === 'hstacked') {
    dgDrawDivergingStackedBars(ctx, gcats, gseries, chartArea, opts);
  } else if (type === 'tornado') {
    dgDrawTornadoBars(ctx, gcats, gseries, chartArea, opts);
  } else if (type === 'bar' || type === 'stacked') {
    dgDrawBars(ctx, rows, chartArea, opts, type === 'stacked');
  } else if (type === 'line' || type === 'area') {
    dgDrawLine(ctx, rows, chartArea, opts, type === 'area');
  } else if (type === 'pie' || type === 'donut') {
    dgDrawPie(ctx, rows, { x: W / 2, y: top + chartArea.h / 2, r: Math.min(chartArea.w, chartArea.h) / 2 - 10 }, opts, type === 'donut');
  } else if (type === 'waterfall') {
    dgDrawWaterfall(ctx, rows, chartArea, opts);
  } else if (type === 'pareto') {
    dgDrawPareto(ctx, rows, chartArea, opts);
  } else if (type === 'funnel') {
    dgDrawFunnel(ctx, rows, chartArea, opts);
  } else if (type === 'worldmap') {
    dgDrawWorldMap(ctx, dgWorldMapMatch, chartArea, opts);
  } else if (type === 'countryzoom') {
    dgDrawCountryZoom(ctx, dgCountryZoomTarget, chartArea, opts);
  }

  // Editable axis titles — enterprise-chart convention (e.g. "Quarter" / "Revenue ($)")
  // sitting outside the plot area, X centred beneath the category labels and Y rotated
  // vertically beside the value labels. Only drawn for chart types that actually have axes.
  if (hasAxes) {
    if (opts.xAxisTitle) {
      ctx.save();
      ctx.fillStyle = '#2b3341';
      ctx.font = '700 12px Inter, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(dgFitLabel(ctx, opts.xAxisTitle, chartArea.w), chartArea.x + chartArea.w / 2, bottom + baseAxisSpace + xTitleExtra - 8);
      ctx.restore();
    }
    if (opts.yAxisTitle) {
      ctx.save();
      ctx.translate(16, chartArea.y + chartArea.h / 2);
      ctx.rotate(-Math.PI / 2);
      ctx.fillStyle = '#2b3341';
      ctx.font = '700 12px Inter, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(dgFitLabel(ctx, opts.yAxisTitle, chartArea.h), 0, 0);
      ctx.restore();
    }
  }

  if (legendLines.length) dgDrawLegend(ctx, legendLines, W, H - legendH + 10, opts);
  dgDrawCardBorder();
  if (!isExport) dgRenderInsightsStrip();
}

// Shared value→pixel scale for bar/line/trendline charts. Unlike a naive
// "0 to max" scale, this always includes 0 in the range and pads both ends,
// so negative values (a loss, a decline, a below-zero temperature) sit
// correctly on their own side of the zero line instead of distorting or
// clipping off the chart. This is what makes mixed positive/negative data
// (profit & loss, deltas, YoY change) render accurately instead of just
// "mostly right".
// Rounds a raw span to the nearest "nice" number — 1, 2, or 5 times a power of
// ten (Heckbert's nice-numbers method, the standard axis-tick algorithm behind
// D3, Chart.js, and every serious BI tool). Used so gridlines land on values
// like 5,000 / 10,000 / 15,000 instead of the ugly quantities (4,287.50,
// 8,575, 12,862.50 ...) that fall out of just splitting min→max into 4 even
// fractions.
function dgNiceNum(range, round) {
  if (!range || range <= 0 || !isFinite(range)) return 1;
  const exponent = Math.floor(Math.log10(range));
  const fraction = range / Math.pow(10, exponent);
  let niceFraction;
  if (round) {
    if (fraction < 1.5) niceFraction = 1;
    else if (fraction < 3) niceFraction = 2;
    else if (fraction < 7) niceFraction = 5;
    else niceFraction = 10;
  } else {
    if (fraction <= 1) niceFraction = 1;
    else if (fraction <= 2) niceFraction = 2;
    else if (fraction <= 5) niceFraction = 5;
    else niceFraction = 10;
  }
  return niceFraction * Math.pow(10, exponent);
}

function dgYScale(vals, area, labelPadPx) {
  const dataMax = Math.max(0, ...vals);
  const dataMin = Math.min(0, ...vals);
  const rawSpan = (dataMax - dataMin) || (Math.abs(dataMax) || 1);
  const niceSpan = dgNiceNum(rawSpan * 1.15, false);
  // A fixed 4 gridlines regardless of chart height or how the data is spread meant a short
  // chart and a tall one got identically coarse resolution, and a dataset with a couple of
  // outliers pulling the max way up (most values under 30K, one or two near 130K) still only
  // got 50,000-wide steps — every "normal" bar ends up bunched in the bottom sliver with no
  // gridline anywhere near it. Scale the tick count to the actual plot height instead — about
  // one gridline every ~65px — so there's a real, height-appropriate reference line more of
  // the data actually sits near, clamped so a short chart doesn't go sparse (min 3) and a tall
  // one doesn't get cluttered (max 7).
  const TICK_COUNT = Math.max(3, Math.min(8, Math.round(((area && area.h) || 260) / 50)));
  const step = dgNiceNum(niceSpan / TICK_COUNT, true) || 1;
  const min = dataMin < 0 ? Math.floor(dataMin / step) * step : 0;
  let max = Math.ceil(dataMax / step) * step;
  // Guarantee at least a sliver of headroom above the tallest bar/point so it
  // never touches the top edge of the chart.
  if (max - dataMax < step * 0.05) max += step;
  // When a value label is drawn above the tallest bar/point (opts.values), that nominal
  // "sliver" isn't necessarily enough — it's sized as a fraction of one nice-number step,
  // which can shrink to just a few pixels regardless of how tall the label text actually
  // is. That's what let the top value label get clipped against the chart's title/top
  // edge. So when the caller tells us how many pixels the label needs (labelPadPx), keep
  // extending the ceiling by whole steps until there's real, measured room for it.
  if (labelPadPx) {
    let guard = 0;
    while (guard < 8) {
      const headroomRange = (max - min) || step;
      const headroomPx = ((max - dataMax) / headroomRange) * area.h;
      if (headroomPx >= labelPadPx) break;
      max += step;
      guard++;
    }
  }
  const range = (max - min) || step;
  const tickCount = Math.max(1, Math.round(range / step));
  return { max, min, range, step, tickCount, toY: v => area.y + area.h - ((v - min) / range) * area.h };
}

function dgDrawAxisGrid(ctx, area, scale, opts) {
  ctx.font = '11px Inter, sans-serif';
  ctx.fillStyle = '#5b6474';
  ctx.textAlign = 'right';
  for (let i = 0; i <= scale.tickCount; i++) {
    const v = scale.min + scale.step * i;
    const y = scale.toY(v);
    // Faint horizontal gridline across the plot area
    ctx.strokeStyle = '#eef1f5';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(area.x, y);
    ctx.lineTo(area.x + area.w, y);
    ctx.stroke();
    // Short tick mark on the y-axis itself, the enterprise-BI-tool convention
    // (Tableau/Power BI style) that makes each gridline value read as a
    // deliberate scale marker rather than just a stray line.
    ctx.strokeStyle = '#9aa4b2';
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(area.x - 5, y);
    ctx.lineTo(area.x, y);
    ctx.stroke();
    ctx.fillText(dgFormatNumber(v, opts.numberFormat), area.x - 11, y + 4);
  }
  // Zero baseline gets its own solid line whenever the data actually
  // crosses zero, so positive vs negative is visually unambiguous.
  if (scale.min < 0 && scale.max > 0) {
    const zeroY = scale.toY(0);
    ctx.strokeStyle = '#c7cfd8';
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(area.x, zeroY);
    ctx.lineTo(area.x + area.w, zeroY);
    ctx.stroke();
  }
  dgDrawAxisLines(ctx, area, scale);
}

// Solid y-axis (left edge) and x-axis (zero line, or bottom edge when the
// data never dips below zero) so the chart reads as a proper plot rather
// than floating bars/lines against just faint gridlines. Colours are a
// darker, more deliberate slate than the gridlines so the axis frame itself
// reads as structure, the way enterprise dashboard tools draw their spines.
function dgDrawAxisLines(ctx, area, scale) {
  const xAxisY = (scale.min < 0 && scale.max > 0) ? scale.toY(0) : area.y + area.h;
  ctx.save();
  ctx.strokeStyle = '#2b3341';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(area.x, area.y);
  ctx.lineTo(area.x, area.y + area.h);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(area.x, xAxisY);
  ctx.lineTo(area.x + area.w, xAxisY);
  ctx.stroke();
  ctx.restore();
}

function dgDrawBars(ctx, rows, area, opts, stacked) {
  const vals = rows.map(r => r.value);
  // 12px bold value labels sit 8px above the bar top — ~26px of headroom keeps the
  // tallest bar's label clear of the chart's top edge/title instead of getting clipped.
  const scale = dgYScale(vals, area, (!stacked && opts.values) ? 26 : 0);
  dgDrawAxisGrid(ctx, area, scale, opts);

  if (stacked) {
    // Stacked bars represent parts of a whole and are only meaningful for
    // non-negative parts; a negative segment can't be stacked as a
    // proportion, so we use the magnitude for the split but flag it below.
    const total = rows.reduce((s, r) => s + Math.abs(r.value), 0) || 1;
    const barW = Math.min(140, area.w * 0.35);
    const bx = area.x + area.w / 2 - barW / 2;
    const stackRad = Math.min(opts.barRadius != null ? opts.barRadius : 8, barW / 2);
    let cursorY = area.y + area.h;
    rows.forEach((r, i) => {
      const segH = (Math.abs(r.value) / total) * area.h * dgAK(i, rows.length);
      cursorY -= segH;
      ctx.fillStyle = r.color;
      // Only round the outer corners of the stack (top segment's top edge,
      // bottom segment's bottom edge) so the curve reads as one pill-shaped
      // bar rather than every internal seam getting rounded too.
      const segRad = Math.min(stackRad, segH / 2);
      dgRoundRectStackPath(ctx, bx, cursorY, barW, segH, segRad, i === rows.length - 1, i === 0);
      ctx.fill();
      if (opts.values && segH > 16) {
        ctx.fillStyle = '#ffffff';
        ctx.font = '700 11px Inter, sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(Math.round((Math.abs(r.value) / total) * 100) + '%', bx + barW / 2, cursorY + segH / 2 + 4);
      }
    });
    return;
  }

  const n = rows.length;
  // A fixed 24px gap works fine for a handful of bars, but eats almost the entire chart width
  // once there are 30-40+ categories (24px × 41 gaps ≈ 980px of a ~1090px-wide chart area),
  // leaving each bar a hairline sliver. Scale the gap down as n grows, with a small floor so
  // bars stay visually separated, and floor the bar width itself so it never goes to zero.
  const gap = n <= 8 ? 24 : Math.max(2, Math.min(24, (area.w / n) * 0.3));
  const barW = Math.max(2, Math.min(70, (area.w - gap * (n + 1)) / n));
  const usedW = barW * n + gap * (n + 1);
  const startX = area.x + (area.w - usedW) / 2 + gap;
  const zeroY = scale.toY(0);

  rows.forEach((r, i) => {
    const x = startX + i * (barW + gap);
    const valY = scale.toY(r.value);
    const bk = dgAK(i, n);   // motion: 1 when still
    const h = Math.max(1, Math.abs(zeroY - valY) * bk);
    const y = valY <= zeroY ? zeroY - h : zeroY;
    ctx.fillStyle = r.color;
    const rad = Math.min(opts.barRadius != null ? opts.barRadius : 8, barW / 2, h / 2);
    dgRoundRectPath(ctx, x, y, barW, h, rad);
    ctx.fill();

    // Small tick mark on the x-axis under each category, matching the y-axis
    // ticks so both axes read as one consistent, deliberately-scaled frame.
    ctx.strokeStyle = '#9aa4b2';
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(x + barW / 2, area.y + area.h);
    ctx.lineTo(x + barW / 2, area.y + area.h + 5);
    ctx.stroke();

    ctx.fillStyle = '#5b6474';
    ctx.font = '11.5px Inter, sans-serif';
    ctx.textAlign = 'center';
    dgDrawAxisLabel(ctx, r.label, x + barW / 2, area.y + area.h + 20, barW + gap - 6, opts.rotateLabels);

    // A bar under ~18px wide can't fit even a short formatted number without truncating to
    // an unhelpful "$..." — at that width it's better to leave the label off (the Insights
    // panel / hover tooltip still carries the exact value) than to render noise on every bar.
    if (opts.values && barW >= 18) {
      ctx.globalAlpha = Math.min(1, bk * bk);
      ctx.fillStyle = '#101820';
      ctx.font = '700 12px Inter, sans-serif';
      // Positive bars get their label above the bar, negative bars below,
      // so the number never overlaps the bar or the axis.
      const labelY = r.value >= 0 ? y - 8 : y + h + 14;
      ctx.textAlign = 'center';
      ctx.fillText(dgFormatValueLabelFit(ctx, r.value, opts, barW + gap - 4), x + barW / 2, labelY);
      ctx.globalAlpha = 1;
    }
  });

  if (opts.trendline && rows.length > 1) {
    const xs = rows.map((r, i) => startX + i * (barW + gap) + barW / 2);
    dgDrawTrendline(ctx, rows, area, xs, scale);
  }
}

// Clustered/grouped bar chart: one shared category axis (e.g. departments), with 2+ named,
// coloured series (e.g. "Profit 2025" vs "Profit 2026") drawn as adjacent bars per category —
// the same visual comparison as putting two colours side-by-side for every row of a table,
// instead of one bar chart per metric or one flattened single-series chart.
function dgDrawGroupedBars(ctx, categories, series, area, opts) {
  if (!categories.length || !series.length) return;
  const allVals = series.reduce((acc, s) => acc.concat(s.values), []);
  // Smaller 10.5px value labels here, but same idea: guarantee pixel headroom above the
  // tallest cluster bar so its label doesn't clip the top edge.
  const scale = dgYScale(allVals, area, opts.values ? 22 : 0);
  dgDrawAxisGrid(ctx, area, scale, opts);
  const zeroY = scale.toY(0);

  const n = categories.length;
  const s = series.length;
  // Same fix as the other bar charts: a fixed 24px gap between clusters swallows the width
  // once there are 20-30 categories, squeezing every cluster (and the bars inside it) thin.
  const gap = n <= 8 ? 24 : Math.max(2, Math.min(24, (area.w / n) * 0.3));
  const barGap = Math.max(2, 6 - s); // tighter inner gap as more series get packed in
  const clusterW = Math.min(s * 44, (area.w - gap * (n + 1)) / n);
  const barW = Math.max(3, (clusterW - barGap * (s - 1)) / s);
  const usedW = clusterW * n + gap * (n + 1);
  const startX = area.x + Math.max(0, (area.w - usedW) / 2) + gap;

  categories.forEach((cat, ci) => {
    const clusterX = startX + ci * (clusterW + gap);
    series.forEach((sr, si) => {
      const v = sr.values[ci] || 0;
      const x = clusterX + si * (barW + barGap);
      const valY = scale.toY(v);
      const gk = dgAK(ci * series.length + si, categories.length * series.length);
      const h = Math.max(1, Math.abs(zeroY - valY) * gk);
      const y = valY <= zeroY ? zeroY - h : zeroY;
      ctx.fillStyle = sr.color;
      const rad = Math.min(opts.barRadius != null ? opts.barRadius : 8, barW / 2, h / 2);
      dgRoundRectPath(ctx, x, y, barW, h, rad);
      ctx.fill();
      if (opts.values && barW > 16) {
        ctx.globalAlpha = Math.min(1, gk * gk);
        ctx.fillStyle = '#101820';
        ctx.font = '700 10.5px Inter, sans-serif';
        ctx.textAlign = 'center';
        const labelY = v >= 0 ? y - 6 : y + h + 13;
        ctx.fillText(dgFormatValueLabelFit(ctx, v, opts, barW + barGap + 4), x + barW / 2, labelY);
        ctx.globalAlpha = 1;
      }
    });

    // One tick + one category label centred under the whole cluster (not per-bar), so
    // "Sales" reads once under its Profit-2025/Profit-2026 pair, not twice.
    const centerX = clusterX + clusterW / 2;
    ctx.strokeStyle = '#9aa4b2';
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(centerX, area.y + area.h);
    ctx.lineTo(centerX, area.y + area.h + 5);
    ctx.stroke();
    ctx.fillStyle = '#5b6474';
    ctx.font = '11.5px Inter, sans-serif';
    ctx.textAlign = 'center';
    dgDrawAxisLabel(ctx, cat, centerX, area.y + area.h + 20, clusterW + gap - 6, opts.rotateLabels);
  });
}

// Value→pixel scale for the horizontal-axis comparison charts below — the same idea as
// dgYScale, just mapped along x instead of y (and given an explicit min/max instead of
// deriving them from a plain array, since both charts below need to pad differently).
function dgXScaleFromRange(min, max, area) {
  const range = (max - min) || 1;
  return { min, max, range, toX: v => area.x + ((v - min) / range) * area.w };
}

// Diverging (horizontal) stacked bar chart: one bar per category, built from 2+ series —
// series with a positive value for that category stack rightward from zero in series order,
// series with a negative value (e.g. a "Wastage"/"Returns" series) stack leftward from zero.
// This is the horizontal-bar equivalent of dgDrawBars(stacked), except a stack can straddle
// zero instead of only ever building upward from it, so a loss/waste series reads as visually
// distinct from the positive segments rather than being forced into the same one-directional
// stack (or silently flipped positive, which would misrepresent it).
function dgDrawDivergingStackedBars(ctx, categories, series, area, opts) {
  if (!categories.length || !series.length) return;
  const n = categories.length;
  let maxPos = 0, maxNeg = 0;
  categories.forEach((cat, i) => {
    let pos = 0, neg = 0;
    series.forEach(s => { const v = s.values[i] || 0; if (v >= 0) pos += v; else neg += Math.abs(v); });
    if (pos > maxPos) maxPos = pos;
    if (neg > maxNeg) maxNeg = neg;
  });
  const min = maxNeg > 0 ? -maxNeg * 1.2 : 0;
  const max = maxPos > 0 ? maxPos * 1.2 : 1;
  const scale = dgXScaleFromRange(min, max, area);
  const zeroX = scale.toX(0);

  // Vertical gridlines + a value axis along the bottom — the horizontal-chart mirror of
  // dgDrawAxisGrid's horizontal gridlines/left axis.
  ctx.font = '11px Inter, sans-serif';
  ctx.textAlign = 'center';
  for (let i = 0; i <= 4; i++) {
    const v = scale.min + scale.range * i / 4;
    const x = scale.toX(v);
    ctx.strokeStyle = '#eef1f5';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x, area.y);
    ctx.lineTo(x, area.y + area.h);
    ctx.stroke();
    ctx.strokeStyle = '#9aa4b2';
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(x, area.y + area.h);
    ctx.lineTo(x, area.y + area.h + 5);
    ctx.stroke();
    ctx.fillStyle = '#5b6474';
    ctx.fillText(dgFormatNumber(v, opts.numberFormat), x, area.y + area.h + 18);
  }
  // Zero baseline, drawn heavier than the gridlines so positive vs negative segments read
  // as unambiguously on one side or the other of it.
  ctx.strokeStyle = '#2b3341';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(zeroX, area.y);
  ctx.lineTo(zeroX, area.y + area.h);
  ctx.stroke();

  const gap = 10;
  const barH = Math.max(4, Math.min(34, (area.h - gap * (n + 1)) / n));
  let y = area.y + gap;
  categories.forEach((cat, i) => {
    let cursorPos = zeroX, cursorNeg = zeroX;
    series.forEach(s => {
      const v = s.values[i] || 0;
      if (!v) return;
      const w = (Math.abs(v) / scale.range) * area.w;
      ctx.fillStyle = s.color;
      if (v > 0) { ctx.fillRect(cursorPos, y, w, barH); cursorPos += w; }
      else { ctx.fillRect(cursorNeg - w, y, w, barH); cursorNeg -= w; }
    });
    ctx.fillStyle = '#2b3341';
    ctx.font = '600 12px Inter, sans-serif';
    ctx.textAlign = 'right';
    ctx.fillText(dgFitLabel(ctx, String(cat), area.x - 20), area.x - 14, y + barH / 2 + 4);
    y += barH + gap;
  });
}

// Tornado / back-to-back bar chart: the first two series, drawn as mirrored horizontal bars
// either side of a shared category column in the middle — e.g. "Supplier A" vs "Supplier B"
// quoted per line item, or a low/high sensitivity pair per variable — so the two sides read
// as one direct left-vs-right comparison instead of two separate bar charts a reader has to
// mentally line up themselves. Both sides share one magnitude scale so bar lengths stay
// directly comparable across the center line.
function dgDrawTornadoBars(ctx, categories, series, area, opts) {
  if (!categories.length || series.length < 2) return;
  const sr0 = series[0], sr1 = series[1];
  const n = categories.length;
  const maxAbs = Math.max(1, ...sr0.values.map(v => Math.abs(v || 0)), ...sr1.values.map(v => Math.abs(v || 0)));

  // Value labels sit just outside each bar's tip. Scaling bars against the raw max lets the
  // biggest bar reach all the way to the chart's outer edge, pushing its label off the edge
  // with no room to render — so when labels are on, measure the widest one and shrink the
  // bar-length scale so every bar tip (and its label) stays inside the plot.
  ctx.font = '600 10.5px Inter, sans-serif';
  let tornadoLabelPad = 0;
  if (opts.values) {
    const allVals = [...sr0.values, ...sr1.values];
    const maxValLabelW = Math.max(0, ...allVals.map(v => ctx.measureText(dgFormatNumber(v, opts.numberFormat)).width));
    tornadoLabelPad = maxValLabelW + 10;
  }

  // Gutter sizes itself to the widest actual category label (with a sane floor/ceiling)
  // rather than a fixed fraction of the chart width, so longer category names (e.g.
  // "Operations", "Variable 12") don't get clipped while short ones ("HR") don't waste space.
  ctx.font = '600 11.5px Inter, sans-serif';
  const maxCatW = Math.max(0, ...categories.map(c => ctx.measureText(String(c || '')).width));
  const gutter = Math.min(240, Math.max(90, maxCatW + 28, area.w * 0.2));
  const sideW = (area.w - gutter) / 2;
  const barMaxW = Math.max(20, sideW - tornadoLabelPad);
  const leftX1 = area.x + sideW;
  const rightX0 = leftX1 + gutter;
  const headerH = 26;

  ctx.textAlign = 'center';
  ctx.font = '700 12px Inter, sans-serif';
  ctx.fillStyle = sr0.color;
  ctx.fillText(dgFitLabel(ctx, sr0.name, sideW - 8), area.x + sideW / 2, area.y + 14);
  ctx.fillStyle = sr1.color;
  ctx.fillText(dgFitLabel(ctx, sr1.name, sideW - 8), rightX0 + sideW / 2, area.y + 14);

  const plotY = area.y + headerH;
  const plotH = area.h - headerH;
  const gap = 10;
  const barH = Math.max(4, Math.min(30, (plotH - gap * (n + 1)) / n));
  let y = plotY + gap;

  // Center dividers the two sides mirror against, one per side of the label gutter.
  ctx.strokeStyle = '#c7cfd8';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(leftX1, plotY); ctx.lineTo(leftX1, plotY + plotH);
  ctx.moveTo(rightX0, plotY); ctx.lineTo(rightX0, plotY + plotH);
  ctx.stroke();

  categories.forEach((cat, i) => {
    const v0 = sr0.values[i] || 0, v1 = sr1.values[i] || 0;
    const w0 = (Math.abs(v0) / maxAbs) * barMaxW;
    const w1 = (Math.abs(v1) / maxAbs) * barMaxW;
    ctx.fillStyle = sr0.color;
    ctx.fillRect(leftX1 - w0, y, w0, barH);
    ctx.fillStyle = sr1.color;
    ctx.fillRect(rightX0, y, w1, barH);

    if (opts.values) {
      ctx.font = '600 10.5px Inter, sans-serif';
      ctx.fillStyle = '#2b3341';
      ctx.textAlign = 'right';
      ctx.fillText(dgFormatNumber(v0, opts.numberFormat), leftX1 - w0 - 6, y + barH / 2 + 4);
      ctx.textAlign = 'left';
      ctx.fillText(dgFormatNumber(v1, opts.numberFormat), rightX0 + w1 + 6, y + barH / 2 + 4);
    }

    ctx.fillStyle = '#101820';
    ctx.font = '600 11.5px Inter, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(dgFitLabel(ctx, String(cat), gutter - 10), leftX1 + gutter / 2, y + barH / 2 + 4);
    y += barH + gap;
  });
}

function dgDrawTrendline(ctx, rows, area, xs, scale) {
  const vals = rows.map(r => r.value);
  const n = vals.length;
  if (n < 2) return;
  // Use the SAME scale the chart itself is drawn with, rather than
  // recomputing an independent one — otherwise the trendline can visually
  // disagree with the bars/points it's supposed to be summarizing.
  const s = scale || dgYScale(vals, area);
  const { slope, intercept } = dgLinearRegression(vals);
  ctx.save();
  ctx.setLineDash([6, 5]);
  ctx.strokeStyle = 'rgba(239,68,68,0.85)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  xs.forEach((x, i) => {
    const predicted = slope * i + intercept;
    const y = s.toY(predicted);
    i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
  });
  ctx.stroke();
  ctx.restore();
  ctx.fillStyle = 'rgba(239,68,68,0.9)';
  ctx.font = '700 10.5px Inter, sans-serif';
  ctx.textAlign = 'left';
  ctx.fillText('Trend', xs[xs.length - 1] - 30, s.toY(slope * (n - 1) + intercept) - 10);
}

function dgDrawLine(ctx, rows, area, opts, filled) {
  const vals = rows.map(r => r.value);
  // Value labels sit 12px above each point (on top of a 5px dot) — reserve enough
  // headroom that the highest point's label can't run off the top of the chart.
  const scale = dgYScale(vals, area, opts.values ? 28 : 0);
  dgDrawAxisGrid(ctx, area, scale, opts);

  const n = rows.length;
  const stepX = n > 1 ? area.w / (n - 1) : 0;
  const pts = rows.map((r, i) => ({
    x: area.x + (n > 1 ? i * stepX : area.w / 2),
    y: scale.toY(r.value)
  }));

  const accent = rows[0] ? rows[0].color : '#00C2FF';
  const zeroY = scale.toY(0);

  if (filled) {
    // Fill down to the zero line, not the bottom of the canvas — with
    // negative values allowed, the bottom of the chart is no longer the
    // same thing as "zero", so filling to area.y+area.h would misrepresent
    // the magnitude of the shaded region.
    ctx.beginPath();
    ctx.moveTo(pts[0].x, zeroY);
    pts.forEach(p => ctx.lineTo(p.x, p.y));
    ctx.lineTo(pts[pts.length - 1].x, zeroY);
    ctx.closePath();
    const grad = ctx.createLinearGradient(0, area.y, 0, area.y + area.h);
    grad.addColorStop(0, dgHexAlpha(accent, 0.45));
    grad.addColorStop(1, dgHexAlpha(accent, 0.03));
    ctx.fillStyle = grad;
    ctx.fill();
  }

  ctx.beginPath();
  pts.forEach((p, i) => i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y));
  ctx.strokeStyle = accent;
  ctx.lineWidth = 3;
  ctx.lineJoin = 'round';
  ctx.stroke();

  rows.forEach((r, i) => {
    const p = pts[i];
    ctx.beginPath();
    ctx.arc(p.x, p.y, 5, 0, Math.PI * 2);
    ctx.fillStyle = r.color;
    ctx.fill();
    ctx.lineWidth = 2;
    ctx.strokeStyle = '#ffffff';
    ctx.stroke();

    ctx.fillStyle = '#5b6474';
    ctx.font = '11.5px Inter, sans-serif';
    ctx.textAlign = 'center';
    dgDrawAxisLabel(ctx, r.label, p.x, area.y + area.h + 20, Math.max(30, stepX - 6), opts.rotateLabels);

    if (opts.values) {
      ctx.fillStyle = '#101820';
      ctx.font = '700 12px Inter, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(dgFormatValueLabelFit(ctx, r.value, opts, Math.max(40, stepX - 4)), p.x, p.y - 12);
    }
  });

  if (opts.trendline && rows.length > 1) {
    const xs = pts.map(p => p.x);
    dgDrawTrendline(ctx, rows, area, xs, scale);
  }
}

function dgDrawPie(ctx, rows, circle, opts, donut) {
  // Pie/donut slices are proportions of a whole and can't represent a
  // negative share — a negative value would flip the arc direction and
  // draw a wildly oversized wedge. We use magnitude for the geometry so
  // the chart never renders garbage; dgRenderInsightsStrip separately
  // warns the user if their data actually has negative entries here.
  const total = rows.reduce((s, r) => s + Math.abs(r.value), 0) || 1;
  let angle = -Math.PI / 2;
  rows.forEach(r => {
    const slice = (Math.abs(r.value) / total) * Math.PI * 2;
    ctx.beginPath();
    ctx.moveTo(circle.x, circle.y);
    ctx.arc(circle.x, circle.y, circle.r, angle, angle + slice);
    ctx.closePath();
    ctx.fillStyle = r.color;
    ctx.fill();

    // Only label slices wide enough that the percentage text sits cleanly inside them —
    // a lot of small, similarly-sized slices (e.g. many census categories) previously all
    // tried to squeeze a label into the same tight radius and ended up overlapping each other.
    if (opts.values && slice > 0.25) {
      const mid = angle + slice / 2;
      const lx = circle.x + Math.cos(mid) * circle.r * 0.68;
      const ly = circle.y + Math.sin(mid) * circle.r * 0.68;
      ctx.fillStyle = '#ffffff';
      ctx.font = '700 13px Inter, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(Math.round((Math.abs(r.value) / total) * 100) + '%', lx, ly + 4);
    }
    angle += slice;
  });

  if (donut) {
    ctx.beginPath();
    ctx.arc(circle.x, circle.y, circle.r * 0.55, 0, Math.PI * 2);
    ctx.fillStyle = '#ffffff';
    ctx.fill();
  }
}

function dgDrawWaterfall(ctx, rows, area, opts) {
  let cum = 0;
  const n = rows.length;
  const cums = rows.map((r, i) => {
    const isTotal = i === 0 || i === n - 1 || /\b(total|start|end|net)\b/i.test(r.label || '');
    if (isTotal) {
      cum = r.value;
      return { start: 0, end: r.value, isTotal: true };
    }
    const start = cum;
    cum += r.value;
    return { start, end: cum, isTotal: false };
  });

  const allVals = cums.reduce((a, c) => a.concat([c.start, c.end]), []);
  const max = Math.max(1, ...allVals) * 1.15;
  const min = Math.min(0, ...allVals);
  const range = (max - min) || 1;
  const toY = v => area.y + area.h - ((v - min) / range) * area.h;

  ctx.strokeStyle = '#e5e9ef';
  ctx.lineWidth = 1;
  ctx.font = '11px Inter, sans-serif';
  ctx.fillStyle = '#8a94a3';
  ctx.textAlign = 'right';
  for (let i = 0; i <= 4; i++) {
    const v = min + range * i / 4;
    const y = toY(v);
    ctx.beginPath();
    ctx.moveTo(area.x, y);
    ctx.lineTo(area.x + area.w, y);
    ctx.stroke();
    ctx.fillText(dgFormatNumber(v, opts.numberFormat), area.x - 10, y + 4);
  }
  dgDrawAxisLines(ctx, area, { min, max, toY });

  // Same fix as the regular bar chart: a fixed 24px gap eats most of the chart width once
  // there are 20-40 waterfall steps, leaving hairline bars. Scale the gap down as n grows.
  const gap = n <= 8 ? 24 : Math.max(2, Math.min(24, (area.w / n) * 0.3));
  const barW = Math.max(2, Math.min(70, (area.w - gap * (n + 1)) / n));
  const usedW = barW * n + gap * (n + 1);
  const startX = area.x + (area.w - usedW) / 2 + gap;

  rows.forEach((r, i) => {
    const x = startX + i * (barW + gap);
    const { start, end, isTotal } = cums[i];
    const y0 = toY(start), y1 = toY(end);
    const top = Math.min(y0, y1), h = Math.max(2, Math.abs(y0 - y1));
    const color = isTotal ? '#3B82F6' : (r.value >= 0 ? '#22C55E' : '#EF4444');

    ctx.fillStyle = color;
    const wfRad = Math.min(opts.barRadius != null ? opts.barRadius : 4, barW / 2, h / 2);
    dgRoundRectPath(ctx, x, top, barW, h, wfRad);
    ctx.fill();

    if (i < n - 1) {
      const connectY = toY(end);
      ctx.strokeStyle = '#c7cfd8';
      ctx.setLineDash([3, 3]);
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(x + barW, connectY);
      ctx.lineTo(x + barW + gap, connectY);
      ctx.stroke();
      ctx.setLineDash([]);
    }

    ctx.fillStyle = '#5b6474';
    ctx.font = '11.5px Inter, sans-serif';
    ctx.textAlign = 'center';
    dgDrawAxisLabel(ctx, r.label, x + barW / 2, area.y + area.h + 20, barW + gap - 6, opts.rotateLabels);

    if (opts.values) {
      ctx.fillStyle = '#101820';
      ctx.font = '700 12px Inter, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(dgFormatValueLabelFit(ctx, r.value, opts, barW + gap - 4), x + barW / 2, top - 8);
    }
  });
}

function dgDrawPareto(ctx, rows, area, opts) {
  // Pareto is inherently a "share of total occurrences" analysis — counts
  // of complaints, defects, etc. — so we use magnitude for sorting and the
  // cumulative-% line; a negative count has no real meaning here and would
  // otherwise send the cumulative line the wrong direction.
  const sorted = [...rows].sort((a, b) => Math.abs(b.value) - Math.abs(a.value));
  const total = sorted.reduce((s, r) => s + Math.abs(r.value), 0) || 1;
  let cum = 0;
  const cumPct = sorted.map(r => { cum += Math.abs(r.value); return (cum / total) * 100; });
  const max = Math.max(1, ...sorted.map(r => Math.abs(r.value))) * 1.2;

  ctx.strokeStyle = '#e5e9ef';
  ctx.lineWidth = 1;
  ctx.font = '11px Inter, sans-serif';
  ctx.fillStyle = '#8a94a3';
  ctx.textAlign = 'right';
  for (let i = 0; i <= 4; i++) {
    const y = area.y + area.h - (area.h * i / 4);
    ctx.beginPath();
    ctx.moveTo(area.x, y);
    ctx.lineTo(area.x + area.w, y);
    ctx.stroke();
    ctx.fillText(dgFormatNumber(max * i / 4, opts.numberFormat), area.x - 10, y + 4);
  }
  ctx.textAlign = 'left';
  for (let i = 0; i <= 4; i++) {
    const y = area.y + area.h - (area.h * i / 4);
    ctx.fillText(Math.round(100 * i / 4) + '%', area.x + area.w + 8, y + 4);
  }
  dgDrawAxisLines(ctx, area, { min: 0, max, toY: v => area.y + area.h - (v / max) * area.h });

  const n = sorted.length;
  // Same fix as the bar/waterfall charts: scale the gap down as category count grows instead
  // of a fixed 24px that swallows the chart width once there are many bars.
  const gap = n <= 8 ? 24 : Math.max(2, Math.min(24, (area.w / n) * 0.3));
  const barW = Math.max(2, Math.min(70, (area.w - gap * (n + 1)) / n));
  const usedW = barW * n + gap * (n + 1);
  const startX = area.x + (area.w - usedW) / 2 + gap;

  sorted.forEach((r, i) => {
    const h = (Math.abs(r.value) / max) * area.h;
    const x = startX + i * (barW + gap);
    const y = area.y + area.h - h;
    ctx.fillStyle = r.color;
    const parRad = Math.min(opts.barRadius != null ? opts.barRadius : 6, barW / 2, h / 2);
    dgRoundRectPath(ctx, x, y, barW, h, parRad);
    ctx.fill();
    ctx.fillStyle = '#5b6474';
    ctx.font = '11.5px Inter, sans-serif';
    ctx.textAlign = 'center';
    dgDrawAxisLabel(ctx, r.label, x + barW / 2, area.y + area.h + 20, barW + gap - 6, opts.rotateLabels);
    if (opts.values) {
      ctx.fillStyle = '#101820';
      ctx.font = '700 12px Inter, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(dgFormatValueLabelFit(ctx, r.value, opts, barW + gap - 4), x + barW / 2, y - 8);
    }
  });

  const pts = sorted.map((r, i) => ({ x: startX + i * (barW + gap) + barW / 2, y: area.y + area.h - (cumPct[i] / 100) * area.h }));
  ctx.beginPath();
  pts.forEach((p, i) => i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y));
  ctx.strokeStyle = '#F97316';
  ctx.lineWidth = 2.5;
  ctx.lineJoin = 'round';
  ctx.stroke();
  pts.forEach((p, i) => {
    ctx.beginPath();
    ctx.arc(p.x, p.y, 4, 0, Math.PI * 2);
    ctx.fillStyle = '#F97316';
    ctx.fill();
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 1.5;
    ctx.stroke();
    ctx.fillStyle = '#F97316';
    ctx.font = '700 10.5px Inter, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(Math.round(cumPct[i]) + '%', p.x, p.y - 10);
  });

  const y80 = area.y + area.h - 0.8 * area.h;
  ctx.strokeStyle = 'rgba(239,68,68,0.55)';
  ctx.setLineDash([4, 4]);
  ctx.lineWidth = 1.3;
  ctx.beginPath();
  ctx.moveTo(area.x, y80);
  ctx.lineTo(area.x + area.w, y80);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = 'rgba(239,68,68,0.85)';
  ctx.font = '700 10px Inter, sans-serif';
  ctx.textAlign = 'left';
  ctx.fillText('80%', area.x + area.w + 8, y80 + 4);
}

function dgDrawFunnel(ctx, rows, area, opts) {
  if (!rows.length) return;
  // Funnel stages are cumulative counts moving through a process — a
  // negative "count" isn't meaningful, and would otherwise flip a
  // segment's width sign and draw a self-intersecting bowtie shape.
  const maxVal = Math.max(1, ...rows.map(r => Math.abs(r.value)));
  const n = rows.length;
  const segGap = 6;
  const segH = area.h / n;
  const maxW = Math.min(area.w * 0.85, 460);
  const cx = area.x + area.w / 2;

  rows.forEach((r, i) => {
    const wTop = (Math.abs(i === 0 ? maxVal : rows[i - 1].value) / maxVal) * maxW;
    const wBot = (Math.abs(r.value) / maxVal) * maxW;
    const yTop = area.y + i * segH;
    const yBot = yTop + segH - segGap;

    ctx.beginPath();
    ctx.moveTo(cx - wTop / 2, yTop);
    ctx.lineTo(cx + wTop / 2, yTop);
    ctx.lineTo(cx + wBot / 2, yBot);
    ctx.lineTo(cx - wBot / 2, yBot);
    ctx.closePath();
    ctx.fillStyle = r.color;
    ctx.fill();

    const midY = (yTop + yBot) / 2;
    const availSegW = Math.min(wTop, wBot) - 12;
    ctx.fillStyle = '#ffffff';
    ctx.font = '700 12px Inter, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(dgFitLabel(ctx, r.label, Math.max(30, availSegW)), cx, midY - 3);

    if (opts.values) {
      const pctOfFirst = rows[0].value ? Math.round((r.value / rows[0].value) * 100) : 100;
      ctx.font = '11px Inter, sans-serif';
      ctx.fillText(dgFitLabel(ctx, dgFormatNumber(r.value, opts.numberFormat) + (i > 0 ? ' (' + pctOfFirst + '%)' : ''), Math.max(30, availSegW)), cx, midY + 13);
    }
  });
}

// Draws a radar/spider chart: one axis per category arranged around a circle, one overlaid
// polygon per series. Values are expected to already be normalized onto a shared 0–100 scale by
// the caller (see dgBuildComparisonCharts) — this function only handles layout and drawing, not
// the statistics, so it stays reusable for any future multi-series comparison spec.
function dgDrawRadar(ctx, categories, series, area, opts) {
  if (!categories || !categories.length || !series || !series.length) return;
  const cx = area.x + area.w / 2;
  // Work out the legend's real row-wrap (same itemW/perRow math the draw pass below uses)
  // up front, so the space reserved for it always matches what's actually drawn. The old
  // fixed "3 per row" assumption disagreed with the dynamic wrap width whenever items were
  // wider or narrower than that guess, which either crowded the legend against the radar
  // shape or shrank the radar for legend room it didn't end up needing. Also reserve nothing
  // at all when the legend is hidden, instead of always carving out its space regardless.
  const showLegend = opts.legend !== false;
  let legendItemW = 0, legendRows = 0, legendH = 0;
  if (showLegend) {
    ctx.font = '12px Inter, sans-serif';
    legendItemW = Math.min(160, area.w / Math.min(3, series.length));
    const legendPerRow = Math.max(1, Math.floor(area.w / legendItemW));
    legendRows = Math.ceil(series.length / legendPerRow);
    legendH = 20 + legendRows * 20;
  }
  const cy = area.y + (area.h - legendH) / 2;
  const R = Math.max(24, Math.min(area.w, area.h - legendH) / 2 - 38);
  const n = categories.length;
  const angleStep = (Math.PI * 2) / n;
  const startAngle = -Math.PI / 2;

  const pointFor = (i, valuePct) => {
    const angle = startAngle + i * angleStep;
    const r = R * Math.max(0, Math.min(100, valuePct)) / 100;
    return { x: cx + r * Math.cos(angle), y: cy + r * Math.sin(angle) };
  };

  // Concentric rings + spokes
  ctx.strokeStyle = '#e4e9f0';
  ctx.lineWidth = 1;
  [0.25, 0.5, 0.75, 1].forEach(f => {
    ctx.beginPath();
    for (let i = 0; i <= n; i++) {
      const angle = startAngle + (i % n) * angleStep;
      const x = cx + R * f * Math.cos(angle), y = cy + R * f * Math.sin(angle);
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.stroke();
  });
  for (let i = 0; i < n; i++) {
    const angle = startAngle + i * angleStep;
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx + R * Math.cos(angle), cy + R * Math.sin(angle));
    ctx.stroke();
  }

  // Axis (category) labels
  ctx.fillStyle = '#3a4658';
  ctx.font = '600 11px Inter, sans-serif';
  for (let i = 0; i < n; i++) {
    const angle = startAngle + i * angleStep;
    const lx = cx + (R + 14) * Math.cos(angle);
    const ly = cy + (R + 14) * Math.sin(angle);
    ctx.textAlign = Math.cos(angle) > 0.15 ? 'left' : (Math.cos(angle) < -0.15 ? 'right' : 'center');
    ctx.fillText(dgFitLabel(ctx, categories[i], Math.max(50, area.w / n)), lx, ly + 4);
  }

  // Series polygons, drawn with a translucent fill so overlapping shapes stay readable
  series.forEach(s => {
    ctx.beginPath();
    s.values.forEach((v, i) => {
      const p = pointFor(i, v);
      if (i === 0) ctx.moveTo(p.x, p.y); else ctx.lineTo(p.x, p.y);
    });
    ctx.closePath();
    ctx.fillStyle = s.color + '2E';
    ctx.fill();
    ctx.strokeStyle = s.color;
    ctx.lineWidth = 2;
    ctx.stroke();
    s.values.forEach((v, i) => {
      const p = pointFor(i, v);
      ctx.beginPath();
      ctx.arc(p.x, p.y, 3, 0, Math.PI * 2);
      ctx.fillStyle = s.color;
      ctx.fill();
    });
  });

  // Legend (wraps to multiple rows for 4+ series) — itemW/perRow/rows here are the exact
  // values already used above to reserve legendH, so the drawn legend can't spill past the
  // space that was actually carved out for it.
  if (showLegend) {
    ctx.font = '12px Inter, sans-serif';
    const itemW = legendItemW;
    const perRow = Math.max(1, Math.floor(area.w / itemW));
    const rows = legendRows;
    const legendTop = area.y + area.h - (rows * 20) + 6;
    series.forEach((s, i) => {
      const row = Math.floor(i / perRow);
      const col = i % perRow;
      const rowCount = Math.min(perRow, series.length - row * perRow);
      const rowW = rowCount * itemW;
      const rowStartX = cx - rowW / 2;
      const x = rowStartX + col * itemW;
      const y = legendTop + row * 20;
      ctx.fillStyle = s.color;
      ctx.beginPath();
      ctx.arc(x + 5, y - 4, 5, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#4b5563';
      ctx.textAlign = 'left';
      ctx.fillText(dgFitLabel(ctx, s.name, itemW - 16), x + 16, y);
    });
  }
}

function dgDrawLegend(ctx, lines, W, y, opts) {
  ctx.font = '12px Inter, sans-serif';
  // All rows share one left edge, derived from the widest row in the block and centred
  // as a single unit — rather than each row centring itself — so shorter rows don't drift
  // out of alignment with longer ones underneath/above them. That jagged per-row centring
  // is what reads as "cluttered"; a shared edge reads as one tidy, deliberate legend.
  const blockW = lines.blockW != null ? lines.blockW : Math.max(0, ...lines.map(items => items.reduce((s, it) => s + it.w, 0)));
  const startX = Math.max(20, W / 2 - blockW / 2);

  // Thin divider separating the legend from the plot above it, the way a report
  // table separates a header from its footnote — a small cue that this is a
  // distinct, deliberate block rather than text trailing off the chart.
  ctx.strokeStyle = '#edf0f4';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(40, y - 14);
  ctx.lineTo(W - 40, y - 14);
  ctx.stroke();

  lines.forEach((items, li) => {
    let x = startX;
    const rowY = y + li * 24;
    items.forEach(it => {
      if (it.more) {
        const pillW = ctx.measureText(it.moreText).width + 16;
        ctx.strokeStyle = '#d8dee6';
        ctx.lineWidth = 1;
        dgRoundRectPath(ctx, x, rowY - 2, pillW, 17, 8.5);
        ctx.stroke();
        ctx.fillStyle = '#6b7684';
        ctx.textAlign = 'left';
        ctx.font = '600 11px Inter, sans-serif';
        ctx.fillText(it.moreText, x + 8, rowY + 10);
        ctx.font = '12px Inter, sans-serif';
        x += it.w;
        return;
      }
      ctx.fillStyle = it.r.color;
      ctx.beginPath();
      ctx.arc(x + 5, rowY + 6, 5, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#4b5563';
      ctx.textAlign = 'left';
      const label = it.r.label + (opts.values ? it.valStr : '');
      // it.w already reserves 30px total for the swatch+gaps (see dgLayoutLegend); the
      // text itself starts at x+16, so it only has it.w-16 to work with before the next
      // entry's swatch starts — fitting to it.w-14 let long labels bleed 2px into it.
      ctx.fillText(dgFitLabel(ctx, label, it.w - 16), x + 16, rowY + 10);
      x += it.w;
    });
  });
}

function dgRoundRectPath(ctx, x, y, w, h, r) {
  r = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

// Like dgRoundRectPath, but lets the caller round only the top corners and/or
// only the bottom corners — used for stacked-bar segments so the curve only
// shows on the outer edges of the stack, not on every internal seam.
function dgRoundRectStackPath(ctx, x, y, w, h, r, roundTop, roundBottom) {
  r = Math.max(0, Math.min(r, w / 2, h / 2));
  const tl = roundTop ? r : 0, tr = roundTop ? r : 0;
  const br = roundBottom ? r : 0, bl = roundBottom ? r : 0;
  ctx.beginPath();
  ctx.moveTo(x + tl, y);
  ctx.lineTo(x + w - tr, y);
  ctx.arcTo(x + w, y, x + w, y + tr, tr);
  ctx.lineTo(x + w, y + h - br);
  ctx.arcTo(x + w, y + h, x + w - br, y + h, br);
  ctx.lineTo(x + bl, y + h);
  ctx.arcTo(x, y + h, x, y + h - bl, bl);
  ctx.lineTo(x, y + tl);
  ctx.arcTo(x, y, x + tl, y, tl);
  ctx.closePath();
}

function dgTruncate(s, n) { s = String(s); return s.length > n ? s.slice(0, n - 1) + '…' : s; }

function dgHexAlpha(hex, alpha) {
  const h = hex.replace('#', '');
  const r = parseInt(h.substring(0, 2), 16), g = parseInt(h.substring(2, 4), 16), b = parseInt(h.substring(4, 6), 16);
  return `rgba(${r},${g},${b},${alpha})`;
}

function dgRender() {
  dgPersist();
  if (!document.getElementById('dgCanvas')) return;
  if (!document.getElementById('dgRows').childElementCount) dgRenderRows();
  if (!document.getElementById('dgPaletteRow').childElementCount) dgRenderPalette();
  dgRenderCustomSwatches();
  dgSyncRibbonForType();
  if (dgIs3DType(dgState.type)) {
    dgActivate3D(dgState.type);
    if (!dg3D.renderer) { dgState.type = (dgState.type === '3d-grouped-bar') ? 'grouped' : 'bar'; dgDeactivate3D(); dgDrawChart(); dgSyncRibbonForType(); } // 3D engine unavailable, fall back
  } else {
    dgDeactivate3D();
    dgDrawChart();
  }
  dgRenderTextOverlay();
  if (typeof dgSyncActiveMultiChartFromState === 'function') dgSyncActiveMultiChartFromState();
}

function dgDownloadPNG() {
  let canvas = dgGetExportCanvas();
  if (!canvas) { if (dgActiveMode === 'flow') toast('Write or pick a diagram first', 'error'); return; }
  canvas = sarvarcMaybeWatermarkCanvas(canvas);
  const titleId = (dgActiveMode === 'flow') ? 'dgFlowTitleInput' : 'dgTitleInput';
  try {
    const a = document.createElement('a');
    a.download = sarvarcBrandFilename(((document.getElementById(titleId) || {}).value || 'chart').trim().replace(/\s+/g, '_') + '.png');
    a.href = canvas.toDataURL('image/png');
    a.click();
    toast((dgActiveMode === 'flow' ? 'Diagram' : 'Chart') + ' downloaded', 'success');
  } catch (e) {
    console.error(e);
    toast('Download failed: ' + e.message, 'error');
  }
}

// ── Export dropdown: PDF / Word / JPEG / PNG ──
function dgExportFilename(ext) {
  const titleId = (dgActiveMode === 'flow') ? 'dgFlowTitleInput' : 'dgTitleInput';
  const raw = ((document.getElementById(titleId) || {}).value || 'chart').trim().replace(/[^\w\- ]+/g, '').trim().replace(/\s+/g, '_') + '.' + ext;
  return sarvarcBrandFilename(raw);
}

function dgExportChart(format) {
  dgCloseAllDropdowns();
  if (format === 'png') return dgDownloadPNG();
  if (format === 'jpeg') return dgExportJPEG();
  if (format === 'pdf') return dgExportPDF();
  if (format === 'docx') return dgExportDOCX();
}

function dgExportJPEG() {
  let canvas = dgGetExportCanvas();
  if (!canvas) return;
  canvas = sarvarcMaybeWatermarkCanvas(canvas);
  // The chart canvas is always painted with an opaque white background
  // first (see dgDrawChart), so converting straight to JPEG is safe —
  // there's no transparency to lose.
  const a = document.createElement('a');
  a.download = dgExportFilename('jpg');
  a.href = canvas.toDataURL('image/jpeg', 0.95);
  a.click();
  toast('Chart downloaded as JPEG', 'success');
}

async function dgExportPDF() {
  const canvas = dgGetExportCanvas();
  if (!canvas) return;
  if (!window.jspdf) { toast('PDF export is unavailable right now', 'error'); return; }
  const password = await sarvarcAskExportPassword('Export Chart as PDF');
  if (password === undefined) return; // cancelled
  try {
    const { jsPDF } = window.jspdf;
    const PXMM = 3.7795; // 96dpi px → mm, same conversion used elsewhere in this app
    const margin = 12; // mm, so the chart isn't flush against the page edge
    const imgW = canvas.width / PXMM, imgH = canvas.height / PXMM;
    const pageW = imgW + margin * 2, pageH = imgH + margin * 2;
    const pdf = new jsPDF(Object.assign({ orientation: pageW > pageH ? 'landscape' : 'portrait', unit: 'mm', format: [pageW, pageH] }, sarvarcPdfEncryptionOpts(password)));
    pdf.addImage(canvas.toDataURL('image/png'), 'PNG', margin, margin, imgW, imgH, '', 'FAST');
    if (window.sarvarcApplyFreeWatermark) sarvarcStampPdfWatermark(pdf);
    pdf.save(dgExportFilename('pdf'));
    toast('Chart exported as PDF' + (password ? ' (password protected)' : ''), 'success');
  } catch (e) {
    console.error(e);
    toast('PDF export failed: ' + e.message, 'error');
  }
}

async function dgExportDOCX() {
  let canvas = dgGetExportCanvas();
  if (!canvas) return;
  canvas = sarvarcMaybeWatermarkCanvas(canvas);
  if (typeof JSZip === 'undefined') { toast('Zip engine failed to load, check your connection', 'error'); return; }
  try {
    const title = (document.getElementById('dgTitleInput') || {}).value || 'Chart';
    const pngBase64 = canvas.toDataURL('image/png').split(',')[1];

    // Word page is 8.5in wide with 1in margins by default → 6.5in usable.
    // Scale the chart to fill that width (never upscale past its native
    // size) and keep its exact aspect ratio via EMU (914400 EMU per inch).
    const EMU_PER_IN = 914400;
    const maxWidthIn = 6.5;
    const nativeWidthIn = canvas.width / 96;
    const widthIn = Math.min(maxWidthIn, nativeWidthIn);
    const heightIn = widthIn * (canvas.height / canvas.width);
    const cx = Math.round(widthIn * EMU_PER_IN);
    const cy = Math.round(heightIn * EMU_PER_IN);

    const contentTypes = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Default Extension="png" ContentType="image/png"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>`;

    const rootRels = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>`;

    const docRels = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/image1.png"/></Relationships>`;

    const documentXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture">
<w:body>
<w:p><w:pPr><w:jc w:val="center"/></w:pPr><w:r><w:rPr><w:b/><w:sz w:val="32"/></w:rPr><w:t xml:space="preserve">${pdfedXmlEscape(title)}</w:t></w:r></w:p>
<w:p><w:pPr><w:jc w:val="center"/><w:spacing w:before="200"/></w:pPr><w:r><w:drawing><wp:inline distT="0" distB="0" distL="0" distR="0"><wp:extent cx="${cx}" cy="${cy}"/><wp:docPr id="1" name="Chart"/><wp:cNvGraphicFramePr><a:graphicFrameLocks noChangeAspect="1"/></wp:cNvGraphicFramePr><a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic><pic:nvPicPr><pic:cNvPr id="0" name="Chart.png"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip r:embed="rId1"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="${cx}" cy="${cy}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p>
<w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440" w:header="720" w:footer="720" w:gutter="0"/></w:sectPr>
</w:body>
</w:document>`;

    const zip = new JSZip();
    zip.file('[Content_Types].xml', contentTypes);
    zip.file('_rels/.rels', rootRels);
    zip.file('word/document.xml', documentXml);
    zip.file('word/_rels/document.xml.rels', docRels);
    zip.file('word/media/image1.png', pngBase64, { base64: true });

    const blob = await zip.generateAsync({ type: 'blob', mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' });
    pdfedDownloadBlob(blob, dgExportFilename('docx'));
    toast('Chart exported as Word document', 'success');
  } catch (e) {
    console.error(e);
    toast('Word export failed: ' + e.message, 'error');
  }
}

// ── Push-to-Workspace: destination choice modal ──
// Before pushing a chart, ask the user whether it should become a brand-new
// page in the Workspace, or be dropped onto the page currently open there.
// dgPendingPushImage lets this same choice modal serve a source OTHER than the flat
// chart canvas — set it (and clear it after use) to redirect dgConfirmPushChoice
// toward an already-captured image instead of dgGetExportCanvas(). Used by the
// Explore Map states/provinces view, which is a real DOM/Leaflet panel with no
// equivalent on #dgCanvas.
let dgPendingPushImage = null; // { dataUrl, pushKind } | null
function dgOpenPushChoiceModal() {
  const canvas = dgGetExportCanvas();
  if (!canvas) { toast((dgActiveMode === 'flow' ? 'Write or pick a diagram' : 'Build a chart') + ' first before pushing to Workspace', 'error'); return; }
  if (typeof pdfed === 'undefined' || typeof navigate !== 'function') { toast('Workspace editor is unavailable right now', 'error'); return; }
  // Map mode, zero matched countries: the map itself still renders (ocean panel +
  // outlines), but every country is the neutral "unmatched" tone, so it's worth a
  // heads-up before pushing rather than letting it look like the push silently failed.
  if (dgActiveMode === 'map' && dgState.type === 'worldmap' && Array.isArray(dgState.rows) && dgState.rows.length) {
    const anyMatched = dgState.rows.some(r => dgResolveCountry(r.label));
    if (!anyMatched) {
      toast('No row labels matched a country name yet — the map will push with outlines only. Try full country names (e.g. India, United States, Germany).', 'info');
    }
  }
  dgPendingPushImage = null; // ensure this goes through the normal chart-canvas path
  const overlay = document.getElementById('dgPushChoiceOverlay');
  if (overlay) overlay.classList.add('open');
}
function dgClosePushChoice() {
  const overlay = document.getElementById('dgPushChoiceOverlay');
  if (overlay) overlay.classList.remove('open');
}
function dgConfirmPushChoice(mode, cardEl) {
  if (cardEl) sarvarcAnimatedPush(cardEl, 'navIcon-workspace');
  dgClosePushChoice();
  if (dgPendingPushImage) {
    const pending = dgPendingPushImage;
    dgPendingPushImage = null;
    dgInsertImageIntoWorkspace(pending.dataUrl, pending.pushKind, mode);
  } else {
    dgInsertIntoWorkspace(mode);
  }
}

// ── GeoJSON → canvas renderer for the states/provinces push ────────────────────
// Plain equirectangular projection (with a cos(latitude) correction so shapes near
// the poles/equator aren't badly stretched) fit to the country's own bounding box.
// Walks every coordinate in every feature to find the bbox — depth is 2 for a
// Polygon's [ring][point] nesting, 3 for a MultiPolygon's [poly][ring][point].
function dgComputeGeoBBox(geojson) {
  let minLng = Infinity, minLat = Infinity, maxLng = -Infinity, maxLat = -Infinity;
  function visit(coords, depth) {
    if (depth === 0) {
      const lng = coords[0], lat = coords[1];
      if (lng < minLng) minLng = lng; if (lng > maxLng) maxLng = lng;
      if (lat < minLat) minLat = lat; if (lat > maxLat) maxLat = lat;
    } else {
      coords.forEach(c => visit(c, depth - 1));
    }
  }
  (geojson.features || []).forEach(f => {
    const g = f.geometry; if (!g) return;
    if (g.type === 'Polygon') visit(g.coordinates, 2);
    else if (g.type === 'MultiPolygon') visit(g.coordinates, 3);
  });
  if (!isFinite(minLng)) return null;
  return { minLng, minLat, maxLng, maxLat };
}
// Returns a project(lng,lat) -> [x,y] function that fits `bbox` into the canvas
// rect (boxX,boxY,boxW,boxH) with a small internal margin, cosLat-corrected so
// e.g. Russia or Canada don't come out squashed.
function dgBuildLngLatProjection(bbox, boxX, boxY, boxW, boxH) {
  const pad = Math.min(boxW, boxH) * 0.06;
  const midLatRad = ((bbox.minLat + bbox.maxLat) / 2) * Math.PI / 180;
  const cosLat = Math.max(0.15, Math.cos(midLatRad));
  const geoW = (bbox.maxLng - bbox.minLng) * cosLat || 1;
  const geoH = (bbox.maxLat - bbox.minLat) || 1;
  const availW = boxW - pad * 2, availH = boxH - pad * 2;
  const scale = Math.min(availW / geoW, availH / geoH);
  const drawW = geoW * scale, drawH = geoH * scale;
  const offX = boxX + pad + (availW - drawW) / 2;
  const offY = boxY + pad + (availH - drawH) / 2;
  return function project(lng, lat) {
    return [offX + (lng - bbox.minLng) * cosLat * scale, offY + (bbox.maxLat - lat) * scale];
  };
}
function dgFeatureToPath2D(feature, project) {
  const g = feature.geometry; if (!g) return null;
  const path = new Path2D();
  function addRing(ring) {
    ring.forEach((pt, i) => {
      const [x, y] = project(pt[0], pt[1]);
      if (i === 0) path.moveTo(x, y); else path.lineTo(x, y);
    });
    path.closePath();
  }
  if (g.type === 'Polygon') g.coordinates.forEach(addRing);
  else if (g.type === 'MultiPolygon') g.coordinates.forEach(poly => poly.forEach(addRing));
  return path;
}

// Renders the ADM1 GeoJSON straight onto an offscreen canvas — no DOM screenshot,
// no map tiles, nothing cross-origin — using the same flat card + hairline-border
// + pill-legend language as the world map and per-country zoom cards, so all three
// map views share one visual language and one export path.
function dgRenderStatesToCanvas(geojson, countryName) {
  const bbox = dgComputeGeoBBox(geojson);
  if (!bbox) return null;
  const rows = (dgState && Array.isArray(dgState.rows)) ? dgState.rows : [];
  const rowMap = {};
  rows.forEach(r => { rowMap[dgNormalizeStateName(r.label)] = r; });
  const normalizedKeys = Object.keys(rowMap);
  const features = (geojson && geojson.features) || [];
  const matchedVals = [];
  features.forEach(f => {
    const row = dgMatchStateRow(rowMap, normalizedKeys, (f.properties && f.properties.shapeName) || '');
    if (row) matchedVals.push(row.value);
  });
  const minV = matchedVals.length ? Math.min.apply(null, matchedVals) : 0;
  const maxV = matchedVals.length ? Math.max.apply(null, matchedVals) : 0;
  const numberFormat = (typeof dgGetOpts === 'function') ? (dgGetOpts().numberFormat || 'plain') : 'plain';

  const CW = 1100, CH = 760;
  const canvas = document.createElement('canvas');
  canvas.width = CW; canvas.height = CH;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, CW, CH);

  ctx.fillStyle = '#334155';
  ctx.font = '700 20px Inter, sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText(countryName, CW / 2, 34);

  const legendH = 50, panelPad = 14;
  const panelX = panelPad, panelY = 54, panelW = CW - panelPad * 2, panelH = CH - 54 - legendH - panelPad;
  // Genuinely flat panel — solid white, crisp hairline border, no shadow — matching
  // the world map and per-country zoom card so all three map views share one
  // premium, dimensionless visual language.
  dgRoundRectPath(ctx, panelX, panelY, panelW, panelH, 8);
  ctx.fillStyle = '#ffffff';
  ctx.fill();
  ctx.strokeStyle = '#dde3ea';
  ctx.lineWidth = 1;
  ctx.stroke();

  const project = dgBuildLngLatProjection(bbox, panelX + 10, panelY + 10, panelW - 20, panelH - 20);
  ctx.lineWidth = 0.6;
  features.forEach(f => {
    const path = dgFeatureToPath2D(f, project);
    if (!path) return;
    const row = dgMatchStateRow(rowMap, normalizedKeys, (f.properties && f.properties.shapeName) || '');
    if (row) {
      const t = maxV > minV ? (row.value - minV) / (maxV - minV) : 1;
      ctx.fillStyle = dgWorldMapColor(t);
    } else {
      ctx.fillStyle = '#cbd5e1';
    }
    ctx.fill(path);
    ctx.strokeStyle = '#ffffff';
    ctx.stroke(path);
  });

  const barY = panelY + panelH + 22, barW = Math.min(280, CW * 0.4), barH = 8;
  const barX = CW / 2 - barW / 2;
  if (matchedVals.length) {
    const grad = ctx.createLinearGradient(barX, 0, barX + barW, 0);
    grad.addColorStop(0, dgWorldMapColor(0));
    grad.addColorStop(1, dgWorldMapColor(1));
    ctx.fillStyle = grad;
    dgRoundRectPath(ctx, barX, barY, barW, barH, barH / 2);
    ctx.fill();
    ctx.strokeStyle = 'rgba(15,23,42,0.08)';
    ctx.lineWidth = 1;
    dgRoundRectPath(ctx, barX, barY, barW, barH, barH / 2);
    ctx.stroke();
    ctx.fillStyle = '#475569';
    ctx.font = '600 12px Inter, sans-serif';
    ctx.textAlign = 'right';
    ctx.fillText(dgFormatNumber(minV, numberFormat), barX - 8, barY + 8);
    ctx.textAlign = 'left';
    ctx.fillText(dgFormatNumber(maxV, numberFormat), barX + barW + 8, barY + 8);
  } else {
    ctx.fillStyle = '#94a3b8';
    ctx.font = '600 13px Inter, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('No state/province rows matched this country yet', CW / 2, barY + 12);
  }
  return canvas;
}

// ── Push the Explore Map states/provinces view to Workspace ────────────────────
// Previously this rasterized the live Leaflet panel with html2canvas, but the
// cross-origin basemap tiles (CARTO/OSM) reliably taint that canvas even with
// useCORS set — the same class of silent SecurityError already hit once on the
// Refine Report "Adjust to A4" canvas reads. Rendering straight from the cached
// GeoJSON (dgRenderStatesToCanvas above) sidesteps tile images entirely, so
// there's nothing left to taint the canvas.
async function dgMapxOpenPushChoiceModal() {
  // Whole function wrapped in try/catch (not just the render step) so literally
  // no failure mode here — including a guard-clause reference throwing, or
  // dgCountryIso3/getElementById returning something unexpected — can ever fail
  // silently. Every exit path now either shows a toast or logs to console.
  try {
    if (typeof pdfed === 'undefined' || typeof navigate !== 'function') { toast('Workspace editor is unavailable right now', 'error'); return; }
    if (!dgMapx.map || !dgMapx.statesOn || !dgMapx.statesLayer) { toast('Turn on States/Provinces and pick a country first', 'error'); return; }
    const select = document.getElementById('dgMapxCountrySelect');
    const countryName = select ? select.value : null;
    const iso3 = countryName ? dgCountryIso3(countryName) : null;
    const geojson = iso3 ? dgMapx.statesCache[iso3] : null;
    if (!geojson) { toast('Boundary data for this country is not loaded yet', 'error'); return; }
    const btn = document.getElementById('dgMapxPushBtn');
    const originalLabel = btn ? btn.textContent : '';
    if (btn) { btn.disabled = true; btn.textContent = 'Rendering…'; }
    try {
      const canvas = dgRenderStatesToCanvas(geojson, countryName);
      if (!canvas) { toast('Could not render this map', 'error'); return; }
      const dataUrl = canvas.toDataURL('image/png');
      dgPendingPushImage = { dataUrl, pushKind: 'map' };
      // Belt-and-suspenders on top of the z-index fix above: also close the Map
      // Explorer itself before showing the destination choice, so there's no
      // way for a future overlay/z-index change to re-hide this dialog behind
      // it again — the choice modal always opens onto a clear backdrop.
      const mapxModal = document.getElementById('dgMapExplorerModal');
      if (mapxModal) mapxModal.classList.remove('open');
      const overlay = document.getElementById('dgPushChoiceOverlay');
      if (overlay) overlay.classList.add('open');
    } catch (e) {
      console.error(e);
      toast('Could not prepare the map: ' + (e && e.message ? e.message : 'unknown error'), 'error');
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = originalLabel; }
    }
  } catch (outerErr) {
    console.error('dgMapxOpenPushChoiceModal failed before rendering:', outerErr);
    toast('Could not start the push: ' + (outerErr && outerErr.message ? outerErr.message : 'unknown error'), 'error');
  }
}

async function dgInsertIntoWorkspace(mode) {
  const canvas = dgGetExportCanvas();
  if (!canvas) return;
  let dataUrl;
  try {
    dataUrl = canvas.toDataURL('image/png');
  } catch (e) {
    console.error(e);
    toast('Could not prepare this for Workspace: ' + e.message, 'error');
    return;
  }
  // Tags what's being pushed so Refine Report can later single maps out for
  // the passport-photo grid layout instead of treating them like a logo or
  // an ordinary dropped-in picture.
  const pushKind = dgActiveMode === 'map' ? 'map' : (dgActiveMode === 'flow' ? 'diagram' : 'chart');
  await dgInsertImageIntoWorkspace(dataUrl, pushKind, mode);
}

// Shared by every "Push to Workspace" entry point — the flat chart/world-map canvas
// (dgInsertIntoWorkspace above) and the Explore Map states/provinces view
// (dgMapxInsertIntoWorkspace below), which captures a real DOM/Leaflet panel via
// html2canvas rather than reading dgCanvas. Both just need to hand this a finished
// PNG data URL; everything past that — new page vs. live page vs. no-workspace-yet — is
// identical regardless of what produced the image.
async function dgInsertImageIntoWorkspace(dataUrl, pushKind, mode) {
  if (typeof pdfed === 'undefined' || typeof navigate !== 'function') { toast('Workspace editor is unavailable right now', 'error'); return; }
  const noWorkspaceYet = !pdfed.pages || pdfed.pages.length === 0;

  try {
    if (noWorkspaceYet) {
      // No workspace document open yet — create a fresh blank A4 page to drop the chart onto,
      // regardless of which option was chosen, since there's no live page to add to.
      const mmW = 210, mmH = 297, EXPORT_PXMM = 3.7795;
      const eW = Math.round(mmW * EXPORT_PXMM), eH = Math.round(mmH * EXPORT_PXMM);
      const bg = document.createElement('canvas');
      bg.width = eW; bg.height = eH;
      const bctx = bg.getContext('2d');
      bctx.fillStyle = '#ffffff';
      bctx.fillRect(0, 0, eW, eH);

      pdfed.pages.push({
        type: 'blank', dataUrl: bg.toDataURL('image/png'), modified: true, edits: {},
        textBlocks: [], placedTexts: [], label: 'Diagram', bgColor: '#ffffff', pageMM: [mmW, mmH]
      });

      pdfed.pdfDoc = null;
      pdfed.file = { name: 'Diagrams & Graphs' };
      ['pdfedExportBtn', 'pdfedRefineBtn', 'pdfedExportBtn2', 'pdfedCloseBtn', 'pdfedPageInfoPill'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.style.display = '';
      });
      const upBtn = document.getElementById('pdfedUploadBtn');
      if (upBtn) upBtn.style.display = 'none';
      const fnEl = document.getElementById('pdfedFileName');
      if (fnEl) fnEl.textContent = pdfed.file.name;
      const ph = document.getElementById('pdfedPlaceholder'); if (ph) ph.style.display = 'none';
      const cw = document.getElementById('pdfedCanvasWrap'); if (cw) cw.style.display = 'inline-block';
      const tb = document.getElementById('pdfedToolbar'); if (tb) tb.style.visibility = 'visible';
      if (state && state.stats) { state.stats.pdfs++; state.stats.pages++; }
      if (typeof updateStats === 'function') updateStats();

      navigate('pdfeditor');
      if (typeof pdfedBuildStrip === 'function') await pdfedBuildStrip();
      if (typeof pdfedGoto === 'function') await pdfedGoto(0);
      setTimeout(() => {
        if (typeof pdfedZoomFit === 'function') pdfedZoomFit();
        if (typeof pdfedActivateImgGhost === 'function') pdfedActivateImgGhost(dataUrl, pushKind);
      }, 120);
    } else if (mode === 'new') {
      // Append a brand-new blank page to the existing Workspace document and drop the chart onto it.
      const mmW = 210, mmH = 297, EXPORT_PXMM = 3.7795;
      const eW = Math.round(mmW * EXPORT_PXMM), eH = Math.round(mmH * EXPORT_PXMM);
      const bg = document.createElement('canvas');
      bg.width = eW; bg.height = eH;
      const bctx = bg.getContext('2d');
      bctx.fillStyle = '#ffffff';
      bctx.fillRect(0, 0, eW, eH);

      pdfed.pages.push({
        type: 'blank', dataUrl: bg.toDataURL('image/png'), modified: true, edits: {},
        textBlocks: [], placedTexts: [], label: 'Diagram', bgColor: '#ffffff', pageMM: [mmW, mmH]
      });
      const newIdx = pdfed.pages.length - 1;

      if (state && state.stats) { state.stats.pages++; }
      if (typeof updateStats === 'function') updateStats();

      navigate('pdfeditor');
      if (typeof pdfedBuildStrip === 'function') await pdfedBuildStrip();
      if (typeof pdfedGoto === 'function') await pdfedGoto(newIdx);
      setTimeout(() => {
        if (typeof pdfedZoomFit === 'function') pdfedZoomFit();
        if (typeof pdfedActivateImgGhost === 'function') pdfedActivateImgGhost(dataUrl, pushKind);
        toast('New page added — drag to position, then click to drop your chart', 'info');
      }, 120);
    } else {
      // Add to the live page currently open in the Workspace.
      navigate('pdfeditor');
      setTimeout(() => {
        if (typeof pdfedActivateImgGhost === 'function') pdfedActivateImgGhost(dataUrl, pushKind);
        toast('Drag to position, then click to drop your chart onto the page', 'info');
      }, 60);
    }
  } catch (err) {
    console.error(err);
    toast('Could not insert chart: ' + err.message, 'error');
  }
}

// Space-to-pan (Figma/Photoshop convention): holding Space turns the empty-
// canvas drag back into panning instead of marquee-select. Ignored while the
// person is actually typing somewhere, so it never eats a literal space.
let dgSpaceDown = false;
document.addEventListener('keydown', function (e) {
  if (e.code !== 'Space' || e.repeat) return;
  const active = document.activeElement;
  const typing = active && (active.tagName === 'INPUT' || active.tagName === 'TEXTAREA' || active.isContentEditable);
  if (!typing) dgSpaceDown = true;
});
document.addEventListener('keyup', function (e) { if (e.code === 'Space') dgSpaceDown = false; });

// ── Marquee (drag-to-select) rectangle: dragging across empty canvas selects
// every placed text label the rectangle touches, same as clicking-and-
// dragging a selection box on any design canvas. Shift/Ctrl/Cmd-dragging adds
// to whatever was already selected instead of replacing it. ──
let dgMarquee = null;

function dgMarqueeStart(clientX, clientY, additive) {
  const holder = document.getElementById('dgCanvasHolder');
  if (!holder) return;
  const box = document.createElement('div');
  box.className = 'dg-marquee-box';
  holder.appendChild(box);
  dgMarquee = {
    startClientX: clientX, startClientY: clientY,
    additive, boxEl: box, moved: false,
    baseSelection: additive ? new Set(dgSelected) : new Set()
  };
  window.addEventListener('mousemove', dgMarqueeMove);
  window.addEventListener('mouseup', dgMarqueeEnd);
}

function dgMarqueeMove(ev) {
  if (!dgMarquee) return;
  const holder = document.getElementById('dgCanvasHolder');
  if (!holder) return;
  const dx = ev.clientX - dgMarquee.startClientX;
  const dy = ev.clientY - dgMarquee.startClientY;
  if (!dgMarquee.moved && Math.hypot(dx, dy) < 4) return;
  dgMarquee.moved = true;

  // Draw the rectangle in the holder's own (scrollable) coordinate space.
  const holderRect = holder.getBoundingClientRect();
  const x1h = dgMarquee.startClientX - holderRect.left + holder.scrollLeft;
  const y1h = dgMarquee.startClientY - holderRect.top + holder.scrollTop;
  const x2h = ev.clientX - holderRect.left + holder.scrollLeft;
  const y2h = ev.clientY - holderRect.top + holder.scrollTop;
  dgMarquee.boxEl.style.left = Math.min(x1h, x2h) + 'px';
  dgMarquee.boxEl.style.top = Math.min(y1h, y2h) + 'px';
  dgMarquee.boxEl.style.width = Math.abs(x2h - x1h) + 'px';
  dgMarquee.boxEl.style.height = Math.abs(y2h - y1h) + 'px';

  // Hit-test against the chart's own (unscaled) coordinate space: the zoom
  // wrap's on-screen rect divided by the current zoom stays correct no
  // matter how the holder is scrolled or the chart is zoomed.
  const wrap = document.getElementById('dgCanvasZoomWrap');
  const wrapRect = wrap ? wrap.getBoundingClientRect() : holderRect;
  const cx1 = (Math.min(dgMarquee.startClientX, ev.clientX) - wrapRect.left) / dgZoomLevel;
  const cy1 = (Math.min(dgMarquee.startClientY, ev.clientY) - wrapRect.top) / dgZoomLevel;
  const cx2 = (Math.max(dgMarquee.startClientX, ev.clientX) - wrapRect.left) / dgZoomLevel;
  const cy2 = (Math.max(dgMarquee.startClientY, ev.clientY) - wrapRect.top) / dgZoomLevel;

  const hit = new Set();
  (dgState.texts || []).forEach(t => {
    const node = document.querySelector('.dg-placed-text[data-id="' + t.id + '"]');
    const tw = node ? node.offsetWidth : 40, th = node ? node.offsetHeight : 24;
    if (t.x < cx2 && t.x + tw > cx1 && t.y < cy2 && t.y + th > cy1) hit.add(t.id);
  });

  dgSelected = new Set([...dgMarquee.baseSelection, ...hit]);
  dgSyncSelectionUI();
}

function dgMarqueeEnd() {
  if (!dgMarquee) return;
  if (dgMarquee.boxEl && dgMarquee.boxEl.parentNode) dgMarquee.boxEl.parentNode.removeChild(dgMarquee.boxEl);
  if (!dgMarquee.moved && !dgMarquee.additive) {
    // A plain click (no drag) on empty canvas clears the selection.
    dgDeselectAllTexts();
  }
  dgMarquee = null;
  window.removeEventListener('mousemove', dgMarqueeMove);
  window.removeEventListener('mouseup', dgMarqueeEnd);
}

// ── Diagrams & Graphs: preview canvas zoom (scoped to the canvas holder only) ──
var dgZoomLevel = 1;
var DG_ZOOM_MIN = 0.25, DG_ZOOM_MAX = 3, DG_ZOOM_STEP = 0.1;

function dgApplyZoom() {
  const wrap = document.getElementById('dgCanvasZoomWrap');
  if (wrap) wrap.style.transform = 'scale(' + dgZoomLevel + ')';
  if (typeof dg3D !== 'undefined' && dg3D.active && dg3D.renderer) {
    dg3DUpdateResolutionForZoom(dgZoomLevel);
  }
  const overlay = document.getElementById('dgTextOverlay');
  if (overlay) overlay.style.setProperty('--dg-inv-zoom', (1 / (dgZoomLevel || 1)).toFixed(4));
  const label = document.getElementById('dgZoomLabel');
  if (label) label.textContent = Math.round(dgZoomLevel * 100) + '%';
  const zoomInBtn = document.getElementById('dgZoomInBtn');
  const zoomOutBtn = document.getElementById('dgZoomOutBtn');
  if (zoomInBtn) zoomInBtn.disabled = dgZoomLevel >= DG_ZOOM_MAX - 1e-6;
  if (zoomOutBtn) zoomOutBtn.disabled = dgZoomLevel <= DG_ZOOM_MIN + 1e-6;
}
function dgZoomIn() {
  dgZoomLevel = Math.min(DG_ZOOM_MAX, Math.round((dgZoomLevel + DG_ZOOM_STEP) * 100) / 100);
  dgApplyZoom();
}

// Keeps the Legend/Values/Trend/Insights chips in the Live Preview toolbar (rather than
// the ribbon) in sync with their checkbox state — highlighting the chip when its overlay
// is on — then redraws the chart the same way the old ribbon checkboxes did.
function dgToggleShowChip(checkbox, chipId) {
  const chip = document.getElementById(chipId);
  if (chip) chip.classList.toggle('active', checkbox.checked);
  dgRender();
}
window.dgToggleShowChip = dgToggleShowChip;

function dgZoomOut() {
  dgZoomLevel = Math.max(DG_ZOOM_MIN, Math.round((dgZoomLevel - DG_ZOOM_STEP) * 100) / 100);
  dgApplyZoom();
}
function dgZoomReset() {
  dgZoomLevel = 1;
  dgApplyZoom();
}
// Scales the chart preview to use the space actually available in the holder,
// instead of always sitting at its fixed 1200×675 native size (which, on most
// screens, left the chart looking small and low with a lot of dead space
// around it). Mirrors the PDF editor's pdfedZoomFit — same idea, same math —
// so it plugs into the existing dgZoomLevel/dgApplyZoom pipeline that pan,
// marquee-select, and the text overlay already scale against.
function dgFitZoomToHolder() {
  const holder = document.getElementById('dgCanvasHolder');
  const canvas = dgIs3DType(dgState.type) ? document.getElementById('dgCanvas3D') : document.getElementById('dgCanvas');
  if (!holder || !canvas || !canvas.width || !canvas.height) return;
  const availW = holder.clientWidth - 24;   // minus .dg-canvas-holder's 12px×2 padding
  const availH = holder.clientHeight - 24;
  if (availW <= 0 || availH <= 0) return;
  const fit = Math.min(availW / canvas.width, availH / canvas.height);
  dgZoomLevel = Math.max(DG_ZOOM_MIN, Math.min(DG_ZOOM_MAX, Math.round(fit * 100) / 100));
  dgApplyZoom();
}
window.dgFitZoomToHolder = dgFitZoomToHolder;
// Re-fit whenever the window resizes while the Diagrams & Graphs canvas view
// is on screen, so resizing the browser doesn't leave the chart stranded at
// a stale scale. Debounced since resize fires rapidly.
let dgFitResizeTimer = null;
window.addEventListener('resize', function () {
  const sec = document.getElementById('sec-diagrams');
  if (!sec || !sec.classList.contains('active')) return;
  clearTimeout(dgFitResizeTimer);
  dgFitResizeTimer = setTimeout(dgFitZoomToHolder, 150);
});
function dgInitCanvasZoom() {
  const holder = document.getElementById('dgCanvasHolder');
  if (!holder || holder.dataset.zoomBound) return;
  holder.dataset.zoomBound = '1';
  // Scoped to the preview canvas only: requires Ctrl/Cmd so normal page/section
  // scrolling elsewhere in the workspace is never affected.
  holder.addEventListener('wheel', function (e) {
    if (!e.ctrlKey && !e.metaKey) return;
    e.preventDefault();
    if (e.deltaY < 0) dgZoomIn(); else dgZoomOut();
  }, { passive: false });
  holder.addEventListener('dblclick', function () { dgZoomReset(); });
  dgApplyZoom();

  // Hand-tool style drag-to-pan, same pattern as the main Workspace canvas.
  const dgPanState = { dragging: false, startX: 0, startY: 0, startScrollL: 0, startScrollT: 0 };

  function dgPanStart(x, y) {
    dgPanState.dragging = true;
    dgPanState.startX = x;
    dgPanState.startY = y;
    dgPanState.startScrollL = holder.scrollLeft;
    dgPanState.startScrollT = holder.scrollTop;
    holder.classList.add('dg-panning');
  }
  function dgPanMove(x, y) {
    if (!dgPanState.dragging) return;
    holder.scrollLeft = dgPanState.startScrollL - (x - dgPanState.startX);
    holder.scrollTop  = dgPanState.startScrollT - (y - dgPanState.startY);
  }
  function dgPanEnd() {
    if (!dgPanState.dragging) return;
    dgPanState.dragging = false;
    holder.classList.remove('dg-panning');
  }

  // Plain left-drag on empty canvas is a marquee (drag-to-select) rectangle —
  // the Canva/Figma convention the person can select text labels manually
  // with. Panning still works via middle-click drag, or by holding Space
  // (also the Figma/Photoshop convention) while dragging.
  holder.addEventListener('mousedown', function (e) {
    if (e.button === 1) { dgPanStart(e.clientX, e.clientY); e.preventDefault(); return; }
    if (e.button !== 0) return;
    if (dgIs3DType(dgState.type)) return; // let OrbitControls own left-drag (orbit) on the 3D canvas
    if (dgSpaceDown) { dgPanStart(e.clientX, e.clientY); e.preventDefault(); return; }
    dgMarqueeStart(e.clientX, e.clientY, e.shiftKey || e.ctrlKey || e.metaKey);
    e.preventDefault();
  });
  window.addEventListener('mousemove', function (e) { dgPanMove(e.clientX, e.clientY); });
  window.addEventListener('mouseup', dgPanEnd);

  holder.addEventListener('touchstart', function (e) {
    if (e.touches.length !== 1) return;
    const t = e.touches[0];
    dgPanStart(t.clientX, t.clientY);
  }, { passive: true });
  holder.addEventListener('touchmove', function (e) {
    if (!dgPanState.dragging || e.touches.length !== 1) return;
    const t = e.touches[0];
    dgPanMove(t.clientX, t.clientY);
  }, { passive: true });
  holder.addEventListener('touchend', dgPanEnd);
  holder.addEventListener('touchcancel', dgPanEnd);
}
dgInitCanvasZoom();

// ── Manual text labels on the chart canvas (Canva-style, draggable) ──
// This is a pure DOM overlay layer (#dgTextOverlay) living inside the same
// #dgCanvasZoomWrap as the <canvas>. It scales/pans as one unit with the
// chart via the existing CSS transform (dgApplyZoom), so dragging text
// NEVER calls dgDrawChart() and never touches the canvas — the chart
// ("its environment") is never cleared, redrawn, or reset while a label is
// being moved or edited. Text is only ever baked onto pixels transiently,
// on an offscreen clone, at export time (see dgGetExportCanvas below).
let dgTextSeq = 0;
let dgTextDrag = null; // { id, startX, startY, startLeft, startTop, moved }
let dgPtxtToolbarItem = null; // the text item the floating B/I/U toolbar is currently attached to

function dgAddText() {
  const canvas = document.getElementById('dgCanvas');
  const fontSize = 20;
  const estW = Math.max(60, 'Text'.length * fontSize * 0.6);
  const estH = fontSize * 1.4;
  const pos = dgFindSmartTextPosition(estW, estH);
  const item = {
    id: 'dgtxt_' + (++dgTextSeq),
    text: 'Text',
    x: pos.x,
    y: pos.y,
    fontSize,
    color: '#101820',
    bold: true,
    align: 'left',
    fontFamily: 'Inter'
  };
  dgState.texts.push(item);
  dgRenderTextOverlay();
  dgSelectText(item.id);
  const el = document.querySelector('.dg-placed-text[data-id="' + item.id + '"]');
  if (el) { dgEnterTextEdit(el, item); }
}

// Smart placement: rather than always dropping new text dead-center (where
// it just stacks on top of whatever was added before), this checks a
// handful of usually-quiet spots on the canvas — corners and top-center,
// which sit clear of bars/lines/pie slices in every chart type — against
// the bounding boxes of text already placed, and picks the first one that
// doesn't overlap. If every quiet spot is taken, it falls back to a
// Word/PowerPoint-style diagonal cascade so labels fan out instead of
// hiding directly on top of each other.
function dgFindSmartTextPosition(w, h) {
  const canvas = document.getElementById('dgCanvas');
  const CW = canvas ? canvas.width : 1200, CH = canvas ? canvas.height : 675;
  const margin = 16;
  const pad = 10; // breathing room required between two labels' boxes

  const existing = (dgState.texts || []).map(t => {
    const el = document.querySelector('.dg-placed-text[data-id="' + t.id + '"]');
    const tw = el ? el.offsetWidth : Math.max(40, String(t.text || '').length * t.fontSize * 0.55);
    const th = el ? el.offsetHeight : t.fontSize * 1.4;
    return { x: t.x, y: t.y, w: tw, h: th };
  });

  function overlapsExisting(x, y) {
    return existing.some(e =>
      x < e.x + e.w + pad && x + w + pad > e.x &&
      y < e.y + e.h + pad && y + h + pad > e.y
    );
  }

  const candidates = [
    { x: margin, y: margin },                                   // top-left
    { x: CW - w - margin, y: margin },                          // top-right
    { x: Math.round(CW / 2 - w / 2), y: margin },               // top-center
    { x: margin, y: CH - h - margin },                          // bottom-left
    { x: CW - w - margin, y: CH - h - margin },                 // bottom-right
    { x: Math.round(CW / 2 - w / 2), y: Math.round(CH / 2 - h / 2) } // dead center, last resort
  ];
  for (const c of candidates) {
    if (!overlapsExisting(c.x, c.y)) return c;
  }

  const n = existing.length;
  const spanX = Math.max(1, CW - w - margin * 2);
  const spanY = Math.max(1, CH - h - margin * 2);
  return {
    x: margin + (n * 26) % spanX,
    y: margin + (n * 22) % spanY
  };
}

function dgRenderTextOverlay() {
  const layer = document.getElementById('dgTextOverlay');
  if (!layer) return;
  layer.innerHTML = '';
  dgState.texts.forEach(item => {
    const el = document.createElement('div');
    el.className = 'dg-placed-text';
    el.dataset.id = item.id;
    el.contentEditable = 'false';
    el.draggable = false;
    el.spellcheck = false;
    el.style.left = item.x + 'px';
    el.style.top = item.y + 'px';
    el.style.fontSize = item.fontSize + 'px';
    el.style.color = item.color;
    el.style.fontWeight = item.bold ? '700' : '400';
    el.style.fontStyle = item.italic ? 'italic' : 'normal';
    el.style.textDecoration = item.underline ? 'underline' : 'none';
    el.style.textAlign = item.align || 'left';
    el.style.fontFamily = `'${item.fontFamily || 'Inter'}', sans-serif`;
    el.textContent = item.text;

    const del = document.createElement('div');
    del.className = 'dg-ptxt-del';
    del.title = 'Delete text';
    del.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>';
    del.style.display = 'none';
    del.onclick = (ev) => { ev.stopPropagation(); dgDeleteText(item.id); };
    el.appendChild(del);

    const move = document.createElement('div');
    move.className = 'dg-ptxt-move';
    move.title = 'Drag to move';
    move.innerHTML = '<svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="5 9 2 12 5 15"/><polyline points="9 5 12 2 15 5"/><polyline points="15 19 12 22 9 19"/><polyline points="19 9 22 12 19 15"/><line x1="2" y1="12" x2="22" y2="12"/><line x1="12" y1="2" x2="12" y2="22"/></svg>';
    move.addEventListener('mousedown', (ev) => dgTextMouseDown(ev, el, item));
    move.addEventListener('touchstart', (ev) => dgTextMouseDown(ev, el, item), { passive: false });
    el.appendChild(move);

    const resize = document.createElement('div');
    resize.className = 'dg-ptxt-resize';
    resize.title = 'Drag to resize';
    resize.addEventListener('mousedown', (ev) => dgTextResizeMouseDown(ev, el, item));
    resize.addEventListener('touchstart', (ev) => dgTextResizeMouseDown(ev, el, item), { passive: false });
    el.appendChild(resize);

    el.addEventListener('mousedown', (ev) => dgTextMouseDown(ev, el, item));
    el.addEventListener('touchstart', (ev) => dgTextMouseDown(ev, el, item), { passive: false });
    el.addEventListener('dblclick', (ev) => { ev.stopPropagation(); dgEnterTextEdit(el, item); });
    el.addEventListener('blur', () => dgExitTextEdit(el, item));
    el.addEventListener('keydown', (ev) => {
      if (ev.key === 'Escape') { ev.preventDefault(); el.blur(); }
      if (ev.key === 'Enter' && !ev.shiftKey && el.classList.contains('editing')) { ev.preventDefault(); el.blur(); }
    });

    layer.appendChild(el);
    if (dgSelected.has(item.id)) { el.classList.add('selected'); del.style.display = 'flex'; }
  });
}

// ── Manual multi-select (Canva/Figma-style) ──────────────────────────────
// dgSelected holds the ids of every currently-selected placed text. A plain
// click selects just that one item; Ctrl/Cmd-click (or Shift-click) adds/
// removes a single item from the set without disturbing the rest; the
// ribbon's "Select All" button and Ctrl+A select every text on the chart;
// and dragging an empty patch of canvas draws a marquee rectangle that
// selects everything it touches (see dgMarqueeStart below).
let dgSelected = new Set();

function dgSyncSelectionUI() {
  document.querySelectorAll('#dgTextOverlay .dg-placed-text').forEach(n => {
    const isSel = dgSelected.has(n.dataset.id);
    n.classList.toggle('selected', isSel);
    const del = n.querySelector('.dg-ptxt-del');
    if (del) del.style.display = isSel ? 'flex' : 'none';
  });
  // The floating Bold/Italic/Underline/Align toolbar edits one item's
  // properties at a time, so only show it when the selection is a single item.
  if (dgSelected.size === 1) {
    const item = (dgState.texts || []).find(t => t.id === [...dgSelected][0]);
    if (item) dgShowPtxtToolbar(item); else dgHidePtxtToolbar();
  } else {
    dgHidePtxtToolbar();
  }
}

// id === null clears the selection. additive=true toggles id in/out of the
// existing selection (Ctrl/Cmd/Shift-click); otherwise id becomes the sole
// selection (a plain click).
function dgSelectText(id, additive) {
  if (id == null) { dgSelected.clear(); dgSyncSelectionUI(); return; }
  if (additive) {
    if (dgSelected.has(id)) dgSelected.delete(id); else dgSelected.add(id);
  } else {
    dgSelected = new Set([id]);
  }
  dgSyncSelectionUI();
}

function dgSelectAllTexts() {
  if (!(dgState.texts || []).length) { toast('No text labels on the chart yet', 'info'); return; }
  dgSelected = new Set(dgState.texts.map(t => t.id));
  dgSyncSelectionUI();
}

function dgDeselectAllTexts() {
  dgSelected.clear();
  dgSyncSelectionUI();
  dgHidePtxtToolbar();
}

function dgDeleteText(id) {
  dgState.texts = dgState.texts.filter(t => t.id !== id);
  dgSelected.delete(id);
  dgRenderTextOverlay();
  dgHidePtxtToolbar();
}

// Deletes every currently-selected text (used by Cut and the Delete/Backspace key).
function dgDeleteSelectedTexts() {
  if (!dgSelected.size) return false;
  dgState.texts = (dgState.texts || []).filter(t => !dgSelected.has(t.id));
  dgSelected.clear();
  dgRenderTextOverlay();
  dgHidePtxtToolbar();
  return true;
}

// ── Copy / Cut / Paste (Ctrl+C / Ctrl+X / Ctrl+V) ───────────────────────
let dgClipboard = [];   // deep-cloned text items, ids stripped
let dgPasteCount = 0;   // cascades repeated pastes so they don't stack exactly on top of each other

function dgCopySelectedTexts() {
  const items = (dgState.texts || []).filter(t => dgSelected.has(t.id));
  if (!items.length) return false;
  dgClipboard = items.map(t => { const c = JSON.parse(JSON.stringify(t)); delete c.id; return c; });
  dgPasteCount = 0;
  return true;
}

function dgCutSelectedTexts() {
  if (!dgCopySelectedTexts()) return false;
  dgDeleteSelectedTexts();
  toast('Cut ' + dgClipboard.length + (dgClipboard.length === 1 ? ' text label' : ' text labels'), 'info');
  return true;
}

function dgPasteClipboardTexts() {
  if (!dgClipboard.length) return false;
  dgPasteCount++;
  const offset = 20 * dgPasteCount;
  const pastedIds = [];
  dgClipboard.forEach(src => {
    const item = JSON.parse(JSON.stringify(src));
    item.id = 'dgtxt_' + (++dgTextSeq);
    item.x = (src.x || 0) + offset;
    item.y = (src.y || 0) + offset;
    dgState.texts.push(item);
    pastedIds.push(item.id);
  });
  dgRenderTextOverlay();
  dgSelected = new Set(pastedIds);
  dgSyncSelectionUI();
  toast('Pasted ' + pastedIds.length + (pastedIds.length === 1 ? ' text label' : ' text labels'), 'info');
  return true;
}

// Guard used by the global keydown handler below: only intercept Ctrl/Cmd+C/X/V
// (and Delete/Ctrl+A) for the chart's own clipboard when the Diagrams & Graphs
// canvas is actually the thing on screen, and never while the user is typing
// inside a placed text box (that should keep native browser copy/paste/select).
function dgCanvasIsActive() {
  const holder = document.getElementById('dgCanvasHolder');
  if (!holder || holder.offsetParent === null) return false;
  const active = document.activeElement;
  if (active && active.classList && active.classList.contains('dg-placed-text') && active.isContentEditable) return false;
  if (active && (active.tagName === 'INPUT' || active.tagName === 'TEXTAREA' || active.isContentEditable)) return false;
  return true;
}

document.addEventListener('keydown', function (e) {
  if (!dgCanvasIsActive()) return;
  const mod = e.ctrlKey || e.metaKey;
  if (mod && e.key.toLowerCase() === 'a') {
    e.preventDefault();
    dgSelectAllTexts();
  } else if (mod && e.key.toLowerCase() === 'c') {
    if (dgCopySelectedTexts()) e.preventDefault();
  } else if (mod && e.key.toLowerCase() === 'x') {
    if (dgCutSelectedTexts()) e.preventDefault();
  } else if (mod && e.key.toLowerCase() === 'v') {
    if (dgPasteClipboardTexts()) e.preventDefault();
  } else if ((e.key === 'Delete' || e.key === 'Backspace') && dgSelected.size) {
    e.preventDefault();
    dgDeleteSelectedTexts();
  } else if (e.key === 'Escape') {
    dgDeselectAllTexts();
  }
});

// ── Floating Bold/Italic/Underline toolbar: shows above whichever placed
// text is selected, tracks it while dragged/resized, and toggles style
// directly on the DOM node (no full overlay re-render needed). ──
function dgShowPtxtToolbar(item) {
  dgPtxtToolbarItem = item;
  const tb = document.getElementById('dgPtxtToolbar');
  if (!tb) return;
  tb.style.display = 'flex';
  dgUpdatePtxtToolbarButtons(item);
  dgPositionPtxtToolbar();
}

function dgHidePtxtToolbar() {
  dgPtxtToolbarItem = null;
  const tb = document.getElementById('dgPtxtToolbar');
  if (tb) tb.style.display = 'none';
  ['dgRbnAlignLeftBtn', 'dgRbnAlignCenterBtn', 'dgRbnAlignRightBtn'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.classList.remove('active');
  });
}

function dgPositionPtxtToolbar() {
  const item = dgPtxtToolbarItem;
  const tb = document.getElementById('dgPtxtToolbar');
  if (!item || !tb) return;
  tb.style.left = item.x + 'px';
  tb.style.top = Math.max(0, item.y - 40) + 'px';
}

function dgUpdatePtxtToolbarButtons(item) {
  const b = document.getElementById('dgPtxtBoldBtn');
  const i = document.getElementById('dgPtxtItalicBtn');
  const u = document.getElementById('dgPtxtUnderlineBtn');
  const al = document.getElementById('dgPtxtAlignLeftBtn');
  const ac = document.getElementById('dgPtxtAlignCenterBtn');
  const ar = document.getElementById('dgPtxtAlignRightBtn');
  const ral = document.getElementById('dgRbnAlignLeftBtn');
  const rac = document.getElementById('dgRbnAlignCenterBtn');
  const rar = document.getElementById('dgRbnAlignRightBtn');
  if (b) b.classList.toggle('active', !!item.bold);
  if (i) i.classList.toggle('active', !!item.italic);
  if (u) u.classList.toggle('active', !!item.underline);
  { const fb = document.getElementById('dgPtxtFontBtn'); if (fb) fb.textContent = (item.fontFamily || 'Inter').split(',')[0].replace(/['"]/g, ''); }
  const align = item.align || 'left';
  if (al) al.classList.toggle('active', align === 'left');
  if (ac) ac.classList.toggle('active', align === 'center');
  if (ar) ar.classList.toggle('active', align === 'right');
  if (ral) ral.classList.toggle('active', align === 'left');
  if (rac) rac.classList.toggle('active', align === 'center');
  if (rar) rar.classList.toggle('active', align === 'right');
}

function dgPtxtSetAlign(align) {
  const item = dgPtxtToolbarItem;
  if (!item) {
    // Ribbon button clicked with no text selected — nudge the user rather
    // than silently doing nothing.
    toast('Select a text label on the chart first', 'info');
    return;
  }
  item.align = align;
  const el = document.querySelector('.dg-placed-text[data-id="' + item.id + '"]');
  if (el) el.style.textAlign = align;

  // Canva-style: alignment repositions the whole box relative to the canvas
  // width, not just the text within a shrink-wrapped box (which is invisible
  // for single-line labels, the overwhelmingly common case).
  const canvas = document.getElementById('dgCanvas');
  const CW = canvas ? canvas.width : 1200;
  const margin = 16;
  const w = el ? el.offsetWidth : 0;
  let newX = item.x;
  if (align === 'left') newX = margin;
  else if (align === 'center') newX = Math.round((CW - w) / 2);
  else if (align === 'right') newX = CW - w - margin;
  item.x = Math.max(0, newX);
  if (el) el.style.left = item.x + 'px';
  dgPositionPtxtToolbar();

  dgUpdatePtxtToolbarButtons(item);
}

function dgPtxtSetFont(value) {
  const item = dgPtxtToolbarItem;
  if (!item) return;
  sarvarcLoadFont(value);
  item.fontFamily = value;
  const el = document.querySelector('.dg-placed-text[data-id="' + item.id + '"]');
  if (el) el.style.fontFamily = `'${value}', sans-serif`;
  const fb = document.getElementById('dgPtxtFontBtn');
  if (fb) fb.textContent = value.split(',')[0].replace(/['"]/g, '');
}

function dgPtxtToggleStyle(prop) {
  const item = dgPtxtToolbarItem;
  if (!item) return;
  item[prop] = !item[prop];
  const el = document.querySelector('.dg-placed-text[data-id="' + item.id + '"]');
  if (el) {
    if (prop === 'bold') el.style.fontWeight = item.bold ? '700' : '400';
    if (prop === 'italic') el.style.fontStyle = item.italic ? 'italic' : 'normal';
    if (prop === 'underline') el.style.textDecoration = item.underline ? 'underline' : 'none';
  }
  dgUpdatePtxtToolbarButtons(item);
}

function dgEnterTextEdit(el, item) {
  dgSelectText(item.id);
  el.classList.add('editing');
  el.contentEditable = 'true';
  el.focus();
  // Place caret at the end rather than selecting/replacing all text.
  const range = document.createRange();
  range.selectNodeContents(el);
  range.collapse(false);
  const sel = window.getSelection();
  sel.removeAllRanges();
  sel.addRange(range);
}

function dgExitTextEdit(el, item) {
  el.classList.remove('editing');
  el.contentEditable = 'false';
  const val = (el.textContent || '').trim();
  item.text = val || 'Text';
  el.textContent = item.text;
  // Re-append the delete badge that textContent just wiped out.
  const del = document.createElement('div');
  del.className = 'dg-ptxt-del';
  del.title = 'Delete text';
  del.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>';
  del.style.display = el.classList.contains('selected') ? 'flex' : 'none';
  del.onclick = (ev) => { ev.stopPropagation(); dgDeleteText(item.id); };
  el.appendChild(del);

  const resize = document.createElement('div');
  resize.className = 'dg-ptxt-resize';
  resize.title = 'Drag to resize';
  resize.addEventListener('mousedown', (ev) => dgTextResizeMouseDown(ev, el, item));
  resize.addEventListener('touchstart', (ev) => dgTextResizeMouseDown(ev, el, item), { passive: false });
  el.appendChild(resize);

  const move = document.createElement('div');
  move.className = 'dg-ptxt-move';
  move.title = 'Drag to move';
  move.innerHTML = '<svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="5 9 2 12 5 15"/><polyline points="9 5 12 2 15 5"/><polyline points="15 19 12 22 9 19"/><polyline points="19 9 22 12 19 15"/><line x1="2" y1="12" x2="22" y2="12"/><line x1="12" y1="2" x2="12" y2="22"/></svg>';
  move.addEventListener('mousedown', (ev) => dgTextMouseDown(ev, el, item));
  move.addEventListener('touchstart', (ev) => dgTextMouseDown(ev, el, item), { passive: false });
  el.appendChild(move);
}

function dgTextMouseDown(ev, el, item) {
  const point = ev.touches ? ev.touches[0] : ev;
  const wasEditing = el.classList.contains('editing');
  ev.stopPropagation(); // never let this bubble up into the canvas hand-pan / marquee

  // Ctrl/Cmd/Shift-click: toggle just this one item in or out of the current
  // selection (standard multi-select convention) and don't start a drag.
  if (!wasEditing && (ev.ctrlKey || ev.metaKey || ev.shiftKey)) {
    dgSelectText(item.id, true);
    return;
  }

  if (!dgSelected.has(item.id)) {
    dgSelectText(item.id); // plain click on an unselected item -> select just this one
  }
  // If the item was already part of a multi-selection, a plain click/drag on
  // it keeps the whole group selected and moves every selected item together.
  const dragIds = dgSelected.size > 1 ? [...dgSelected] : [item.id];
  const items = dragIds.map(id => {
    const it = (dgState.texts || []).find(t => t.id === id);
    const node = document.querySelector('.dg-placed-text[data-id="' + id + '"]');
    return (it && node) ? { item: it, el: node, startX: it.x, startY: it.y } : null;
  }).filter(Boolean);

  dgTextDrag = {
    primary: item, el, wasEditing, items,
    startClientX: point.clientX, startClientY: point.clientY, moved: false
  };
  window.addEventListener('mousemove', dgTextMouseMove);
  window.addEventListener('mouseup', dgTextMouseUp);
  window.addEventListener('touchmove', dgTextMouseMove, { passive: false });
  window.addEventListener('touchend', dgTextMouseUp);
  // If it's not currently being edited, this mousedown can only mean "move
  // me" — commit to a drag right away. If it IS being edited, let the
  // browser place the caret normally; dgTextMouseMove only turns this into
  // a drag once the pointer actually moves past a small threshold, so a
  // plain click to position your cursor / keep typing is left alone.
  if (!wasEditing) { ev.preventDefault(); items.forEach(d => d.el.classList.add('dragging')); }
}

function dgTextMouseMove(ev) {
  if (!dgTextDrag) return;
  const point = ev.touches ? ev.touches[0] : ev;
  const rawDx = point.clientX - dgTextDrag.startClientX;
  const rawDy = point.clientY - dgTextDrag.startClientY;

  if (!dgTextDrag.moved) {
    if (Math.hypot(rawDx, rawDy) < 4) return; // still could just be a caret click, not a drag
    dgTextDrag.moved = true;
    if (dgTextDrag.wasEditing) {
      // The pointer moved enough to mean "drag", not "place my cursor" —
      // cancel the native text selection this would otherwise start and
      // hand control over to the drag instead.
      const sel = window.getSelection();
      if (sel) sel.removeAllRanges();
      dgExitTextEdit(dgTextDrag.el, dgTextDrag.primary);
    }
    dgTextDrag.items.forEach(d => d.el.classList.add('dragging'));
  }

  ev.preventDefault();
  // Divide by dgZoomLevel: the overlay is visually scaled by the same CSS
  // transform as the canvas, so a screen-space mouse delta must be
  // converted back into the canvas's own 1200x675 coordinate space.
  const dx = rawDx / dgZoomLevel;
  const dy = rawDy / dgZoomLevel;

  if (dgTextDrag.items.length === 1) {
    // Single-item drag keeps the Canva-style smart alignment/snap guides.
    const d = dgTextDrag.items[0];
    const rawX = d.startX + dx, rawY = d.startY + dy;
    const w = d.el.offsetWidth, h = d.el.offsetHeight;
    const snapped = dgApplySnap(d.item, rawX, rawY, w, h);
    d.item.x = snapped.x; d.item.y = snapped.y;
    d.el.style.left = d.item.x + 'px'; d.el.style.top = d.item.y + 'px';
  } else {
    // Multiple items move together as a rigid group (no snapping), so their
    // positions relative to each other stay exactly fixed while dragging.
    dgClearSnapGuides();
    dgTextDrag.items.forEach(d => {
      d.item.x = Math.round(d.startX + dx);
      d.item.y = Math.round(d.startY + dy);
      d.el.style.left = d.item.x + 'px';
      d.el.style.top = d.item.y + 'px';
    });
  }
  if (dgPtxtToolbarItem && dgTextDrag.items.some(d => d.item === dgPtxtToolbarItem)) dgPositionPtxtToolbar();
}

function dgTextMouseUp() {
  if (!dgTextDrag) return;
  const wasMulti = dgTextDrag.items.length > 1;
  const noDrag = !dgTextDrag.moved;
  const primaryId = dgTextDrag.primary.id;
  dgTextDrag.items.forEach(d => d.el.classList.remove('dragging'));
  dgTextDrag = null;
  dgClearSnapGuides();
  window.removeEventListener('mousemove', dgTextMouseMove);
  window.removeEventListener('mouseup', dgTextMouseUp);
  window.removeEventListener('touchmove', dgTextMouseMove);
  window.removeEventListener('touchend', dgTextMouseUp);
  // A plain click (no drag) on one item of a multi-selection narrows the
  // selection down to just that item — matching standard editor behavior.
  if (wasMulti && noDrag) dgSelectText(primaryId);
}

// Smart resize (Canva-style): dragging the corner handle scales the font
// size right along with the box, using the diagonal distance dragged vs.
// the box's starting diagonal — so a drag in any direction scales evenly
// instead of just stretching a fixed font into a bigger/smaller box. Same
// pattern as the PDF editor's te-resize-handle, adapted to this canvas's
// own zoom level (dgZoomLevel) instead of pdfed.zoom.
let dgTextResize = null;

function dgTextResizeMouseDown(ev, el, item) {
  ev.preventDefault();
  ev.stopPropagation(); // don't also trigger the parent's move-drag
  dgSelectText(item.id);
  const point = ev.touches ? ev.touches[0] : ev;
  const startW = el.offsetWidth, startH = el.offsetHeight;
  dgTextResize = {
    item, el,
    startDiag: Math.sqrt(startW * startW + startH * startH) || 1,
    startFontSize: item.fontSize,
    startClientX: point.clientX, startClientY: point.clientY,
    startW, startH
  };
  window.addEventListener('mousemove', dgTextResizeMouseMove);
  window.addEventListener('mouseup', dgTextResizeMouseUp);
  window.addEventListener('touchmove', dgTextResizeMouseMove, { passive: false });
  window.addEventListener('touchend', dgTextResizeMouseUp);
}

function dgTextResizeMouseMove(ev) {
  if (!dgTextResize) return;
  ev.preventDefault();
  const point = ev.touches ? ev.touches[0] : ev;
  const dx = (point.clientX - dgTextResize.startClientX) / dgZoomLevel;
  const dy = (point.clientY - dgTextResize.startClientY) / dgZoomLevel;
  const newW = Math.max(10, dgTextResize.startW + dx);
  const newH = Math.max(8, dgTextResize.startH + dy);
  const newDiag = Math.sqrt(newW * newW + newH * newH);
  const scale = newDiag / dgTextResize.startDiag;
  const newFontSize = Math.max(8, Math.min(120, Math.round(dgTextResize.startFontSize * scale)));
  dgTextResize.item.fontSize = newFontSize;
  dgTextResize.el.style.fontSize = newFontSize + 'px';
  if (dgPtxtToolbarItem === dgTextResize.item) dgPositionPtxtToolbar();
}

function dgTextResizeMouseUp() {
  dgTextResize = null;
  window.removeEventListener('mousemove', dgTextResizeMouseMove);
  window.removeEventListener('mouseup', dgTextResizeMouseUp);
  window.removeEventListener('touchmove', dgTextResizeMouseMove);
  window.removeEventListener('touchend', dgTextResizeMouseUp);
}

// ── Smart alignment (Canva-style): while dragging, snaps the box's edges/
// center to the canvas center/edges and to other placed text's edges/
// center, and flashes a thin guide line for whichever snap fired. Pure
// geometry + a visual overlay — never touches the chart canvas. ──
const DG_SNAP_PX = 6; // canvas-space px tolerance

function dgClearSnapGuides() {
  const g = document.getElementById('dgSnapGuides');
  if (g) g.innerHTML = '';
}

function dgShowSnapGuide(axis, pos) {
  const g = document.getElementById('dgSnapGuides');
  if (!g) return;
  const line = document.createElement('div');
  line.className = 'dg-snap-line ' + (axis === 'v' ? 'v' : 'h');
  if (axis === 'v') line.style.left = pos + 'px'; else line.style.top = pos + 'px';
  g.appendChild(line);
}

function dgApplySnap(item, rawX, rawY, w, h) {
  const canvas = document.getElementById('dgCanvas');
  const CW = canvas ? canvas.width : 1200, CH = canvas ? canvas.height : 675;

  const xTargets = [0, CW / 2, CW];
  const yTargets = [0, CH / 2, CH];
  (dgState.texts || []).forEach(t => {
    if (t.id === item.id) return;
    const el = document.querySelector('.dg-placed-text[data-id="' + t.id + '"]');
    const tw = el ? el.offsetWidth : 0, th = el ? el.offsetHeight : 0;
    xTargets.push(t.x, t.x + tw / 2, t.x + tw);
    yTargets.push(t.y, t.y + th / 2, t.y + th);
  });

  let snappedX = rawX, bestXDiff = DG_SNAP_PX + 1, guideX = null;
  [rawX, rawX + w / 2, rawX + w].forEach((edge, i) => {
    const off = i === 0 ? 0 : (i === 1 ? w / 2 : w);
    xTargets.forEach(t => {
      const diff = Math.abs(edge - t);
      if (diff < bestXDiff) { bestXDiff = diff; snappedX = t - off; guideX = t; }
    });
  });

  let snappedY = rawY, bestYDiff = DG_SNAP_PX + 1, guideY = null;
  [rawY, rawY + h / 2, rawY + h].forEach((edge, i) => {
    const off = i === 0 ? 0 : (i === 1 ? h / 2 : h);
    yTargets.forEach(t => {
      const diff = Math.abs(edge - t);
      if (diff < bestYDiff) { bestYDiff = diff; snappedY = t - off; guideY = t; }
    });
  });

  dgClearSnapGuides();
  if (guideX !== null) dgShowSnapGuide('v', guideX);
  if (guideY !== null) dgShowSnapGuide('h', guideY);

  return { x: Math.round(snappedX), y: Math.round(snappedY) };
}

// Draws all manual text labels onto a given canvas context, in the canvas's
// native (unscaled) coordinate space. Used ONLY for export compositing —
// never called on the live/interactive dgCanvas.
function dgDrawTextsOnCtx(ctx) {
  (dgState.texts || []).forEach(item => {
    ctx.save();
    ctx.fillStyle = item.color || '#101820';
    ctx.font = (item.bold ? '700 ' : '400 ') + (item.italic ? 'italic ' : '') + item.fontSize + 'px Inter, sans-serif';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    const align = item.align || 'left';
    const lines = String(item.text || '').split('\n');
    // The on-screen box shrink-wraps to its widest line, and left/center/right
    // aligns each line within that box — mirror the same geometry here so
    // exported images match what was placed on the live overlay.
    const lineWidths = lines.map(line => ctx.measureText(line).width);
    const boxW = Math.max(0, ...lineWidths);
    lines.forEach((line, i) => {
      const ly = item.y + 2 + i * (item.fontSize * 1.3);
      const lw = lineWidths[i];
      let lx = item.x + 4;
      if (align === 'center') lx = item.x + 4 + (boxW - lw) / 2;
      else if (align === 'right') lx = item.x + 4 + (boxW - lw);
      ctx.fillText(line, lx, ly);
      if (item.underline && line) {
        const uy = ly + item.fontSize * 1.05;
        ctx.strokeStyle = item.color || '#101820';
        ctx.lineWidth = Math.max(1, item.fontSize / 16);
        ctx.beginPath();
        ctx.moveTo(lx, uy);
        ctx.lineTo(lx + lw, uy);
        ctx.stroke();
      }
    });
    ctx.restore();
  });
}

// Returns an offscreen canvas with the current chart PLUS all placed text
// baked onto it — used for every export path (PNG/JPEG/PDF/DOCX/Push).
// The real #dgCanvas is never touched, so the live preview and the
// overlay's drag/edit state are completely unaffected by exporting.
function dgGetExportCanvas() {
  if (dgActiveMode === 'flow') return dgFlowCanvasCache || null;
  if (dgIs3DType(dgState.type) && dg3D.renderer) {
    // Force one fresh frame right before capture (renderer has
    // preserveDrawingBuffer:true so toDataURL reads the last-rendered frame)
    dg3D.renderer.render(dg3D.scene, dg3D.camera);
    return document.getElementById('dgCanvas3D');
  }
  const canvas = document.getElementById('dgCanvas');
  if (!canvas) return null;
  if (!dgState.texts || !dgState.texts.length) return canvas;
  const out = document.createElement('canvas');
  out.width = canvas.width;
  out.height = canvas.height;
  const ctx = out.getContext('2d');
  ctx.drawImage(canvas, 0, 0);
  dgDrawTextsOnCtx(ctx);
  return out;
}
// Exposed globally so the Kadessa assistant module (its own separate IIFE,
// further down the file) can call this to grab a clean chart image for
// vision -- without this, dgGetExportCanvas is only visible inside this
// closure, and calling it from elsewhere quietly fails.
window.dgGetExportCanvas = dgGetExportCanvas;

// ── High-resolution ("4K") export ────────────────────────────────────────────
// Built for the World Map's choropleth — a fixed-size, flat-shaded map is exactly
// the kind of content that turns visibly blocky the moment it's zoomed into or
// printed at the app's normal ~1200px-wide canvas — but works for any chart type
// on this same canvas. Rather than upscaling the already-rendered bitmap (which
// only blurs it up, adding no real detail), this re-runs the exact same vector
// draw calls (Path2D fills/strokes, fillText, gradients) onto a fresh offscreen
// canvas whose backing resolution is `DG_4K_SCALE`x bigger, so every edge and
// glyph is rasterized crisp at the higher resolution instead of stretched.
const DG_4K_SCALE = 3.2; // 1200×675 (this canvas's base size) × 3.2 = 3840×2160, true 4K UHD

function dgGetExportCanvasHD() {
  if (dgActiveMode === 'flow' || dgIs3DType(dgState.type)) return null; // not applicable — see dgDownloadPNG4K
  const hd = document.createElement('canvas');
  dgDrawChart(hd, DG_4K_SCALE);
  if (dgState.texts && dgState.texts.length) {
    const ctx = hd.getContext('2d');
    ctx.save();
    ctx.setTransform(DG_4K_SCALE, 0, 0, DG_4K_SCALE, 0, 0);
    dgDrawTextsOnCtx(ctx);
    ctx.restore();
  }
  return hd;
}

// Downloads a crisp, high-resolution PNG of the current chart/map — same content
// as "Download PNG", just rendered at DG_4K_SCALE so it holds up at full-screen
// zoom or in print, instead of the compact ~1200px-wide size used for the live
// preview and the standard export pipeline.
function dgDownloadPNG4K() {
  if (dgActiveMode === 'flow') {
    toast('Diagrams already export at high resolution — use Download PNG', 'info');
    return;
  }
  if (dgIs3DType(dgState.type)) {
    toast('4K export isn\'t available for 3D charts yet', 'error');
    return;
  }
  const canvas = document.getElementById('dgCanvas');
  if (!canvas) { toast('Build a chart first', 'error'); return; }
  try {
    const hd = dgGetExportCanvasHD();
    if (!hd) return;
    const titleId = 'dgTitleInput';
    const base = ((document.getElementById(titleId) || {}).value || 'chart').trim().replace(/\s+/g, '_') || 'chart';
    const a = document.createElement('a');
    a.download = sarvarcBrandFilename(base + '_4K.png');
    a.href = hd.toDataURL('image/png');
    a.click();
    toast('Chart downloaded in 4K', 'success');
  } catch (e) {
    console.error(e);
    toast('4K download failed: ' + e.message, 'error');
  }
}
window.dgDownloadPNG4K = dgDownloadPNG4K;

// ── Rotating Video export ──
// Records the live 3D chart doing one slow spin, with the user's typed
// notes rendered beneath it, and downloads the result as a .webm file.
// Everything happens on-device: a hidden composite canvas is fed into
// MediaRecorder via canvas.captureStream(), so no upload/server is involved.
const dgVideo = { recording: false, raf: null };

function dgOpenVideoExportModal() {
  dgCloseAllDropdowns();
  const modal = document.getElementById('dgVideoModal');
  const warn = document.getElementById('dgVideoModalNote3D');
  const btn = document.getElementById('dgVideoRecordBtn');
  const is3D = dgIs3DType(dgState.type) && dg3D.renderer;
  if (warn) warn.style.display = is3D ? 'none' : 'block';
  if (btn) btn.disabled = !is3D;
  if (btn) btn.style.opacity = is3D ? '1' : '0.5';
  const status = document.getElementById('dgVideoStatus');
  if (status) status.textContent = '';
  // Same containing-block fix as dgOpenMapExplorer: this modal is position:fixed
  // but lives inside #dgCanvasZoomWrap, whose CSS transform (from dgApplyZoom)
  // makes it the containing block instead of the viewport, mispositioning/clipping
  // the modal. Escape it to <body> once, same as the Map Explorer.
  if (modal && modal.parentElement !== document.body) document.body.appendChild(modal);
  if (modal) { modal.style.display = 'flex'; }
  dgVideoOnQualityChange();
  dgVideoDrawPreviewFrame();
}

// 4K software VP9 encoding at 60fps is more than most devices/browsers can
// reliably sustain in real time — when the encoder falls behind it tends to
// produce a truncated/broken .webm rather than gracefully catching up. So
// 4K locks itself to 30fps for a file that actually opens; 1080p/1440p keep
// the 60fps "butter smooth" option since they're light enough for that.
function dgVideoOnQualityChange() {
  const q = (document.getElementById('dgVideoQualitySelect') || {}).value;
  const fpsSel = document.getElementById('dgVideoFpsSelect');
  const note = document.getElementById('dgVideoQualityNote');
  if (!fpsSel) return;
  if (q === '2160') {
    fpsSel.value = '30';
    fpsSel.disabled = true;
    if (note) note.textContent = '4K locks to 30fps so the export encodes reliably instead of overloading and producing a broken file.';
  } else {
    fpsSel.disabled = false;
    if (note) note.textContent = '';
  }
}
window.dgVideoOnQualityChange = dgVideoOnQualityChange;

function dgCloseVideoExportModal() {
  if (dgVideo.recording) return; // don't let the modal close mid-recording
  const modal = document.getElementById('dgVideoModal');
  if (modal) modal.style.display = 'none';
}

// Static preview of the composite frame (chart + notes) so the user can see
// roughly what the exported video will look like before hitting record.
function dgVideoDrawPreviewFrame() {
  const canvas = document.getElementById('dgVideoPreviewCanvas');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#0A0F1E';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  if (dgIs3DType(dgState.type) && dg3D.renderer) {
    dg3D.renderer.render(dg3D.scene, dg3D.camera);
    const chartH = Math.round(canvas.height * 0.78);
    ctx.drawImage(dg3D.renderer.domElement, 0, 0, canvas.width, chartH);
    dgVideoDrawNotes(ctx, canvas, chartH);
  } else {
    ctx.fillStyle = 'rgba(232,244,255,0.5)';
    ctx.font = '13px Inter';
    ctx.textAlign = 'center';
    ctx.fillText('Build a 3D chart to preview the rotating video', canvas.width / 2, canvas.height / 2);
  }
}

function dgVideoDrawNotes(ctx, canvas, chartH, scale) {
  scale = scale || 1;
  const notes = (document.getElementById('dgVideoNotesInput') || {}).value || '';
  ctx.fillStyle = '#141B2D';
  ctx.fillRect(0, chartH, canvas.width, canvas.height - chartH);
  if (!notes.trim()) return;
  ctx.fillStyle = '#E8F4FF';
  ctx.font = Math.round(15 * scale) + 'px Inter';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  dgVideoWrapText(ctx, notes, 20 * scale, chartH + 14 * scale, canvas.width - 40 * scale, 20 * scale, 5);
}

function dgVideoWrapText(ctx, text, x, y, maxWidth, lineHeight, maxLines) {
  const words = text.split(/\s+/);
  let line = '', lines = [];
  for (const w of words) {
    const test = line ? line + ' ' + w : w;
    if (ctx.measureText(test).width > maxWidth && line) { lines.push(line); line = w; }
    else line = test;
  }
  if (line) lines.push(line);
  if (lines.length > maxLines) {
    lines = lines.slice(0, maxLines);
    lines[maxLines - 1] = lines[maxLines - 1].replace(/\s*\S*$/, '') + '…';
  }
  lines.forEach((l, i) => ctx.fillText(l, x, y + i * lineHeight));
}

// Quality presets: chartW is the rendered 3D viewport width in the exported
// video (in real pixels, not CSS px). chartH is derived from the chart's
// native aspect ratio so nothing gets stretched/squished. Bitrates are set
// to what software VP9 can realistically sustain at each resolution/fps —
// overshooting this is what caused 4K exports to choke and come out broken.
const DG_VIDEO_QUALITY_PRESETS = {
  '1080': { chartW: 1920, bitrate: 16_000_000 },
  '1440': { chartW: 2560, bitrate: 24_000_000 },
  '2160': { chartW: 3840, bitrate: 30_000_000 } // paired with a 30fps lock, see dgVideoOnQualityChange
};

function dgStartVideoRecording() {
  if (dgVideo.recording) return;
  if (!(dgIs3DType(dgState.type) && dg3D.renderer)) {
    toast('Build a 3D chart first, then record its rotation', 'error');
    return;
  }
  if (typeof MediaRecorder === 'undefined') {
    toast('Video recording is not supported in this browser', 'error');
    return;
  }

  const durationSec = parseFloat((document.getElementById('dgVideoDurationSelect') || {}).value || '8');
  const qualityKey = (document.getElementById('dgVideoQualitySelect') || {}).value || '2160';
  const fps = qualityKey === '2160' ? 30 : parseInt((document.getElementById('dgVideoFpsSelect') || {}).value || '60', 10);
  const preset = DG_VIDEO_QUALITY_PRESETS[qualityKey] || DG_VIDEO_QUALITY_PRESETS['2160'];

  const btn = document.getElementById('dgVideoRecordBtn');
  const status = document.getElementById('dgVideoStatus');

  // Base (CSS-pixel) size of the 3D canvas as first initialized — used only
  // to work out the chart's native aspect ratio, never touched/resized.
  const baseW = dg3D.baseW || dg3D.renderer.domElement.width;
  const baseH = dg3D.baseH || dg3D.renderer.domElement.height;

  const chartW = preset.chartW;
  const chartH = Math.round(chartW * (baseH / baseW));
  const totalH = Math.round(chartH / 0.78); // notes strip below, same proportion as the on-screen preview
  const totalW = chartW;
  const uiScale = totalW / 640; // scale captions relative to the original 640px-wide design

  // Offscreen recording canvas — this is what MediaRecorder actually
  // captures, sized at the full export resolution.
  const recCanvas = document.createElement('canvas');
  recCanvas.width = totalW;
  recCanvas.height = totalH;
  const ctx = recCanvas.getContext('2d', { alpha: false });

  // IMPORTANT: render the rotation on its OWN hidden renderer instead of
  // resizing the live interactive chart's renderer. The live chart has its
  // own continuous animate loop (dg3DAnimate) — if we blow up dg3D.renderer
  // to 4K, that loop keeps rendering 4K frames too, which is what made the
  // whole page (including the live preview) lag during export. Antialiasing
  // is also switched off here: it's the single biggest GPU cost at high
  // resolution and isn't necessary for a compressed, moving video.
  let capRenderer;
  try {
    const capCanvas = document.createElement('canvas');
    capRenderer = new THREE.WebGLRenderer({ canvas: capCanvas, antialias: false, alpha: false, preserveDrawingBuffer: true, powerPreference: 'high-performance' });
    capRenderer.setPixelRatio(1);
    capRenderer.setSize(chartW, chartH, false);
    capRenderer.setClearColor(0xffffff, 1);
  } catch (e) {
    toast('Could not set up the recording renderer: ' + (e && e.message ? e.message : e), 'error');
    return;
  }

  // Pause orbit controls and remember the starting rotation so we can spin
  // the chart ourselves at a steady rate for a clean, predictable loop.
  // (This still moves the shared dg3D.group, so the live chart behind the
  // modal will visibly spin too — same as before — but rendering itself
  // stays cheap because dg3D.renderer's own resolution is never touched.)
  const hadControls = !!dg3D.controls;
  if (hadControls) dg3D.controls.enabled = false;
  const startRotY = dg3D.group ? dg3D.group.rotation.y : 0;

  function disposeCapRenderer() {
    try {
      capRenderer.dispose();
      const gl = capRenderer.getContext();
      const ext = gl && gl.getExtension('WEBGL_lose_context');
      if (ext) ext.loseContext();
    } catch (e) { /* best-effort cleanup */ }
  }

  function cleanup() {
    if (hadControls) dg3D.controls.enabled = true;
    disposeCapRenderer();
  }

  function finishUI() {
    dgVideo.recording = false;
    if (btn) { btn.disabled = false; btn.textContent = 'Record & Download'; btn.style.opacity = '1'; }
    if (status) status.textContent = '';
  }

  const stream = recCanvas.captureStream(fps);
  let recorder;
  try {
    const mime = MediaRecorder.isTypeSupported('video/webm;codecs=vp9') ? 'video/webm;codecs=vp9' : 'video/webm';
    recorder = new MediaRecorder(stream, { mimeType: mime, videoBitsPerSecond: preset.bitrate });
  } catch (e) {
    toast('Could not start the video recorder: ' + (e && e.message ? e.message : e), 'error');
    cleanup();
    return;
  }

  const chunks = [];
  recorder.ondataavailable = e => { if (e.data && e.data.size) chunks.push(e.data); };
  recorder.onerror = () => {
    toast('Recording hit an error — try a lower quality.', 'error');
    if (dgVideo.raf) cancelAnimationFrame(dgVideo.raf);
    finishUI();
    cleanup();
  };
  recorder.onstop = () => {
    cleanup();
    finishUI();
    // A stalled/overloaded encoder can come back with only a few bytes —
    // that's the "downloaded file won't open" failure mode. Catch it here
    // instead of handing the user a broken .webm.
    const totalBytes = chunks.reduce((n, c) => n + c.size, 0);
    if (totalBytes < 2000) {
      toast('Recording didn\'t produce a usable video — try a lower quality or shorter duration.', 'error');
      return;
    }
    const blob = new Blob(chunks, { type: 'video/webm' });
    pdfedDownloadBlob(blob, dgExportFilename('webm'));
    toast('Rotating video downloaded', 'success');
    dgCloseVideoExportModal();
  };

  dgVideo.recording = true;
  if (btn) { btn.disabled = true; btn.style.opacity = '0.6'; }
  const startTime = performance.now();
  recorder.start(250); // periodic chunks rather than one at the very end, so an interrupted recording still yields whatever was captured

  const frameInterval = 1000 / fps;
  let lastFrameTime = 0;

  function frame(now) {
    // Pace draws to the chosen export fps rather than raw rAF cadence.
    if (now - lastFrameTime < frameInterval - 1) {
      dgVideo.raf = requestAnimationFrame(frame);
      return;
    }
    lastFrameTime = now;

    const elapsed = (performance.now() - startTime) / 1000;
    const progress = Math.min(elapsed / durationSec, 1);
    if (dg3D.group) dg3D.group.rotation.y = startRotY + progress * Math.PI * 2;
    if (dgHologramOn() && dg3D.group) dg3DHologramFlicker();
    capRenderer.render(dg3D.scene, dg3D.camera);

    ctx.fillStyle = '#0A0F1E';
    ctx.fillRect(0, 0, totalW, totalH);
    ctx.drawImage(capRenderer.domElement, 0, 0, chartW, chartH);
    dgVideoDrawNotes(ctx, recCanvas, chartH, uiScale);
    if (window.sarvarcApplyFreeWatermark) sarvarcStampCanvasWatermark(recCanvas);

    if (btn) btn.textContent = 'Recording… ' + Math.ceil(durationSec - elapsed) + 's';
    if (status) status.textContent = Math.round(progress * 100) + '% · ' + (qualityKey === '2160' ? '4K' : qualityKey + 'p') + ' · ' + fps + 'fps';

    if (progress < 1) {
      dgVideo.raf = requestAnimationFrame(frame);
    } else {
      recorder.stop();
    }
  }
  dgVideo.raf = requestAnimationFrame(frame);
}

window.dgOpenVideoExportModal = dgOpenVideoExportModal;
window.dgCloseVideoExportModal = dgCloseVideoExportModal;
window.dgStartVideoRecording = dgStartVideoRecording;

